/* 令和2年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20201009-4","meetingId":"r02-c-settlement","date":"2020年10月9日","dateIso":"2020-10-09","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３９分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を167件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"目を含む質問を行う委員の質問を先行して行い、該当の質問が終わり次第、品川区保健所長をはじめとした関係理事者には退席していただきますので","agenda":"目を含む質問を行う委員の質問を先行して行い、該当の質問が終わり次第、品川区保健所長をはじめとした関係理事者には退席していただきますので","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、２６９ページ、健康づくり支援事業に関連してと、粗大ごみの中継所に関連して質問したいと考えています。健康づくりでそういうことをやっていくことをどんどん進めていただきたいと思っているわけでありますけれども、それについてのお考えをお聞かせください。","respondent":"高山健康課長","answer":"自宅で気軽に取り組める運動ということで、まずはそのような取組みをしています。ご提案のケーブルテレビなどいわゆる映像系の可能性については、非常に高いと考えておりますので、今後検討してまいりたいと考えております。","voiceIndex":6,"id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問","question":"動画サイトの話は分かるのですけれども、ラジオ体操があるじゃないですか。あれは高齢者の方も必ずその時間になったらつけるというぐらい結構分かっているわけですね。この回数の問題もあるのだけれども、ではケーブルテレビをつけていただいて、１時間に１回ぐらい、例えば３分の短いコンテンツでもいいのだけれども、それも例えば音楽を入れ込んで、その音楽に合わせて何かやる。","respondent":"高山健康課長","answer":"ご提案のケーブルテレビなどは、いわゆる放送時間帯なども工夫しながら固定的に放送することも可能ですので、そうした映像につきましては、当面続きますこのコロナ禍における対応として非常に有効だと考えておりますので、引き続いて検討してまいりたいと考えております。","voiceIndex":8,"id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"粗大ごみ中継所に関連してというのは、旧東品川清掃作業所について伺いたいと考えています。我々の会派としてはもう２年も３年も前から、ここは用途制限が解除される日が決まっているのだから、そこの部分についてはもう計画を策定して、要は基本設計ぐらいはもうやってしまって、用途制限が解除された後すぐに工事にかかれるぐらいのことをしてくださいという要望をずっと出してきました。","respondent":"佐藤企画調整課長","answer":"旧東品川清掃作業所の検討調査の現状です。現時点におきましては鉄道事業者との調整を行っておりまして、委員ご指摘のとおり、鉄道建設工事というところでそういった取扱い指針や地下構造物の影響について確認するなど、解体工事を行った場合の課題の抽出を行っているところです。","voiceIndex":10,"id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そこら辺のところももちろんお考えになってやっていらっしゃるのだろうと思うけれども、その辺の二重投資をどうしていこうか。それはもう検討委員会を作って、こういう方向性でやっていく。けれども、二重投資を踏まえるのか踏まえないのかは別だけれども、そういう部分でお金をかけたとしても、何か利用していこうとされているとか、そこら辺のところももう一回状況を教えていただきたいと思います。","respondent":"佐藤企画調整課長","answer":"今後の検討委員会の設置も含めた検討の進め方ですが、本格活用に向けましては地元の意見もしっかりとお聞きして、検討委員会の設置も含めて様々な手法を考えていきたいと考えております。","voiceIndex":12,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひよろしくお願いしたいと思います。例えば期間が３年ぐらいかかるということ、３年間の間に今言ったオリンピックがあるから、半年。これはせっかく品川区の財産でもあるわけでありますから、そういう貸す方法を幅広く考えていくことが私はありなのかなと思っていて、ぜひそういうことも踏まえて考えていただきたいと思いますが、その部分について、最後にそこだけもう一点お聞かせください。","respondent":"佐藤企画調整課長","answer":"施設の有効利用の観点での検討ですが、私どもも歳入の確保の観点は常に持っておりますので、解体までの期間については、有効に活用していくことを様々な手法を用いながら検討していきたいと考えております。","voiceIndex":14,"id":"exchange-005"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、２８１ページの３目保健予防費の感染症対策事業に関連して、新型コロナウイルス感染症について、現状、区の取組みについて、順次お伺いしていきたいと思います。品川区における新型コロナウイルス感染症の流行の現状についてお伺いいたします。コロナウイルス検査の陽性者数の推移、現在の状態と第二次流行となった２０２０年６月以降の経過について、ご報告をお願いいたします。","respondent":"鷹箸保健予防課長","answer":"特に先日１０月７日は東京都の報告数の１０分の１が品川区からの報告ということで、ちょっと驚いているところになります。","voiceIndex":17,"id":"exchange-006"},{"speaker":"鈴木（博）委員","kind":"質問","question":"区内医療機関に入院している患者数の推移はいかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"８月に入りまして、これまで一番入院患者の数が多かったのが８月９日で６８名ですが、今、先ほどお話ししたように症状がある方の報告が続いておりまして、１０月８日でまた５１名ということで、また入院が必要な患者が増えている状況があります。","voiceIndex":19,"id":"exchange-007"},{"speaker":"鈴木（博）委員","kind":"質問","question":"検査陽性者は、新型コロナウイルス感染症が指定感染症のため原則入院ということになりますが、また増えてきているというお話なのですけれども、検査陽性者の振り分けは現在どのように行われているのでしょうか。日本財団が品川区に療養施設を整備しているという報道が行われておりますが、この施設に関しても現在どのような状態になっているのかお知らせください。","respondent":"鷹箸保健予防課長","answer":"本来は本日オープンする予定だったということなのですけれども、台風の影響もありまして、来週からオープンということを聞いております。","voiceIndex":21,"id":"exchange-008"},{"speaker":"鈴木（博）委員","kind":"質問","question":"新型コロナウイルス感染症を抑え込んだと評判になった国や地域でも、続々と再流行の報告も相次いでいます。新型コロナウイルス感染症対策について、診断、検査、隔離政策、治療薬について、順次区の見解をお伺いしていきたいと思います。診断、検査についてお伺いします。現在新型コロナウイルス感染症の診断に用いられているＰＣＲ検査について、ごく簡単にご説明をお願いいたします。","respondent":"鷹箸保健予防課長","answer":"ＰＣＲ検査ですが、これはいわゆるウイルスの遺伝子の断片を増殖させて、あるかどうかを調べるもので、鼻咽頭ですとか咽頭、唾液などで検査をするわけですけれども、増幅して調べるために一定程度の時間が必要でございまして、最低でも五、六時間。","voiceIndex":23,"id":"exchange-009"},{"speaker":"鈴木（博）委員","kind":"質問","question":"新型コロナウイルス感染症では、感染者の大体３割から４割ぐらいが無症状ではないかと言われています。本年８月に、東京都世田谷区は「いつでも、誰でも、何度でもＰＣＲ検査」なるものを打ち出しましたが、この取組みは現在どうなっているのでしょうか。このような新型コロナウイルス感染症の診断、検査体制を脅かしかねない現在の情勢に対する区のご見解はいかがでしょうか。併せてご説明をお願いします。","respondent":"鷹箸保健予防課長","answer":"その理由といたしまして、大勢の人の検査を実施するには一人ひとりの検査をしていてはとても時間等もかかるということで、献血と同じ方式で、何人かの方の検体を混ぜて検査をして。","voiceIndex":25,"id":"exchange-010"},{"speaker":"鈴木（博）委員","kind":"質問","question":"よく分かりました。世田谷区医師会も８月２４日に、「報道されておりますいわゆる世田谷モデル事業と、世田谷区医師会ＰＣＲ検査センターは全く関係ありません。資料をお願いします。国立国際医療センターの忽那賢志医師も、「ＰＣＲ検査は鼻咽頭をぬぐった検体で陽性率は約６割と言われています。つまり１０回検査をしても、４回は陰性と出てしまいます。中央に５０ｍｌの滅菌遠沈管があります。","respondent":"鷹箸保健予防課長","answer":"こちらは、患者の体内に存在するコロナウイルスに対する抗体と抗原が反応するという性質を用いる検査でございまして、ＰＣＲ検査に比べますと非常に短時間、３０分程度で結果が出るのですけれども、あるウイルスが一定量ないと出てこないといったあたりで。","voiceIndex":27,"id":"exchange-011"},{"speaker":"鈴木（博）委員","kind":"確認","question":"スライドをお願いします。抗原検査は採取後１５分から３０分で結果が出ること、インフルエンザの迅速診断と同じで定性の場合は特殊な機器が要らなくて手軽に行えることから、現在広く一般に行われるようになってきています。したがって結果が疑義ある場合は、今課長がおっしゃったように、必ずＰＣＲ検査を併用して確認しなければいけないと言われています。次に、治療について伺います。","respondent":"鷹箸保健予防課長","answer":"１１月以降と聞いておりますが、日本で開発されましたアビガンもようやく使えるようになる見込みだと聞いてあります。","voiceIndex":29,"id":"exchange-012"},{"speaker":"鈴木（博）委員","kind":"意見","question":"９月９日、集中治療医学会は「ＣＯＶＩＤ－１９薬物療法に関するRapid/living Recommendations」を発表し、新型コロナウイルス感染症の軽症にはファビピラビル、これはアビガンのことですが、これを弱く推奨、中等症から重症にはデキサメタゾンを強く推奨、レムデシベル、これはベクルリーという商品になっていますけれども、これを弱く推奨というガイドラインを発表しました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"私からは、２８１ページ、猫の不妊・去勢手術費助成、２９９ページ、企業活力強化支援事業に関連して、テレワーク事業についてお伺いいたします。初めに、産業経済費のほうから伺ってまいります。途中経過で１３３件と伺いました。当初予算は１００件１億円というところが、１３３件使われていると確認いたしましたが、現状はどうかということを教えていただきたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"業種につきましては、一番多いのが卸売・小売業、それからサービス業、情報通信業などがこちらの対象として申込みをいただいているところでございまして、比較的にそういうことになじみ深いところもあるのですけれども、今まで多分経験したことのない。","voiceIndex":33,"id":"exchange-014"},{"speaker":"新妻委員","kind":"質問・要望","question":"ニーズを見極めていただきたいと思いますのと、本当にリモートワークをするという環境がないままで進めている方も多くいらっしゃいます。民生費でも取り上げました。そこに当てはまらない個人におけるこのテレワーク環境を整えるための支援を、ぜひ品川区でもお願いしたいと考えていますが、見解を伺います。","respondent":"遠藤商業・ものづくり課長","answer":"今回１２月を予定しているのですが、中小企業を対象にした、今回いろいろと導入していく部分でのまず入門というか、セミナーというか、そういう形でやらせていただく予定で、今進めているところです。","voiceIndex":35,"id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひ研究、検討を進めていただきたいと思います。次に、猫の不妊・去勢手術費助成についてお伺いいたします。２０１９年度の予算の執行率は確認いたしましたが、現在の本年の現状をまず確認させていただきたいと思います。もしかしたら各地区１０頭という予算付けではないのかもしれませんが、柔軟に予算を使わせていただけるような対策をと思いますが、いかがでしょうか。","respondent":"鈴木生活衛生課長","answer":"その際に手続きやルールを少ししっかりと詰めた上で、各地区の意見も聞きながら進めたいということで、今検討をしています。","voiceIndex":37,"id":"exchange-016"},{"speaker":"新妻委員","kind":"質問・要望","question":"どうぞ前向きなご検討をお願いしたいと思います。ぜひご検討いただきたいと思いますが、いかがでしょうか。このボランティア活動は、既に町会や自治会の皆様にはアピールを行っていただいて周知をされているところではありますが、まだまだ地域によってはご理解がないような地域もあると伺いました。より一層の地域の皆様への周知をお願いしたいと思いますが、いかがでしょうか。","respondent":"鈴木生活衛生課長","answer":"ただ地区も広がってまいりましたし、腕章の数も今だんだん不足してきていますので、改めて各地区の意見を聞いた上で、使いやすく、また周りの方にも認識していただけるようなものを用意したいと考えております。","voiceIndex":39,"id":"exchange-017"},{"speaker":"新妻委員","kind":"質問・要望","question":"よろしくお願いします。もう一つ、区から貸出しの捕獲器がいつも借りられないという声があります。拡充を求めます。さらに不妊・去勢手術後はすぐにリリースすることができません。預かっていただく方への何かしらの支援をお願いしたいという声もありますが、いかがでしょうか。","respondent":"鈴木生活衛生課長","answer":"リリース後の対応につきましても、実際に受け入れていただく方の確保というのが課題ですが、進めていきたいと考えております。","voiceIndex":41,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は２７９ページの感染症予防費、新型コロナウイルス対策について伺いたいと思います。感染拡大防止と社会経済活動を両立させる最大の鍵はＰＣＲ検査の抜本的な拡充で、無症状の感染者を見つけ出して保護・隔離をすることだと思いますけれども、いかがでしょうか。やはりＰＣＲ検査を大規模に拡大して、無症状の感染者の保護・隔離をするということではないでしょうか。いかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"誰でも検査をして、その陽性者を見つけるということがそのまま感染拡大防止につながるかというところは、非常に意見の分かれるところですが、保健所といたしましては、現在国の方針にのっとりまして、必要な場合にはいち早くかなり対象を広げて検査を実施しているところです。","voiceIndex":44,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そのような中で、ＰＣＲ検査については我が党の一般質問で、新型コロナウイルス感染症であっても、７０％の人に陽性が出るといった検査の特性があるという部長の答弁もありましたが、この７０％の人に陽性が出るというのは、３０％は感染をしていても陰性に出るということで言われたのだと思うのですけれども、これは厚生委員会の中でもちょっとした論争にもなったのですが。","respondent":"鷹箸保健予防課長","answer":"これにつきましては国の方針が今後変わることももちろんあるかもしれませんので、その際にも国の方針にのっとって、必要な人に必要な検査をいち早く実施していくということで考えております。","voiceIndex":46,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところで、区民に最も身近なところで接している品川区ですから、実態を見ながら意見を述べていくということも必要ではないかと思います。どんどん広がってきたということに対して区としてどう捉え、今後どうすべきと考えているかについてもお聞かせいただきたいと思います。","respondent":"鷹箸保健予防課長","answer":"高齢者施設につきましては、対象の方がもし感染した場合には重症化になりやすいということもありまして、初めからかなり広く対象を取って検査をさせていただいておりまして、この方針につきましては、最終的にもちろん決めるのは保健予防課長ではありますけれども。","voiceIndex":48,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今後どのようにこれを抑えていくかというお考えがありましたら、お聞かせいただきたいと思います。先ほどもありましたけれども、感染を恐れて外出をしないという高齢者もたくさんいます。そのような中で、足腰の衰えと、認知機能の低下が心配されるという声もたくさん聞いております。そういう点では、そこまで検査の拡大を区としても行い、国に求めていくべきではないかと思いますが、いかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"重症化しやすい高齢者につきましては、今委員がお話しされたような方針が国から出たことは十分認識しております。","voiceIndex":50,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はこういうところにまで拡大してこそ、希望にも応えられるし、市中感染の状況の把握にもつながっていくと思います。今回１回だけ初めてやることになりましたけれども、これは本当に大きな前進だと思いますが、さらに定期的に、そして対象拡大も含めてぜひやっていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-023"},{"speaker":"筒井委員","kind":"質問・要望","question":"私からは、２８５ページ、航空機騒音調査、３０３ページ、消費者啓発費、時間があれば３０１ページ、商店街活性化事業費についてお伺いいたします。これと同様のものが昨年１０月に港区で議決されておりまして、今回２回目ということになっております。この２つの小学校にしたという選定理由と、またほかの地点への、例えば大井町などに増設のお考えはあるのでしょうか、お伺いします。","respondent":"鈴木都市計画課長","answer":"この２地点の測定局を設けた経緯ですが、基本的にはこれは国の事業ですので、測定を行う、あるいは測定をする場所を決めるというところは、国のほうで計画が出された段階から検討を進めておりまして、実際に３地点で、今国のほうが測定局を設置しています。","voiceIndex":54,"id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"特に台場小学校は７４.５デシベルぐらいになっていないといけないのですけれども、それを超える数値が出ております。そうしたことで、今回品川区独自の測定結果と、国土交通省の事前に発表している騒音の推計値と比較して、区としてのこの測定結果の評価についてどうお考えなのかを伺います。","respondent":"鈴木都市計画課長","answer":"測定結果の公表、４月分を９月３０日から公表を行いまして、これを今後順次測定結果を公表してまいりますが、基本的に国のほうは事前に台場小学校、立会小学校付近での推計騒音値というのは公表してございません。","voiceIndex":58,"id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。逆に区の独自の測定のもので、最小値が５０デシベル台後半のものもあるのですけれども、国が設置している南部下水道事務所品川出張所とかで測っているところと比べて、５０デシベル台後半というのはちょっとかなり低く数字が出ているのかと思っているのですが、その理由というか、今回の品川区独自の測定方法の信頼性というか精度は大丈夫なものなのでしょうか。","respondent":"鈴木都市計画課長","answer":"そうしたところで、２ルートの低い方の音を結果的に拾って、それが公表されているということで、区としては確認をしています。","voiceIndex":60,"id":"exchange-026"},{"speaker":"筒井委員","kind":"質問・要望","question":"しっかりと今後も精度を高めて測定をしていただきたいのですけれども、いずれにせよ小学校近くを飛行機が通っているという事実、また小学校でこのような騒音測定をしなければならなくなってしまったというこの事態をやはり重く受け止めるべきと考えております。かなり異常な事態だと考えております。そのことについてどう受け止めるのか。区が知り得る国の認識というのをお聞かせください。","respondent":"鈴木都市計画課長","answer":"騒音測定を区が実施しているということは、当然ながら国も認識してございまして、この測定結果については国の測定結果とともに情報は共有して、様々な意見交換をこれから行っていきたいです。","voiceIndex":62,"id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"国はあまり小学校の近くを通っていることは気にしていないということなのでしょうか。品川区は国に対して固定化の回避といって取り組んでおりますけれども、こうした小学校近くを通っている、子どもたちが犠牲になっている、環境配慮やＳＤＧｓに矛盾するといったことを、やはり固定化回避の理由の一つとして国にしっかりと伝えるべきだと思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"もう一点お尋ねの環境影響ですが、これについても国のほうでは、空港周辺で環境に対する、大気に関する調査は事前にもう行っておりまして、これは継続して行っていくというところで聞いてありますので、当然ながら環境基準というものもありますので。","voiceIndex":64,"id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひよろしくお願いします。大人の都合で子どもが犠牲になるということはぜひ防いでいただいて、国に対してゼロ回答は許さないと。早期に品川区上空を通るルートはやめていただくということを国に伝えていただきたいと思います。よろしくお願いします。そうしたことで、まず品川区でネットワークビジネスの被害や相談件数など、どのぐらい把握されているのでしょうか。状況をお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"すみません、特殊販売の令和元年度の数字になりますけれども、いわゆるマルチあるいはマルチまがいという部分につきましては、昨年３３件となっております。","voiceIndex":66,"id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"それは多いと考えているのでしょうか。その認識と、これ以上の被害をぜひ食い止めていただきたいので、今後こういうのが多発すると考えられますので、注意喚起や啓発、救済制度や相談窓口の周知の徹底という対策を行っていただきたいのですけれども、品川区としてはいかがお考えでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"今後につきましても、先ほどの成人年齢が下がるという部分も含めまして、特になりたての方について周知啓発を進めていきたいと考えています。","voiceIndex":68,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"本当に特殊詐欺のようにはっきりと被害が分かりにくい。そして、被害を受けるのは少し若い方が多いので、やはりどうしても相談というのも後手後手に回ってしまうことがありますので、広報しながわ等々でそうした周知の徹底をぜひお願いしたいと思います。よろしくお願いします。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、２７２ページの母子保健費全般から２つ伺います。それから２９７ページの産業経済費から就業支援について伺います。最初に２７２ページ、母子保健費全般から伺います。それから、子育て世代包括支援センターとして保健センターと子ども家庭支援センター、両方が位置づけられているのですけれども、その役割の分担はどのようにお考えか伺います。","respondent":"間部品川保健センター所長","answer":"ただこの間５年が経ちますので、いろいろな課題も出てきていますので、なお一層子育ての分野と連携をして、事業の実施に努めていきたいと考えています。","voiceIndex":72,"id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"その連携型というところに課題があるのかと。品川・生活者ネットワークは２０１６年から、区のネウボラ事業は当事者から見ると相談が途切れてしまうことを指摘しております。制度は隙間なくちゃんとあるのです。その辺がやはり利用者目線で考える子育て世代包括支援センターに求められているのだと思います。そういう当事者から見た一貫した支援の再構築が必要と考えますが、見解を伺います。","respondent":"間部品川保健センター所長","answer":"子育て支援ということで考えますと、当然１８歳や２０歳ということで、それぞれその世代、時期によって課題が異なるということで、私どもは妊娠期の届け出のネウボラ相談を実施することによって、妊娠期から産褥期にあたる部分についての支援を主に担っておりまして。","voiceIndex":74,"id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"課題は認識しておられるようなので、やはり法律が違うわけですから、そこで制度が別々にあって、そこをトータルで使うのが利用者ですので、その辺の課題をまず洗い出していただいて、どうやったら当事者の情報が伝わって相談しやすくなるか、ぜひその目線で検討をしていただければと思います。これは要望にとどめます。分かりやすい周知を何とか自治体として工夫できないものでしょうか、見解を伺います。","respondent":"高山健康課長","answer":"一義的には委員ご紹介のとおり、国・都において責任を持ってこの仕組みが紹介されることで、支援として行き渡るということが理想的ではありますが、品川区の一つの広報といたしましては、品川区のホームページではありますが。","voiceIndex":76,"id":"exchange-034"},{"speaker":"吉田委員","kind":"質問","question":"厚生労働省はちゃんと周知すべきだというのは私も同感です。新しいチラシを出しているようですので、せめてこれを品川区に取り寄せて、各窓口の目につきやすいところに置くとか、事業者も品川区民が品川区内で働いているわけでもないですけれども、品川区内の事業者にこういう周知を協力してもらうとか、そういう工夫はできないものでしょうか、伺います。","respondent":"高山健康課長","answer":"妊娠中の様々な支援メニューについては、様々なチラシなどは健康課の窓口、それから保健センターの窓口などに置かせていただいています。既に新しいものが出来上がったとお伺いしましたので、そうしたものを見する中で、有効な支援策の広報について検討してまいります。","voiceIndex":78,"id":"exchange-035"},{"speaker":"吉田委員","kind":"確認","question":"どうぞよろしくお願いいたします。調査の目的は、電力調達の現状や方針を確認し、それをきっかけに自治体の再生可能エネルギー利用を促すためです。１０年後に実現するための方針などがあれば伺います。歳入のときに、本庁舎の電力について質疑がありましたが、品川区の環境政策実現ならばまず本庁舎ではないのか、環境課として、本庁舎の電力ということへの働きかけはないのでしょうか、伺います。","respondent":"提坂環境課長","answer":"今後、再生可能エネルギー、２０５０年１００％に向けて頑張っているところですけれども、手順としてはまず品川区の職員のエコアクトというのを定めていまして、その中で職員がＣＯ２削減に各自取り組むということでうたってあるのですけれども。","voiceIndex":80,"id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"今後は再生可能エネルギーの内容までぜひ検討してほしいと思います。区が直接契約しているものについては、契約書を確認しましたところ、全て仕様書として再生可能エネルギー１００％のメニューを選んでいました。今後はぜひその点にも注目していっていただきたいと思います。これだと電気の素性も明らかでよいと考えるのですけれども、以前もこのような事例をご紹介しましたが、見解を伺います。","respondent":"提坂環境課長","answer":"電力の調達を行う中で、契約の中で仕様書に再生可能エネルギー１００％ということをうたってはありますけれども、今後環境とかを分析している専門機関などとも相談しまして、その辺をもっと細かく指定できないかとか、そういうことは検討してまいりたいと思います。","voiceIndex":82,"id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"要望にとどめます。次に、産業経済費の就業支援費で伺います。２定の一般質問で、新型コロナウイルス感染症の影響が出始めた後の就業センターとわかもの・女性就業相談コーナーでの相談の数と、就職につながった数を伺いました。その後の相談件数と就職につながった実績を伺いたいと思います。品川・生活者ネットワークとしては、雇用者への支援だけではなく、職を失った人への支援を求めています。","respondent":"遠藤商業・ものづくり課長","answer":"サポしながわの関係なのですが、しながわ活力応援給付金等で国・区からの委託業者が雇用が必要ということで、３３名を一応コールセンター事務補助という形で雇わせていただいた事例があります。","voiceIndex":84,"id":"exchange-038"},{"speaker":"横山委員","kind":"質問","question":"私からは、２７３ページ、母子健康診査費、２７５ページ、母子保健指導事業費、２６９ページ、健康づくり支援事業費についてお伺いします。１点目に、母子健康診査費についてお伺いいたします。予算では母子健康手帳の交付時に配布するマタニティバッグ、マタニティストラップおよび母子健康手帳用ビニルカバーが計上されていますが、出費を抑える工夫をしていただいているという認識でよろしいでしょうか。","respondent":"高山健康課長","answer":"費用を抑える工夫という点ですが、企業の広告を入れることを前提に無償で提供していただいている部分がございまして、委員がご紹介になった母子手帳を入れるバッグでありますとか、あるいは手帳のカバーなどは現在のところは無償で提供していただいて有効に活用しています。","voiceIndex":88,"id":"exchange-039"},{"speaker":"横山委員","kind":"質問・要望","question":"こちらは今後もしキャンペーン等が終了した場合に、無償提供やカバーの裏表紙などに広告掲載をしていただくような民間事業者を広く募集していただきたいと思うのですけれども、いかがでしょうか。次に、妊娠届の際のアンケートについてもお伺いいたします。コロナ禍における女性の心と体のセルフケア方法について、保健センターではどういった場面で女性の健康に関する相談を受けていますでしょうか。","respondent":"高山健康課長、間部品川保健センター所長、榎本荏原保健センター所長","answer":"一応必要な予算として、そうしたものを区で購入する予算は計上していますが、今後も出費が抑えられるよう。ご家庭の状況とか支援の度合いとか、経済的な部分も含めて必要だと認識をしておって今実施をしているです。心と体の女性の健康相談ですけれども、特別に実施しているわけではないのですが、保健センターでは様々な場面でご相談に応じています。","voiceIndex":90,"id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"健康づくりのところです。やせの問題、加齢による筋力低下の体への影響、また癖による体のゆがみなどの姿勢について、学校保健との連携をしていただきたいのですが、衛生費では要望とさせていただきまして、現在の状況については教育費のところでお聞きしたいと考えています。３点目に、母子保健指導事業費についてお伺いいたします。母親学級、父親学級、両親学級のカリキュラムの詳細を教えてください。","respondent":"榎本荏原保健センター所長、間部品川保健センター所長","answer":"女性は月経、妊娠、出産など女性ホルモンに関わる変化がありまして、心身共に不安定になるなど、女性特有の健康問題があることについて正しい知識の復旧啓発などが必要だということは認識しております。私からは母親学級等についてご答弁します。母親学級につきましては、妊婦を対象に、妊娠、出産、そして育児に関する知識の習得と地域の仲間作りを目的に実施をしているもので、１開催３日コースで実施をしているものです。","voiceIndex":94,"id":"exchange-041"},{"speaker":"横山委員","kind":"質問・要望","question":"ちょっと時間がないので、産褥期の問題なのですけれども、女性が恋人、妻、母へと役割が変わっていくにあたって、事前の知識というのを知っていたほうがいいと思いますので、ぜひアットホームの作り方講座など、そういった内容でもいろいろと考えていただけたらということで、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-042"},{"speaker":"西村委員","kind":"質問","question":"衛生費より、２７５ページ、すくすく赤ちゃん訪問事業、不妊治療助成事業。２７９ページ、子宮がん検診、乳がん検診。産業経済費より、共通商品券普及促進事業について、順不同で時間が許す限り伺ってまいります。不妊治療助成事業について伺います。菅首相は所信表明演説で、２年を目途に不妊治療の保険適用を実現すると明言しました。は不妊治療の助成制度を設けて以降、近年の傾向をお知らせください。","respondent":"高山健康課長","answer":"制度としては一般不妊治療制度と、それから特定不妊治療制度という２つの仕組みを持っておりまして、近年の傾向性としては、全体で見ますと昨年度よりも件数のほうは減っているかに見えるのですが、いろいろな制度のカバーする年齢層の影響もありますので、全般的に見ますと。","voiceIndex":99,"id":"exchange-043"},{"speaker":"西村委員","kind":"質問","question":"現在全国で不妊治療をしている方が約１０万人と言われている中、保険適用が実現すれば不妊治療への敷居が低くなり、スタートアップが早くなるのではないかと期待する当事者の方の声を伺いました。現在の事業の成果をどのようにお考えでしょうか。お聞かせください。","respondent":"高山健康課長","answer":"そうした意味では、これは年齢との戦いというようなお話も伺いますので、できるだけ早くこの治療に着手していただいて授かっていただくといったことは、私どもとしても願うところですので、そういう意味では、特にいわゆる特定不妊治療に関しましては。","voiceIndex":101,"id":"exchange-044"},{"speaker":"西村委員","kind":"質問","question":"２年を目途にと首相もおっしゃられておりますように保険適用は十分な議論が必要だと思いますが、晩婚化が進んでいる昨今、適齢期での治療を促進できる可能性もあるため、区民の方々への正しい知識の周知も必要だと考えています。不妊治療に関しまして、現在区からご案内しているツールや講座、その他手法がありましたら教えてください。","respondent":"高山健康課長","answer":"主に健康課では、そうした不妊治療に関わります助成制度、仕組みについてのパンフレットなども置かせていただいておりますので、そうしたものをお手に取っていただいて、早くそうした治療のほうに着手していただければと考えております。","voiceIndex":103,"id":"exchange-045"},{"speaker":"西村委員","kind":"意見","question":"ぜひとも都と連携しながら、助成制度も周知をお願いしたいと考えていますが、不妊治療はストレス、心身への負担がつらいとおっしゃる方が多く、ケアサポートのほうも区で何かできないかということを考えています。昨日の新聞で、厚生労働省が令和４年の診療報酬の改定に合わせて、適用拡大できるよう検討を進めていくといったようなニュースも出ておりました。","respondent":"高山健康課長","answer":"不妊・不育のホットラインなども東京都のほうで設けていらっしゃいますので、まずはこうしたものの仕組みを十分にご活用いただいて、いろいろな正確な情報を早く入手していただければと考えております。区独自の支援につきましては、今後の課題と受け止めております。","voiceIndex":105,"id":"exchange-046"},{"speaker":"西村委員","kind":"意見","question":"不妊治療はなかなか人に言えない、相談ができないなどの悩みが深く、皆様ご存じだと思うのですが、排卵期になると毎日病院に行かなければなりませんし、１時間単位の時間休暇ですとか、勤務時間が変更できるですとか、会社の理解も必要ですので、仕事と治療の両立にも社会の理解と制度整備の必要を感じています。このあたりに関してもご意見をお聞かせください。","respondent":"高山健康課長","answer":"そうした不妊治療に取り組みやすい社会的な機運、企業内における理解というところもひとつ大きな課題かと考えております。","voiceIndex":107,"id":"exchange-047"},{"speaker":"西村委員","kind":"質問","question":"続きまして、子宮がん検診、乳がん検診について伺います。現在品川区では、子宮がんは２０歳以上、乳がんは３４歳以上の偶数年齢の女性区民の方を対象に検診を行っていると理解をしております。なかなか難しい点もあろうかと思いますが、そのあたりも含めまして可能かどうか、まずはご所見をお聞かせください。","respondent":"高山健康課長","answer":"実際に４０歳以上が、この両方が全て対象になってくるかと思うのですが、封書で乳がん・子宮がんの健診の受診票を同封する形で送らせていただいておりますので、その中にはそれぞれ受診できる医療機関の紹介などのチラシなども入れておりますので。","voiceIndex":109,"id":"exchange-048"},{"speaker":"西村委員","kind":"質問","question":"婦人科検診ということで、同時に受けられたらいいというお声が多かったものですから、お伝えさせていただきましたが、また引き続きご検討をお願いしたいと思います。一方、目黒区では混乱を来したというような声も伺っておりまして、品川区は長くプレミアム付商品券の発行を続けてこられて、これまでの分析も含めまして他区との比較など、どのように評価をされているのかお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"今年度実施しましたいわゆる特別プレミアム付品川区内共通商品券についての答弁をします。今回３０％ということで、今までにないような形の金額で募集をさせていただいたところです。","voiceIndex":111,"id":"exchange-049"},{"speaker":"西村委員","kind":"質問","question":"今回特に利用者の幅が広がった印象があります。制服ですとか体操着など、学用品を購入するときにも計画的に利用しているという保護者の声が届いており、母親たちにも利用が広がっているように思います。商店街側、消費者、双方の反響はいかがでしょうか、お聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"消費者からのお話ですけれども、今回とにかく３０％をプレミアムとして乗せさせていただいたと。しながわ活力応援給付金などもございまして、そちらのほうの効果もありまして多くの方にご利用いただけたのかと感じるところです。商店街の反応です。","voiceIndex":113,"id":"exchange-050"},{"speaker":"西村委員","kind":"質問・要望","question":"インパクトが大変あったかと思います。政策要望でも会派よりお伝えしておりますが、９月での継続発行要望を改めてさせていただきたいと思います。事業者、店舗の皆様の経済的ダメージも今回このコロナ禍で大きかったものですから、最低でも３０％、１０億円相当の維持を改めて要望したいと思いますが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"今後の商品券の発行につきましての質問です。こちらにつきましては、また商店街連合会ともいろいろと協議などをしながら進めていきたいと考えております。","voiceIndex":115,"id":"exchange-051"},{"speaker":"西村委員","kind":"質問・要望","question":"コロナ禍においてなかなか経済の活性化がままならない中、プレミアム付商品券は区内経済効果が目に見えるのではないかと思います。次年度に向けてどのようにお考えかをお聞かせください。春に向けても区民、商店の皆様が元気になる施策として、ぜひご検討いただきたいと思いますが、そのプロセスにつきましてお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"繰り返しになりますけれども、商店街連合会などの意向を聞きながら、あるいはまた商品券以外でもほかの支援策なども検討しながら、うまい形で組み合わせたもので商店街の支援をさせていただきたいと考えております。","voiceIndex":117,"id":"exchange-052"},{"speaker":"西村委員","kind":"意見","question":"現在使った方に関しましては、分かりやすいということで、リピートしていらっしゃる率も高いのではないかと思っています。そのような具体的な区民の方の利用していらっしゃる動向をもし調査していらっしゃいましたら、どのように皆様がご利用かをお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"今回利用された店舗ですが、今回の３０％の部分についてはまだ十分な検証ができていないところではありますが、特徴といたしましては大型店では使えないですので、いわゆる個店を中心にお使いいただいているのかと感じているところです。","voiceIndex":119,"id":"exchange-053"},{"speaker":"西村委員","kind":"質問","question":"小さな商店にも行ってくださっているという区民の方の声を聞くと正直ほっといたします。区の経済活性化のためにも、ぜひとも続けて盛り上げていけたらと私も思います。前後してすみません。すくすく赤ちゃん訪問について伺わせてください。今現在コロナ禍における保健所訪問を控える方もいらっしゃると思います。すくすく赤ちゃん訪問の減少状況、それによるフォローアップの体制をお聞かせください。","respondent":"間部品川保健センター所長","answer":"ただ、そのフォローということではありますけれども、通常の保健師や助産師による電話相談や産後電話、また４カ月児健診再開後はそこでの個別相談などで、いろいろな事業を組み合わせてフォローを実施してきたです。","voiceIndex":121,"id":"exchange-054"},{"speaker":"西村委員","kind":"質問・要望","question":"私も様々な方法をお調べしたのですが、電話相談体制の構築、今後メールやＬＩＮＥでも相談ができること、オンラインでの外国人の方の多言語対応、交流施設とオンラインを組み合わせた支援の仕方を模索するなど、子ども育成課との連携部分もあるかと思いますが、産後の母親をどう支えるのか。出向けない方にも父親、母親ともに支援していける方法をぜひとも積極的に引き続きご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-055"},{"speaker":"せお委員","kind":"質問・要望","question":"私からは２７９ページ、感染症予防費から保健所の業務全般について、２７５ページ、母子保健指導事業費から母子手帳について、同じく２７５ページ、不妊治療助成事業についてお聞きします。感染症予防費です。そこで、保健所全般の業務の負担軽減に関わることを何点かお聞きします。東京都の調査において、１０代以下の重症化率、死亡率はゼロです。こちらは要望します。","respondent":"鷹箸保健予防課長","answer":"現在、区の電話相談の窓口に、不安のある方のお電話は一義的に入ってまいりますけれども、そこで症状がある方、あるいは濃厚接触者の方については、もうすぐに私どものほうで行政検査、そして様々な区内の医療機関であったり。","voiceIndex":126,"id":"exchange-056"},{"speaker":"せお委員","kind":"質問・要望","question":"様々、ＰＣＲ検査に関しては賛否があると思うのですが、区民の気持ちに寄り添った支援となるように要望いたします。次に保健所の業務、特に保健師の業務内容に関してです。保健師に関しても一度業務の切り出しを行うべきかと考えますが、見解を伺います。例えば障害者福祉課とも業務を分担し、連携をして取り組んでいくべきかと考えますが、そちらについても見解をお聞かせください。","respondent":"榎本荏原保健センター所長","answer":"母子保健、それから難病、精神保健ということで、委員からのご説明のあったようなあらゆる業務を行っているところですけれども、その中で、例えば母子保健業務もそうなのですが、健診や相談事業など様々な業務を行っている中で。","voiceIndex":128,"id":"exchange-057"},{"speaker":"せお委員","kind":"質問・要望","question":"次へ移ります。２７５ページ、母子保健指導事業費に関連して、母子手帳についてお聞きします。成長にはそれぞれ個人差があります。ですから、現在の母子手帳に加えて、小さな成長も大きく喜べるような工夫がなされている手帳があると、心から幸せを感じることができます。東京都のホームページでは、それを掲載して紹介しています。は区のホームページでもご紹介いただきたいと思いますが、見解を伺います。","respondent":"高山健康課長","answer":"今、ホームページなどで都がご紹介されているというお話も伺いましたので、そうした方々が区のホームページをご覧になったとき、必要と思われるものをご自身でダウンロードして使っていただけるような、そのような、より行き届いたホームページの掲載などは。","voiceIndex":130,"id":"exchange-058"},{"speaker":"せお委員","kind":"質問・要望","question":"はすぐにできるところから取り組んでいただきたいと思います。東京都には、妊娠期から学齢期まで使用できて、子どもの成長や健康に関する記入欄や、子育て情報を盛り込んだ、子供手帳モデルというものがあります。ぜひともこの包括補助を活用して、品川区独自の母子手帳やアプリ、冊子などを作成していただきたいと考えますが、見解をお聞かせください。","respondent":"高山健康課長","answer":"今後、そうした導入が他の区においても検討が進む中で、品川区においても、そうした母子健康手帳のよりよいものという形を模索してまいりたいと考えております。","voiceIndex":132,"id":"exchange-059"},{"speaker":"せお委員","kind":"意見","question":"母子手帳は障害がある子もない子も、どのお子さんでも成長を喜べるものであるべきだと考えます。次に、不妊治療助成事業に移ります。不妊治療助成の件数が、これは決算書にあったものですが、平成３０年度が７１０件に対し、令和元年度は６１０件となって減っています。先ほどご答弁の中で少しお話しされていましたが、いま一度詳しく、この減った理由をお聞かせください。","respondent":"高山健康課長","answer":"不妊治療助成の年度の推移という点でご説明します。平成３０年度と令和元年度の比較です。平成３０年度は７１０件ということで、決算書のほうに載っております。今年度の決算書をご覧いただきますと、６１０件ということでご確認いただけるかと思います。","voiceIndex":134,"id":"exchange-060"},{"speaker":"せお委員","kind":"質問","question":"理解いたしました。さらに報道では、その実現には早くて２年程度かかるという見方で、それまでの間は助成制度の拡充などで治療を支援したいということです。この不妊治療の保険適用が開始されるまでの約２年間に関しては、助成制度の拡充というお話があるわけですが、制度としてはどのように取り扱うご予定でしょうか。見解をお聞かせください。","respondent":"高山健康課長","answer":"区といたしましては、そのような動きと、何というのでしょうか、かぶることなくといいますか、その動きを捉えて、区としても必要な支援については、この２年間の間、どのような支援が必要かどうかについては、より拡充するよう検討してまいります。","voiceIndex":136,"id":"exchange-061"},{"speaker":"せお委員","kind":"提案","question":"不妊治療の２年間というものはとても大きいものですので、国の動向を待たずとも、様々な視点から区ができる支援を検討していただきたいと思っています。昨年の決算特別委員会でも提案させていただきました、不妊治療をされている方の交流の場を作ること、これは子どもを望んでいるけれどもできないという非常にセンシティブな悩みから、その間は開放される大切な時間です。","respondent":"高山健康課長","answer":"先進都市と申しますか、中核市レベルですと、そのような交流の場を提供しているというお話は伺っておりますので、そうした先進都市のお話なども伺いながら、どのような支援が適しているかということについては、引き続き検討してまいります。","voiceIndex":138,"id":"exchange-062"},{"speaker":"せお委員","kind":"質問・要望","question":"私は以前から、ネウボラは妊娠期からではなく、妊娠前からの支援にしていただきたいと常に申し上げております。不妊治療を経て妊娠、出産された方は、もちろんそれで終わりではないです。そこから子育てが待っています。そこも切れ目なくつながっておりますので、ぜひその辺も考慮したネウボラも要望して、終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":140,"id":"exchange-063"},{"speaker":"あべ委員","kind":"質問・要望","question":"１点は、この不妊治療助成の中で、男性不妊の件数がどの程度あるかということを把握されているかどうかということ、それから２つ目、保険適用、これは私も不妊治療の経験者として、国に保険適用を求める要望に関わってまいりましたが、今年になってようやく国が動き始めたということで大変喜んでおります。それから３点目です。はここまでお願いします。","respondent":"高山健康課長","answer":"それから３点目の様々な障害といいますか、負担についての区としての見解といいますか、支援という観点ですが、先ほどちょっとご説明の中でも申しましたけれども、現在都においての取組みなどもございまして、例えばそうしたフォーラム。","voiceIndex":142,"id":"exchange-064"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひ件数については、区で把握をしていただきたいと思いますが、改めてご答弁をお願いします。それと次に進みます。子宮頸がん予防接種なのですけれども、これの対象者の数、それから現在の接種の割合を教えてください。子宮頸がんによる全国の年間の死亡者数が分かれば、ごめんなさい、これはいいです。品川区内の話でいきます。接種対象者と接種の現在の数、そして割合を教えてください。","respondent":"高山健康課長、鷹箸保健予防課長","answer":"今後、新たな支援の仕組みなどを考える中で、そうした既存の、いただいている申請などの内容について改めて精査をする中で、把握に努めてまいりたいと考えております。子宮頸がんの予防接種、ＨＰＶのワクチンですけれども、こちらのワクチンは小学校６年生から高校１年生までの女子を対象とするワクチンでございまして、昨年と一昨年ですと、大体５,０００、平成３０年度が５,９４０人、令和元年度。","voiceIndex":144,"id":"exchange-065"},{"speaker":"あべ委員","kind":"質問","question":"本当に非常に少ないと思います。子宮頸がん、大変恐ろしい病気ですけれども、８月にようやく品川区でも接種の呼びかけは行ったと思うのですが、そして一定の問合せがあったとも聞いております。どの程度の問合せがあり、また、予診票を送ったのでしょうか。","respondent":"鷹箸保健予防課長","answer":"８月の末に、あなたのお子さん、あるいはあなたがこの予防接種の対象ですという部分のお知らせの通知を、ようやく接種控え勧奨後初めて送って、そのすぐ後からこれまでの間に、９８件のお問合せがあり、予診票をお送りしまして。","voiceIndex":147,"id":"exchange-066"},{"speaker":"あべ委員","kind":"質問・要望","question":"一定の効果はあったということですけれども、ただ全体の数からいえば、まだまだ接種率としては非常に少ないと思います。でないと、なかなか周囲のお母さんたちの関心が低くて、これからも多くの女性と、それから、これから生まれるであろう子どもたちの命のため、確実に守る１つの方策として、ぜひ、より積極的に勧奨していただきたいと思うのですが、いかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"８月末のお知らせに次いで、つい先日の国の検討委員会のほうでも、新たな接種、勧奨はしないのですけれども、必要性について分かりやすい国のパンフレットを作り直して、それを送るようにというような方針も出ておりますので、より積極的なといいますか。","voiceIndex":149,"id":"exchange-067"},{"speaker":"あべ委員","kind":"質問・要望","question":"残りの時間で環境について伺いたいと思います。この分野、技術や性能の進化が速い中で、ぜひ品川区としてもＲＥ１００、環境計画に盛り込む、あるいは前倒し実施も進めていただきたいということが１点と、それから電力の調達に当たっては、他の自治体との連携だけではなくて、区内の企業との連携もできるのではないかということで、これぜひご検討いただきたいのですが、いかがでしょうか。","respondent":"提坂環境課長","answer":"それで再生可能エネルギーの利用率というのですか、その辺の率がコロナ禍の中でかなり上回ってきたという部分があるのですけれども、それが継続的につながるものなのか、一時的なものなのか、その辺の見極めも大切だと思うので。","voiceIndex":151,"id":"exchange-068"},{"speaker":"つる委員","kind":"質問・要望","question":"最後のは、ペットの散歩やマナーについて伺っていきたいと思います。予防接種費でありますが、２０１８年の小児がんなどの治療で免疫を失った子どもの定期予防接種の再接種の費用助成についてを、繰り返し質問して求めてまいりましたけれども、品川区も２０１９年度末に要綱を変更していただいて、実施の運びとなったわけであります。","respondent":"鷹箸保健予防課長","answer":"これまで１件ではありますけれども、つい先日助成の申請がございまして、このお子さんについては、いわゆる骨髄移植ではございませんでしたが、ガンマグロブリン注射ということで、このガンマグロブリンを打つと免疫がなくなってしまうということに対して初めて申請がありまして。","voiceIndex":154,"id":"exchange-069"},{"speaker":"つる委員","kind":"質問・要望","question":"２３区で見ると、先ほど提示させていただいた区がやっていて、品川区は、今１件申請中で手続き中というところで伺いました。ちょっと細かいところですが、まさに始めていただいたばかりであるわけでありますけれども、他区の状況を見ると、この、いわゆる申請期間については若干ばらつきがあるような理解であります。オンライン申請など、そうしたことの検討もあれば、ぜひ教えてください。","respondent":"鷹箸保健予防課長","answer":"現在のところ、確かに委員ご指摘のとおり、保健予防課の窓口に主治医の先生の証明書といいますか、それとともに申請するようにというふうになってありますが、今その他の申請を含めて、郵送あるいはウェブ上での申請がほぼ可能になってありますので。","voiceIndex":156,"id":"exchange-070"},{"speaker":"つる委員","kind":"提案","question":"母子保健費に関連して、一般質問で今回提案させていただいた、とうきょうママパパ応援事業のうち、衛生費の所管する各課についての質問させていただきたいと思いますが、その中で移動経費補助の活用、それから多胎ピアサポート事業の活用というところでは、既に一般質問でご答弁、検討いただくということでそれぞれいただいておりますけれども、移動経費補助については。","respondent":"間部品川保健センター所長","answer":"とうきょうママパパ応援事業の移動支援に関してですが、委員からご指摘がありましたように、今般、今年は母子保健事業の中でも１万円のタクシー券の上乗せということで、区内商品券を配布したところですけれども、今この移動支援も検討する中では、やはり、かなり好評だったので。","voiceIndex":158,"id":"exchange-071"},{"speaker":"つる委員","kind":"提案","question":"よろしくお願いします。その２０１８年のときには、デザインの力やファッションの力を活用して、障害者の、そうした作業所等での工賃向上につなげていく、チャリティーではなく、やはりビジネスとしてしっかりと押し上げていくと、そのような支援を産業経済費の所管のほうから何かできないかという提案をさせていただきました。これは有名になっていますけれども、既に工賃が３倍になっているというのです。","respondent":"遠藤商業・ものづくり課長","answer":"アイデアなどもいろいろと出てくれば、それに沿った形のもので支援といいますか、いわゆる経営相談的なものが事業所という形でお受けすることもできますので、そういうところからの支援という形でさせていただければというふうに考えております。","voiceIndex":160,"id":"exchange-072"},{"speaker":"つる委員","kind":"意見","question":"最後に、今いろいろと支援策を考えていただけるということのご答弁と理解しましたので、ぜひまた次の質疑のときに具体的な方策が出てくることを期待したいと思います。本当に障害者が作られた後、それに著作権を入れて、何か著作権使用料を支払うとか、そのような仕組みも含めて、様々、本当に本人、ご家族、いろいろなお考えをしっかりと聞いていただいて、工賃向上の支援策を考えていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":162,"id":"exchange-073"},{"speaker":"芹澤委員","kind":"質問・要望","question":"私からは２８１ページ、感染症対策事業、２９７ページ、中小企業活性化推進事業、時間があれば２８１ページの動物愛護について伺っていきます。最初に感染症対策事業について、１点まず確認でありますが、今朝のご答弁の中で、感染者数が１,０６２名というようなお答えがあったかと思いまして、今朝の読売だったか、産経だったかの新聞だと、９８０程度だったように記憶をしています。","respondent":"鷹箸保健予防課長","answer":"東京都が報告している数と、品川区で把握している感染者数のずれですけれども、こちらについて厚生委員会等ではこれまでも何度かご説明してきたところですが、品川区で把握し、報告している数は、品川区保健所が陽性者の方に対して入院勧告。","voiceIndex":164,"id":"exchange-074"},{"speaker":"芹澤委員","kind":"質問・要望","question":"今はもう非常事態ですから、当然既に医師会、保健所、そして行政がすごく連携は取られているのだと思いますけれども、医師会の方々からも、日常的にしっかりと連携を取りたいというようなお話をいただいていまして、これがどういったスパンでやるのかはそれぞれのお考えがあるのでしょうが、今後はこのコロナ収束後にも、医師会と行政の皆さんで。","respondent":"舩木保健体制整備担当課長、遠藤商業・ものづくり課長","answer":"ＰＣＲ検査センターにつきましては、５月の開設以来、当時はなかなかコロナの感染がどこまで続くのかという見込みが立たなかったものですから、最初は本当に当面３か月程度という緊急対応を取ったところですが。こちらの支援策といたしましては、私どもでなかなかこのような助成金に慣れていない企業といいますか、特に本当に小規模な事業者がいらっしゃいますので、中小企業センターの１階で相談窓口を設けさせていただきまして。","voiceIndex":166,"id":"exchange-075"},{"speaker":"芹澤委員","kind":"質問・要望","question":"中小企業支援に関しては、私も以前要望を出させていただきましたけれども、このような各行政文書を官公庁に提出するということを代行できるのは、行政書士がメインになりまして、税金であったら税理士、労務関係であったら社労士、そのほかは行政書士ということが公的な見解だと理解をしています。最後に、動物愛護の件で伺っていきます。ご見解をお聞かせください。","respondent":"鈴木生活衛生課長","answer":"基本的には、ペットの飼育や販売業者のほうは装着と登録を義務付けられておりますが、一般の方、遡っての登録までは、まだ義務として徹底されていないところですので、今後周知をしっかりとしていきたいというふうに考えております。","voiceIndex":169,"id":"exchange-076"},{"speaker":"松澤委員","kind":"質問","question":"私からは２６９ページ、健康づくり支援事業と、２７５ページ、産後ケア事業についてお聞きいたします。健康づくり支援事業の中からウォーキングマップアプリ運用保守等と、健康ポイント事業運営委託等についてお伺いいたします。今年の７月に厚生労働省が発表しました日本人の平均寿命、女性が８７.４５歳、男性が８１.４１歳となります。ともに過去最高を更新いたしました。","respondent":"高山健康課長","answer":"区民が気軽に実行できる健康づくりの１つとして散歩を推奨するために、冊子のほうも既に作っておりまして、こちら「品川ウォーキングマップ私の散歩道」というものがございまして、これ以外にスマートフォンのアプリということで、配信のほうを平成２８年より実施しております。","voiceIndex":172,"id":"exchange-077"},{"speaker":"松澤委員","kind":"意見","question":"分かりました。ウォーキングアプリと同様に、この健康ポイント事業について、歩くことに着目した事業であります。そこで、開始から３年目となる、本事業の内容と実績、利用者の反応についてお知らせください。","respondent":"高山健康課長","answer":"区民の約７割を占めると言われております、健康づくりに無関心な層を含む多くの区民に対しまして、運動を始めるきっかけや継続する動機となるインセンティブを付与するということで、健康づくりに取り組むことを目指すものです。","voiceIndex":174,"id":"exchange-078"},{"speaker":"松澤委員","kind":"提案","question":"分かりました。８割の方が喜んでいる、これは確かにとてもいい取組みだと考えられます。先ほどポイントという話がありましたけれども、これは兵庫県豊岡市、これは市が開発した「とよおか歩子」というアプリがあります。そこでちょっとご提案します。要介護にならない体づくりにもつながり、それにプラス付加価値をつけ、どちらもウィン・ウィンになる考え方が大切だと思いますが、ご所見をお伺いいたします。","respondent":"高山健康課長","answer":"なかなかこの事業に、非常に思いを入れてくださっている方もいらっしゃるので、継続して続けたいという方のお声にも応えてまいりました。委員ご提案のそのような仕組みも、利用者の声を聞きながら、今後導入できるかどうかについて検討してまいります。","voiceIndex":176,"id":"exchange-079"},{"speaker":"松澤委員","kind":"質問","question":"アプリやＡＩを駆使し、さらに健康に対する区民の取組みが活性化することを願い、次の質問へ移らせていただきます。２７５ページ、母子健康指導事業費の中から産後ケアについてお伺いいたします。実は私も４人の子どもがおりまして、真ん中の２人は双子であります。その双子も小学校の４年生になりました。バスには乗れません。買物も行けません。どうしても通路が狭いので入れないのです。","respondent":"間部品川保健センター所長","answer":"今、主な支援ですが、多胎児育児学級ということで、いわゆるふたごの会で、先輩の親からいろいろなアドバイスを伺ったりして育児不安の軽減を図っていたり、また、早産や軽体重で生まれることもありますので、そういった場合については。","voiceIndex":178,"id":"exchange-080"},{"speaker":"松澤委員","kind":"質問","question":"多胎児を抱えた母親、出産後数か月は授乳と泣き続けることへの対応、これはほとんど睡眠時間が取れない状態になります。このような状態に対して、自分からＳＯＳを出すことができないこともあります。多胎児家庭について、保健センターとして有効な支援策について、ポイントなどがあれば教えてください。","respondent":"間部品川保健センター所長","answer":"やはり有効な手段ということで、先ほどもご答弁させていただきましたけれども、父親学級ということで実施をしております。やはり、育休中の夫の３割は、家事育児が２時間足らずという調査結果もあります。","voiceIndex":180,"id":"exchange-081"},{"speaker":"塚本委員","kind":"質問・要望","question":"私からは、２８１ページの感染症対策事業、それから２８９ページ、家庭用生ごみ処理機普及事業、３０１ページ、商店街活性化事業費について伺っていきたいと思います。陽性率も上がっていると。この中で、やはりこの約半数が感染経路不明ということになっているかと思います。そのように、すぐにＰＣＲ検査ということには一足飛びに行かない、この辺の事情についてお聞かせをいただきたいと思います。","respondent":"鷹箸保健予防課長","answer":"委員のおっしゃられたように、当初は通知が来て、ではその後どうするのかと、特段ちょっと方針も示されていなかった部分もありますが、８月２１日の国の通知以降は、基本的には通知が来た方は検査の対象と考えてもよいと。","voiceIndex":183,"id":"exchange-082"},{"speaker":"塚本委員","kind":"質問","question":"これは、現在どのような形で負担軽減につながっているかということをちょっとお伺いしたいのですが、ＣＯＣＯＡの案内先、今は帰国者・接触者相談センターイコール品川区の保健所ということになっているかと思いますけれども、この電話番号等が東京都のコールセンター等に変わっていくのか、そのような形で負担軽減という形が具体的に取られていくのか、この辺の見通しを教えてください。","respondent":"鷹箸保健予防課長","answer":"ＣＯＣＯＡの対応ですが、現在は、今委員ご指摘のとおり、品川区民であれば全例品川区の電話相談センターまで電話がかかってくるところですけれども、ちょうど昨日の２３区の課長会で、今後都のほうで一括対応するというような方針を示すべく、各区にこれから調査、アンケート。","voiceIndex":185,"id":"exchange-083"},{"speaker":"塚本委員","kind":"質問・要望","question":"例えばＣＯＣＯＡを１つ取ってみても、陽性者というものは自分で登録して、自分の行動によって、接触があった人に対して通知が行くわけですけれども、この登録自体が任意だというところがあるということで、登録しなければそれっきりというようなところもあるので、やはり多くの方がしっかりとこれを利用していただければ、一定の感染経路不明者に対する感染拡大の防止につながるとは思うのですが。","respondent":"鷹箸保健予防課長","answer":"感染経路が分かっていない方への対応ですが、まず、感染経路はどうして分かるかといいますと、陽性者の方が保健所のほうに、医師から届出があったときに詳しく、発症前１４日間、症状がない方については検査以前の１４日間の行動について詳しく聞き取ります。","voiceIndex":187,"id":"exchange-084"},{"speaker":"塚本委員","kind":"質問・要望","question":"この堆肥としての利用というものを、区としてうまく回るような形を作って、普通は家庭菜園で使うとか、そのようなことが推奨されていますけれども、より一層この家庭用生ごみ処理機というものが、付加価値のようなもので、家に１個あるといろいろと便利でいいのだという形になるような施策というものをぜひ検討していただきたいと思いますけれども、区のお考えはいかがでしょうか。","respondent":"工藤品川区清掃事務所長","answer":"いずれにいたしましても、やはり機器の購入の助成を拡大しまして、単なる、何というのですか、生ごみの減量だけではなくて、これが堆肥化できると。そういったところをしっかりとＰＲしながら、今後の普及に努めてまいりたいと思っているところです。","voiceIndex":189,"id":"exchange-085"},{"speaker":"塚本委員","kind":"質問・要望","question":"３０１ページの商店街活性化事業費の中で、聞きたいことは区内の、主に商店街のキャッシュレス化の状況についてなのですけれども、今、区内のキャッシュレス化というものはどの程度進んでいるのか、区の支援策というものもあるかと思いますが、その辺の実績等も含めて認識をお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"今回ＩＴの関係で助成金を用意したところですが、途中から販路拡大支援事業という補正予算を頂戴しまして、そちらがいわゆるキャッシュレスに対応したものということで用意させていただいたのですけれども、実際にそちらの申請のほうはほとんどないというような状況です。","voiceIndex":191,"id":"exchange-086"},{"speaker":"塚本委員","kind":"質問・要望","question":"対面接客の省力化、お釣りのやり取りなどといったものが省力化するので、その分業務的に効率が上がると、こういう面でメリットがあるわけですけれども、今後のキャッシュレスの推進について、ちょっともう時間がないので要望で終わるのですが、ぜひ商店街としてのキャッシュレス化というものも１つの今後の大事な施策だと思いますので、推進のほうよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":193,"id":"exchange-087"},{"speaker":"西本委員","kind":"質問・要望","question":"それを、今後は予防という観点からいうと、いろいろな対策に使えるのではないかと思っているのですが、その情報の使い方というか、見方というか、分析はどうされていますでしょうか。保健所のほうの人員は大丈夫ですか。これから増えてくるのか、減ってくるのか、よく分かりませんけれども、その対応はできているのでしょうかということです。今、そのようなことはありませんよね。","respondent":"鷹箸保健予防課長、遠藤商業・ものづくり課長","answer":"人員についてですが、東京都からの応援派遣職員ですとか、その他の区独自の派遣看護師なども含めまして、今総勢、当初の常勤の数よりも、事務職で５名増、それから会計年度任用職員も８月から３名増、それから派遣の看護師については。こちらはいわゆる融資のあっせん制度で、私ども区のほうでもそうですけれども、国や都につきましても制度融資等がかなり充実しているということで、倒産については一定程度回避されているというふうな形で考えているところです。","voiceIndex":195,"id":"exchange-088"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり情報というものが、私はどうしても理解できないのが、品川区にとってという、分かるのです、感染したところの集約は分かるのです。でも、ではなぜそのような状況になったのですかというような分析は、やはり知らせていくべきなのではないでしょうか。そのような分析の方法が、もうそろそろ必要なのではないでしょうかということをちょっとお聞きしたかったので、もう一度お願いします。そうですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":198,"id":"exchange-089"},{"speaker":"小芝委員","kind":"質問","question":"私からは２８１ページ、食品衛生について、２６９ページ、健康推進費の中の職員給与費に関連した保健師について、また、産経費のところ、３０１ページ、空き店舗活用支援事業についてお伺いをいたします。は２８１ページの食品衛生についてです。こちら当初予算比で半分ほどに減りました要因、そしてそれに対する評価について教えていただければと思います。","respondent":"鈴木生活衛生課長","answer":"１つは、食品衛生法が改正されまして、それに伴うＨＡＣＣＰの指導等に関する非常勤の方、これを５名募集をかけて勤務していただく予定だったのですが、全国的な需要、それから法改正だけではなくて、オリンピックのほうでも非常勤食品衛生監視員の募集が増えたことがありまして。","voiceIndex":202,"id":"exchange-090"},{"speaker":"小芝委員","kind":"質問","question":"その幾つかある要因の中で、食中毒の件数が減ったという話を伺いまして、それならば執行率の低さというものも喜ばしいことであるとは思います。そこでお聞きしますが、近年におきます、この食中毒の件数の推移、また、その特徴について教えていただければと思います。","respondent":"鈴木生活衛生課長","answer":"ただ年度によって、また時期によって、状況は変わっておりますが、先ほどの予算も含めて、多くの事例が発生してしまった場合にも十分な対応ができるように予算措置を取っているところです。","voiceIndex":204,"id":"exchange-091"},{"speaker":"小芝委員","kind":"質問","question":"今年度特にコロナウイルスの影響もありまして、一層の感染防止の徹底がなされているため、この食中毒被害が今後またより少なくなることを期待しておりますが、一方で、テイクアウトがこれほどまでに需要が伸びた年もこれまでになかったと思います。今年について、そういったことで食中毒になられたような方というのは、例年に比べて多かったのでしょうか。","respondent":"鈴木生活衛生課長","answer":"実際のテイクアウトの食事による中毒ですが、幸いなことにテイクアウトの食事を原因とする食中毒、今年度に関しましては、まだたしか１件か２件程度ということで、それほど多く発生していないということが現状です。","voiceIndex":206,"id":"exchange-092"},{"speaker":"小芝委員","kind":"確認","question":"引き続き、区民の食の安全とともに、区民の健康に寄与されますことを強く願いまして、次の質問に移らせていただきます。続きまして、職員給与費に関連して、保健師についてお伺いをいたします。保健師１人が対応する患者の数は自治体によって様々であることが、この新聞報道で分かりました。そこでまず確認ですが、現時点での、品川区におけます常勤の保健師の方は、何名ほどいらっしゃるのでしょうか。","respondent":"高山健康課長","answer":"福祉部と健康推進部を合わせまして、４３名と記憶しております。","voiceIndex":208,"id":"exchange-093"},{"speaker":"小芝委員","kind":"質問","question":"保健師はそれぞれ本来の持ち場で働かれていると思うのですが、本来の業務をこなしつつ、一方でコロナにも対応されているという状況なのでしょうか。その辺りのところを教えていただければと思います。","respondent":"鷹箸保健予防課長","answer":"それ以外に、電話相談あるいはその他の個別のコロナ対応業務ということで、現在派遣の看護師にこの業務は担っていただいておりまして、その人数が２５名になります。","voiceIndex":210,"id":"exchange-094"},{"speaker":"小芝委員","kind":"意見","question":"ちょっと時間が押していますので、産業経済費のほうに移ります。３０１ページの空き店舗活用支援事業です。区の会計決算審査意見書にも載っておりますが、こちらのほうは対当初予算比で１１.８％と、特に執行率の低い事業となっております。","respondent":"遠藤商業・ものづくり課長","answer":"こちらの空き店舗解消支援事業につきましては、昨年度につきましては執行がなかったというところで、なかなか難しい状況だというふうに認識しています。","voiceIndex":212,"id":"exchange-095"},{"speaker":"こんの委員","kind":"質問","question":"私からは２８１ページ、感染症対策事業、２７９ページ、自殺予防対策事業、２９７ページ、サポしながわ支援事業と、品川区シルバー人材センター支援事業をお伺いしたいと思います。軽症者や無症状者は、原則自治体が借り上げた施設で療養すると認識をしております。この調整も、保健所保健師の方がしてくださっているという状況も伺いますが、そこら辺のご苦労の大変さも少し教えていただければと思います。","respondent":"鷹箸保健予防課長","answer":"それから施設利用ですが、現在都内では８つのホテルを東京都が借り上げまして、症状がない方、あるいは非常に軽症な方については、そちらのホテル療養、施設療養に行っていただいているわけですけれども、こちらにつきましては。","voiceIndex":215,"id":"exchange-096"},{"speaker":"こんの委員","kind":"質問・要望","question":"特別な理由がある方を自宅療養者としているというところが分かりました。どのような食材を配達されているのか、食材の内容、それから療養期間中に何回ほど配達をされているのか、１回で、その療養期間中のものを全部配達されているのか、それとも何回かに分けていらっしゃるのか、その辺を伺いたいのと、それから、どなたが配達をしてくださっているのか、この配達の仕組み、その辺もお伺いしたいと思います。","respondent":"鷹箸保健予防課長","answer":"そのお届けしている内容ですけれども、基本は保存が利くような形の食材で、バランスも考えまして、主食、それからお熱が出ることも考えて、電解質水分ですとか、あとは野菜を召し上がっていただくのが難しいので野菜ジュースなど、主食その他全部、おかず。","voiceIndex":217,"id":"exchange-097"},{"speaker":"こんの委員","kind":"質問","question":"その１つは、品川区の船の科学館の敷地内に整備した災害危機サポートセンターというようにお聞きしているのですが、この件について、この場所を選ばれたのはなぜなのか、もし経緯が分かれば、その辺を参考までにお伺いしたいのと、また、入所対象要件、これについて、また、いわゆるペットと同伴だけれども、その同伴をするにも要件があるのか、その辺の調整、入所の流れの概要などもご説明ください。","respondent":"鷹箸保健予防課長","answer":"は当然ですけれども、ペットの食べ物まで都のほうで準備するわけではございませんので、それをマックス１０日間分は自分で用意してくるようにといったところまでが、今、保健所のほうに示されておりますが、ペットによって条件が違うと思いますので、今後。","voiceIndex":219,"id":"exchange-098"},{"speaker":"こんの委員","kind":"質問","question":"分かりました。ここに相談をされる方というのは、ご家族の方、ご本人というふうに想像するわけですけれども、例えば、全く医療にかかっていない方をつなげるという作業があると思うのですが、相談を受けた後に医療にかかって、医療にかかったら、その医療とそのご本人あるいは家族の方で、それが、何でしょう、自殺予防、いわゆる心のケアというように流れていくのでしょうか。その辺を教えてください。","respondent":"榎本荏原保健センター所長","answer":"保健センターのほうに心の相談という形で入っていらっしゃる方々の相談、いろいろなご相談をお受けしている中で、すぐに受診をしたいのでクリニックなどを教えてほしいというご希望のある方は、そのまま受診をお勧めする場合もありますし。","voiceIndex":223,"id":"exchange-099"},{"speaker":"こんの委員","kind":"質問・要望","question":"フォローしてくださっている体制があるということは分かりました。それでも保健師はほかの業務も大変に業務が多い中で、このアウトリーチはどこまでいってもというか、１回、２回で終わる話ではないと想像するところだと、やはり保健師の確保というのは、これからもこういう対応には、保健師の確保というものは大事だなと考えています。その辺は要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":225,"id":"exchange-100"},{"speaker":"木村委員","kind":"質問","question":"長寿の方々は、健康に対して何かを行っています。この教室は、１会場１コースにつき定員２５名程度、４６教室ですから、会場の広さでも異なりますけれども、計算しますとざっと１,１５０人近くになります。区内の６０歳以上の中で、この健康塾に参加されている割合は、これでよいとお考えでしょうか。それとも、会員をもっともっと集めるべきと考えているのでしょうか、お聞かせをください。","respondent":"高山健康課長","answer":"会場の都合などもございまして、これ以上多くの参加者の人数の積み増しということもなかなか困難な状況もありますので、事業の実施の規模としては適正と考えております。","voiceIndex":227,"id":"exchange-101"},{"speaker":"木村委員","kind":"質問・要望","question":"健康塾は同じような年代が集まるわけですから、話に花が咲き、健康づくりに拍車がかかるわけであります。高齢者には大変居心地のよいところになると思います。何らかの形で、この規模を大きくすることはもう、今の答弁にもありましたけれども、あんまりしたくないというような、これ以上はもう無理だというようなことでありますが、もう一度お答えをいただきたいと思います。","respondent":"高山健康課長","answer":"仮にこの会場数を増やすとなると、既存の団体にもある程度我慢をいただく必要もあるといったこと、それから実際にこの事業運営をお願いしておりますトリム体操連盟のほうに、さらなる負担をお願いしなくてはいけないといった事情もございまして、会場規模として。","voiceIndex":229,"id":"exchange-102"},{"speaker":"木村委員","kind":"質問","question":"今度は２７７ページの上から９番目にありますけれども、９行目にあります「２０歳からの健康診査」、１,９４７万円余からの質問をいたします。「２０歳からの健康診査」とありますけれども、二十歳といえば、例外もありますが、健康そのものという印象が強いのですけれども、なぜこの二十歳からになったのでしょうか。２０代にはどのような病気が考えられているのか、お聞かせをください。","respondent":"高山健康課長","answer":"この世代に特に生活習慣病などで大きく懸念されるような所見はないというふうには考えておりますが、早くからこのような、１年に１回ご自身の健康と向き合うという、そうした契機として、この健康診査のほうを活用いただければと考えております。","voiceIndex":231,"id":"exchange-103"},{"speaker":"木村委員","kind":"質問","question":"２７９ページの中段より下にありますけれども、こころの健康づくり事業からの質問をいたします。２０１９年の全国の自殺者数は、２０１８年より６７１人減の２万１,６０９人、そして２０２０年８月までの自殺者が、前年比で約２５０名増えているという報道もありました。さらなる自殺者減少に向けた取組みの強化とありますけれども、この取組みの強化とはどのようなことでしょうか。","respondent":"鷹箸保健予防課長","answer":"その対策の強化につきましては、目に見えてすぐ効果的な対策というものは実際には難しいところですが、特に今年については、コロナの問題を背景に、経済的あるいはその閉塞感から自殺者が増えるということが想定されている中で。","voiceIndex":233,"id":"exchange-104"},{"speaker":"木村委員","kind":"質問","question":"いろいろな相談があり、大変な対応に苦慮されていることと思いますけれども、親切に対応をして多くの命を救ってきたと思いますが、これからも、今以上にこの苦労があると思いますけれども、これからの事業成功には何が必要とお考えでしょうか。","respondent":"鷹箸保健予防課長","answer":"今後の新たな取組みですが、先ほどの繰り返しになる部分もありますけれども、これまでやってきたものを、普及啓発であればより具体的かつ区民の皆さんの身近なところで展開していく、今回の計画では、区内の、例えば医師会。","voiceIndex":235,"id":"exchange-105"},{"speaker":"木村委員","kind":"質問","question":"本当にせっかく生をうけて、この世の中に生まれてきたわけでありますから、まだまだ、人間にはやることが十分にあると思います。ぜひとも皆さんの力で、１人でも多くの方をお救いいただきますようお願いをして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":237,"id":"exchange-106"},{"speaker":"須貝委員","kind":"質問","question":"私は２６９ページ、職員の人事について、２７４ページ、保健予防についてお聞きします。ならば、なぜ人をもっと増やさないのか。コロナ感染症による発病者や死亡者を守ることも必要ですが、その一方で、コロナが原因ではなくて、外出自粛などの規制により、患者や関連死の方が増えている、増え続けている、このような現状についてどう思われているのか、ちょっとその辺のご見解をお聞かせください。","respondent":"黒田人事課長、鷹箸保健予防課長","answer":"職員数のお尋ねですが、いわゆる常勤の職員につきましては、採用試験を前年度に行いまして、そちらのほうで特別区全体で採用活動を行っているというところでは、急遽繁忙となった時に採用数を増やすということは難しい状況ですので。ただ、一方で外に出るのが怖くて受診できない、お薬がなくなってしまう、どうしようということについては、いわゆるリモート診療というのでしょうか、電話での再診扱いにして。","voiceIndex":239,"id":"exchange-107"},{"speaker":"須貝委員","kind":"質問","question":"どのような企業でも。そして、今私のお聞きしたのは、片やコロナ、コロナで、そちらのほうに力を集中しているのは分かります。でも、区民は皆さん平等ではないですか。それだったら何か保健衛生の根幹として、私はおかしいと思うのですが、その辺についてちょっともう１回お聞かせください。片一方は一生懸命守っています。何か矛盾しているように思うのですが、違いますか。","respondent":"高山健康課長","answer":"保健師の現下における活動領域といいますか、その辺りをちょっと私のほうでご説明します。","voiceIndex":242,"id":"exchange-108"},{"speaker":"須貝委員","kind":"質問・要望","question":"実際にそのような方たちが増えているというならば、何とかそれをフォローして、ほかの区民の方も大切なのですから、何とか人員を増やしてでも対応していただきたいと私は思います。その中で緩和している、今、感染予防の緩和は分かります。この方たちはこれが楽しみで、そして、これが元気になる、気力になる、１つの大きな要素ではないですか。その辺についてちょっとご見解をお聞かせください。","respondent":"高山健康課長","answer":"その中には保健師も関わりながら、例えばフレイルチェックの要素を入れたりとか、そのようなことでふれあい健康塾など、従来からの健康づくり事業を安全性を確保しながら再開しています。","voiceIndex":244,"id":"exchange-109"},{"speaker":"須貝委員","kind":"質問・要望","question":"そのほかに仕掛けはありますが、実際にソーシャルディスタンスというものは、この品川区の感染予防の指針にもありますけれども、これ変えたほうがいいのではないですか。だけれども、このようなことがあるならば、そのような品川区の感染予防の指針も、やはり何も国に従うのではなくて、皆さんに安心感を持たせる意味でも、改善するところ、変更することはしていかないといけないのではないのですか。","respondent":"鷹箸保健予防課長","answer":"あれも駄目、これも駄目といった形で、特段そこを強調して広報などをした記憶は、少なくとも私はございませんで、特に緊急事態宣言の頃は、お店に行くのもなるべく控えるようにといったことはあったかと思いますが、現在は、ただお店に行っても。","voiceIndex":246,"id":"exchange-110"},{"speaker":"須貝委員","kind":"質問","question":"２０cmか３０cm、現実を見てください。現実を。それで、何もそこにソーシャルディスタンスなどをやってしまったら、お店だって、それからライブだって、何かやるときに何もできないではないですか、そういうことも、区民の生活ということも考えてください。そういうところは私は行動指針としてしっかりと直して、少しでも区民に安心感を与えるべきだと思いますが、もう一度ご見解をお聞かせください。","respondent":"鷹箸保健予防課長","answer":"繰り返しの答弁になりますが、必要な感染予防をしっかりと保っていただいた上で、可能な限りこれまでどおりの生活していただくということが区の姿勢であり、それは国も推奨していることでございまして、いたずらに全て駄目などということは。","voiceIndex":248,"id":"exchange-111"},{"speaker":"須貝委員","kind":"質問・要望","question":"このような宮沢さんという、やはりウイルスの研究者が明言して、断言しているのです。このような人たちの声にも耳を傾けて、いい区政をつくっていただきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":250,"id":"exchange-112"},{"speaker":"たけうち委員","kind":"質問","question":"初めに、２８１ページのほうから伺っていきたいと思いますが、まずこの事業の概要、内容についてと、また、難病といいますと数多くあるわけですが、難病の数、それから区内にどれくらいいらっしゃるかという毎年の申請状況、それから申請の多い難病というものはどのようなものがあるのかということを教えてください。","respondent":"舩木大井保健センター所長","answer":"これらの事業に加えまして、各保健センターの保健師による家庭訪問や電話相談、また、必要に応じて関係機関との連携を図りながら、必要な個別支援を行っているところです。","voiceIndex":252,"id":"exchange-113"},{"speaker":"たけうち委員","kind":"質問","question":"いろいろと保健師が、やはり本当にコロナだけではなくて、いろいろなところでお力添えをいただいている中で、患者の支援をしていただいているです。この潰瘍性大腸炎は、比較的に若い人に多いと言われております。そういった中で、今様々な支援事業をお聞きしましたけれども、就労というか、お仕事についての支援のようなものは何かやっているのかどうかということをお聞きしたいと思います。","respondent":"舩木大井保健センター所長","answer":"具体的にその難病に特化した就労支援の仕組みづくりというものを保健センターでは実施はしてございません。","voiceIndex":254,"id":"exchange-114"},{"speaker":"たけうち委員","kind":"質問","question":"例えば公務員で、２３区の場合には試験に合格した後に面接されると思うのですけれども、その面接のときに、例えばこういった、難病ということのお話がご本人からあったときに、どのような対応をされているのか、もし分かれば教えてください。","respondent":"黒田人事課長","answer":"採用時につきましては、特に勤務できる条件としまして、１日の勤務時間が７時間４５分で、週３８時間４５分勤務ができるということが前提での採用試験に応募していただいているですので、特に個別に病歴について確認するということはございませんが、また採用試験の中でも。","voiceIndex":256,"id":"exchange-115"},{"speaker":"たけうち委員","kind":"質問","question":"当然品川区の場合は２３区一律ですから、品川区単独でそのようなことはできないことは重々分かっているのですけれども、先ほどあったように、実質的には難病の方でも、その方の状況に応じて採用される場合もあるということで、これはもう非常にいいことなのですが、やはりそのような方にとって、障害者もそうですけれども、なかなか進んでいませんが。","respondent":"黒田人事課長","answer":"例えば、ご紹介のありました明石市の職員採用の中では、特別区ではいわゆる障害者を対象とした区分の採用試験を行っておりますが、その中に自立支援医療受給者証をお持ちの方や発達障害に係る医師の診断書を受けている方。","voiceIndex":258,"id":"exchange-116"},{"speaker":"たけうち委員","kind":"質問・要望","question":"ぜひ今後研究・検討、いろいろな方面でそのような方にお会いしたら、そのようなこともあるということをお伝えいただければと思います。これは要望にとどめします。この内容について簡単にお知らせいただきたいということと、あと実績というか、状況について、また、一応そのように実績が出ているのですけれども、決算としては出ていないのですが、どこかに入っているのかどうか、もし分かれば教えてください。","respondent":"鷹箸保健予防課長","answer":"その後どうなったかということは、実は一昨年までは全く地元の保健所に連絡がなかったところですが、例えばその方が区民であれば、戻ってきた後に保健センターの保健師等が個別の支援が必要ということで、かねてから要望しておりましたところ、一昨年の６月以降。","voiceIndex":260,"id":"exchange-117"},{"speaker":"たけうち委員","kind":"質問・要望","question":"最初のほうの警察官通報ですけれども、今あったとおり、今まではなかなか通報はするけれども、区を素通りして、その後フィードバックがないという中で、地域の方がやはり、いろいろなケースがあると思うのですが、やはり区にも情報が来ないということが、要望されて最近、一昨年ですか、変わったということで、非常にいいケースだと思うので、いろいろな方がいて、本当にその情報をやはりどこまで。","respondent":"榎本荏原保健センター所長","answer":"医療保護入院につきましては、品川区で毎年３００件弱ぐらいの件数になっておりますけれども、保健センターのほうで関わって入院になる場合と、ご家族なりがご本人を連れていってということで、関わりがない方もいらっしゃるかと考えています。","voiceIndex":262,"id":"exchange-118"},{"speaker":"たけうち委員","kind":"意見","question":"本当に保健師が家まで行って、訪ねていただいて、医者などを連れていっていただけるケースもあるようなので、本当にお世話になりますけれども、どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":264,"id":"exchange-119"},{"speaker":"安藤委員","kind":"質問・要望","question":"２８２ページ、環境費から環境学習交流施設、大気汚染調査、羽田新ルートなどについて伺います。は環境学習交流施設です。地球温暖化、気候変動の問題は、巨大台風による災害の激甚化や、酷暑、激暑など、私たち区民の肌感覚でも、改善は待ったなしの課題となっているのではないでしょうか。当施設における地球温暖化問題、気候変動対策の位置づけについて簡単に伺います。","respondent":"提坂環境課長","answer":"施設の中で大型映像装置による展示ですとか、あと体験型の展示とか、そのようなところを予定していますけれども、そのような体験を通じていただいて、地球温暖化に対する意識、あと環境保全全体に対する意識を向上するという狙いがあります。","voiceIndex":267,"id":"exchange-120"},{"speaker":"安藤委員","kind":"提案","question":"夏と冬のバージョンがあり、それぞれ１０分程度で非常に短くて見やすいということです。ぜひこの気候変動問題とこの対策の必要性を自分に引きつけて考える、いい材料だと思うのですけれども、この映像資料を、環境課に限らないと思うのですが、これからの温暖化対策というところで活用していただくことを提案したいと思いますけれども、いかがでしょうか。","respondent":"提坂環境課長","answer":"今ご紹介いただいた環境省の「２１００年未来の天気予報」ですか、これは私も拝見したのですけれども、冬の２月の話ですと、節分の時期に豆がとれない、そのような紹介もしておりまして、非常にショッキングな内容なので、今のお子さんが見てもこれは非常にショックを受けて。","voiceIndex":269,"id":"exchange-121"},{"speaker":"安藤委員","kind":"質問・要望","question":"ほかのＮＯｘやＳＯ２と同様に、この区のページでまとめて見られるようにしていただきたいのですが、いかがでしょうか。大気環境の改善に取り組む市民団体の皆さんから、大井中央陸橋と平塚橋、この２か所の自排局についても、ＰＭ２.５を加えてきめ細かく測定してほしいとの声を伺っていますが、この２か所についてもＰＭ２.５を測定するよう求めたいのですけれども、いかがでしょうか。","respondent":"提坂環境課長","answer":"自動車排気ガス測定局の部分で、大井中央陸橋と平塚橋の部分ですけれども、こちらのほうについては、区で設置している部分ではありますが、実際に都の所有地を借りているというところで、さらにＰＭ２.５の測定器を作るとなると。","voiceIndex":271,"id":"exchange-122"},{"speaker":"安藤委員","kind":"質問・要望","question":"表示の仕方はぜひ工夫していただきたいと思います。直近でいうと、ＰＭ２.５は環境基準を満たしているという話でしたが、２０１５年は未達成だったのです。騒音測定については区は独自にやっていますけれども、この騒音測定同様、区もこの大気汚染についての独自調査を強めて、区民への健康被害の影響や、その有無を把握すべきだと思いますが、区の考えはいかがでしょうか。","respondent":"提坂環境課長","answer":"それから直近でちょっと見てみたのですけれども、１０月２日と１０月４日に品川の上空を飛んでいるのですが、そのときの数値というものがそのほかの日と比べてもそう大差ないというか、逆に低かったりということで、むしろ、やはりその設置場所からいいますと。","voiceIndex":273,"id":"exchange-123"},{"speaker":"安藤委員","kind":"質問・要望","question":"それで今後測定していって、その数値が超えた場合、まず増やしてはいかがかということと、そしてこれが増えた場合、そのときに環境基準を超えたという場合、どのような対応をするのかも伺いたいと思います。区民の環境や健康を守る立場から、そのような場合は国に当然新ルートの中止を求めるべきだと思うのですが、区はその考えがあるのかないのか伺います。","respondent":"鈴木都市計画課長","answer":"大気環境についてですが、基本的には、今、環境課長が答弁しましたように、区内、ＰＭ２.５については、ルート直下ではございませんけれども、区内でバランスよく測定をしているというところで、上空からの影響については、大気の風向きですとか、そうしたところが様々影響して。","voiceIndex":275,"id":"exchange-124"},{"speaker":"安藤委員","kind":"質問","question":"空港周辺で国はやると言うのですけれども、問題はその国の調査に品川区も入っているのですか。実際に区民が暮らしているところの大気環境がどうなのかということが重要なので、それと増えた場合、超した場合はどうするのかという質問の答弁がないので教えてください。","respondent":"鈴木都市計画課長","answer":"当然ながら超えた場合は、これは国のほうで責任を持って、これは環境基準ですので、その超えた場合についての対応は、国についてしっかりと求めていくということになろうかと思います。","voiceIndex":277,"id":"exchange-125"},{"speaker":"松本委員","kind":"質問","question":"本日は３０１ページ、商店街活性化事業費について、それと３０３ページ、消費者啓発費について伺います。商店街活性化事業費のうち、商店街アドバイザー派遣事業助成なのですけれども、こちらは予算段階では６５万円計上されていたのですが、決算段階で見ると２万円ということで、相当少なくなっているかと思います。こちらの事業内容と、ここまで低調となっている理由についてお願いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"商店街アドバイザー派遣事業です。こちらは商店街のほうで、例えばですけれども、専門家の力が必要だというような場合に派遣をさせていただいて、解決に導いていただくというものでございまして、昨年については、そちらのほうのお話があまりなかったというようなところです。","voiceIndex":280,"id":"exchange-126"},{"speaker":"松本委員","kind":"質問・要望","question":"それで活性化ということで少しお伺いしたいのですけれども、今年の６月に国土交通省が、テイクアウトやテラス営業などのための道路占用の許可基準を緩和するということが、テラス席の道路占用の許可基準を緩和するというふうな施策を始めました。東京都のほうも、占用許可基準緩和によるテラス営業支援事業を始めているというふうに伺っております。","respondent":"遠藤商業・ものづくり課長","answer":"いわゆるお店の前にテラス等を設けてというような話を、基準が緩和されたということでお話を伺いまして、そちらにつきましては、全ての商店街にこのような形に制度が変わったので。","voiceIndex":282,"id":"exchange-127"},{"speaker":"松本委員","kind":"質問・要望","question":"現実には８月段階ではなく、今の段階でもどうやらないということで、ただ一方で、やはり簡単な周知だとなかなか分かっていただけない部分もあるのかなと思います。これは要望です。過去の答弁で移転に関し、商業・ものづくり課との連携強化という点もあり得るというように挙げられていたかと思うのですけれども、移転から１年経っての連携の現状についてもお願いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"本来であれば、中小企業センターまつりというものが毎年５月に行われているところがありまして、そこにいわゆる消費者の団体などがいろいろなイベントなどを一緒にやって、一体感を持ってというところであったのですけれども、今回コロナ禍ということで。","voiceIndex":284,"id":"exchange-128"},{"speaker":"松本委員","kind":"意見","question":"１８歳になるということで、これからそういった若い人たちをターゲットにした、午前中もあったマルチ商法等の問題が出てくるということはそのとおり、そのとおりというか、あると思うのです。その消費者教育なのですけれども、こちらが結構見ていますと、学校側でなかなか消費者教育の時間が確保できないというような声も聞かれるのですが、こちらのほうの取組みの状況をお願いできればと思います。","respondent":"遠藤商業・ものづくり課長","answer":"私どもでやらせていただいている成年の年齢の引下げに対する取組みということであれば、例えば同じ建物にあります介護福祉専門学校、このようなところに、特に新成人、社会人になろうという方たちに対して啓発用冊子を提供したり、あるいは少し離れますが、小学校低学年を対象に。","voiceIndex":286,"id":"exchange-129"},{"speaker":"松本委員","kind":"質問・要望","question":"詐欺などという話自体は、教育することも大事なのですけれども、具体的な手法というか、どのように彼らが取り込んでいっているのかというところも、ぜひともこの教育支援の中に取り込んでいただきたい。具体的な手法の部分も取り込んでいただきたいと思うのですが、最後にご答弁をお願いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"最新のそのような情報については、消費生活相談員に研修等も受けしていますので、出前講座等もあります。その部分活用して、周知に努めたいと思います。","voiceIndex":288,"id":"exchange-130"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、２８５ページの航空機騒音調査から、羽田新ルートについて伺いたいと思います。午前中の質疑で、区の測定地点の高度、立会小学校で３７０ｍ、台場小学校で４７０ｍという答弁がありました。高度と併せて、横の距離といいますか、ルートの線があると思うのですが、そこからの、この２つの測定地点の距離というものが分かれば、立会小学校と台場小学校の距離を教えていただきたいと思います。","respondent":"鈴木都市計画課長","answer":"区内で設置しております２地点でのルートとの横方向の距離になりますが、台場小学校については、海側のルートから横方向で２５０ｍ、立会小学校が、内陸部のルートになりますが、横方向で１５０ｍという位置関係です。","voiceIndex":291,"id":"exchange-131"},{"speaker":"石田（ち）委員","kind":"質問","question":"国の説明では、高度３００ｍでの騒音が直下で８０デシベルと、高度４５０ｍの直下で７６デシベルという説明なのです。台場小学校でも、立会小学校よりも高い高度にもかかわらず、８１デシベルが最大でも出ているのです。改めて、国の説明よりもうるさい、大きな騒音で飛んでいる状況の区の認識を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"午前中、騒音測定結果についてご答弁差し上げましたが、基本的に、例えば立会小学校につきましては、当初国のほうは大井町駅付近で８０デシベルというところで説明があったかと思います。その測定、高度から比較すると、立会小学校はさらに高度が低いというところの位置関係です。","voiceIndex":293,"id":"exchange-132"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"約３時間飛んでいる、その下で感じているその被害というものは、本当に大きなものだと思っています。ですので、数字的には突出して大きい騒音が出たという認識ではないということではなくて、これだけの被害を与えているという認識をぜひとも持っていただきたいと思います。このＬｄｅｎで問題なしということ自体問題だと思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"区としては、このＬｄｅｎの考え方がおかしいというところではなくて、やはりルート直下、影響のある騒音環境について、少しでも軽減になるような取組みを、以前も、これからも求めていくです。","voiceIndex":295,"id":"exchange-133"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"Ｌｄｅｎが６２デシベル以上になれば防音工事を保障しないといけない。それを避けるために３時間程度にしておけば防音工事もしなくて済む。その程度の考えで、約３時間にわたって８０デシベル以上の騒音にさらされる区民の暮らしなど、考えられていないということが明らかではないですか。Ｌｄｅｎで問題なしとするのはやめるよう国に求めてほしいと思いますけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"国の職員が対象にならないように行ったということがありましたが、それは区として、何か直接お聞きしたことは一切ございませんけれども、基本的にＬｄｅｎというものは音の総エネルギーということで、例えば夜間、静かなときに係数を多くして。","voiceIndex":297,"id":"exchange-134"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そのＬｄｅｎで問題がないということが、この新ルートを解禁した元にもなっているのです。ですので、やはりこうした考えを区から改善させていく、そうした声を区民とともに上げていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":299,"id":"exchange-135"},{"speaker":"くにば委員","kind":"質問・要望","question":"順不同に２９９ページ、産学連携推進事業、３０１ページ、商店街振興事業、３０３ページ、商店街国際化推進事業、空き店舗活用支援事業についてお伺いします。多様性のある視点からの施策は、行政にとっても重要だと思いますので、今後もぜひ連携を強化して、様々な機会を捉えて意見交換を行っていただきたいと考えています。","respondent":"遠藤商業・ものづくり課長","answer":"それぞれの特徴を捉えまして、ちょっと今後、来月ぐらいになろうかと思いますけれども、五反田バレーと、それから商店街とで連携といいますか、イベントをちょっと考えておりまして、商店街のほうで。","voiceIndex":301,"id":"exchange-136"},{"speaker":"くにば委員","kind":"質問・要望","question":"今おっしゃっていた形で、コロナ禍で商店街と五反田バレーとの取組みが何かそのきっかけとなって、ぜひともその区の貴重な資源である五反田バレー、そして商店街の連携を行政がその仲介になって行っていけるように、商業・ものづくり課のほうで連携のほうを強めていただきたいと思います。商店街の活性化のためには、魅力的な個店づくりが重要であるとの考え方が１つ。質問します。","respondent":"遠藤商業・ものづくり課長","answer":"商店街国際化推進事業では、区を訪れる外国人の増加が見込まれるというようなところがございまして、多言語による情報提供、外国人受入れのための整備などを行っているところにつきまして。","voiceIndex":303,"id":"exchange-137"},{"speaker":"くにば委員","kind":"意見","question":"このハラルフードに関しては、２０１６年ぐらいから日本の様々、官公庁含めて関心が上がっております。最後にムスリムの方々の取り込みによる商店街の活性化施策の１つとして、空き店舗活用支援事業のチャレンジマート事業でのハラル対応店の開業などの事業費助成など、様々考えられますけれども、こういった点に関してご所見をお聞かせください。","respondent":"遠藤商業・ものづくり課長","answer":"ハラルフードにつきましても、そこが商店街にとってはとても魅力的で、観光客を呼び込むというような事例がありますので、そこについてお話がありましたら、ぜひ前向きにこちらも推進等をしたいと考えています。","voiceIndex":305,"id":"exchange-138"},{"speaker":"くにば委員","kind":"意見","question":"こちらのチャレンジマート事業のほうが、直近の実績のほうを見たら、実際に助成を申請したのが１件であるとか、３件であるとか、なかなか進んでいない事業だということは認識しております。商店街のまた１つ新たな魅力の切り口として、こういったハラルフードという観点等、様々商店街の方々とお話をなさって、ぜひともこういった取組みのほうもよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":307,"id":"exchange-139"},{"speaker":"おくの委員","kind":"質問","question":"４点伺います。この東京都家賃支援給付金について、その東京都の２分の１を給付するということですけれども、これがなぜ２分の１なのでしょうか。なぜこのように減らすのでしょうか。これはどのようにしてこの数字、７,２００件を割り出してこられたのでしょうか。これはかなり高い家賃を払っている事業所を想定しているように思いますけれども、これはなぜでしょうか、以上４点、まず伺います。","respondent":"遠藤商業・ものづくり課長","answer":"こちらの部分につきまして、２割が適正か、あるいは１割かというような部分はあろうかと思いますけれども、実際にその家賃を払わないで自分の家で実施している方であれば固定資産税を払うとか、いろいろと経費がかかるようなところがあるかと思います。","voiceIndex":309,"id":"exchange-140"},{"speaker":"おくの委員","kind":"質問","question":"今伺っておりますと、かなりざっくりと計算された結果だなと思いました。例えば、私はいろいろと伺ってきまして、ある喫茶店経営者の方からは、売上げがかなり落ちたのだけれども、この給付金の基準には至らなかったので給付金は受けられないと。家賃が８０万円であることを想定するよりも、そのようなことをお考えになったほうがよかったのではないかと私は思うのですけれども、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"先ほど売上高が前年度同月比で５０％以下というような説明をしましたが、もう一つ条件がございまして、５月から１２月で連続する３か月の合計が３０％以上落ちていると、２つの条件のどちらかを満たせば、給付の対象になるですので、苦しいところはこれだけ。","voiceIndex":311,"id":"exchange-141"},{"speaker":"おくの委員","kind":"質問","question":"例えばほかのレストラン経営者の方に伺ったお話では、そこも客足が戻ってきつつあるけれども、まだ戻りきらないというようなところなのですが、コロナが収束しても業態転換を考えなければいけないだろうというところで、まだまだ時間が欲しいということで、この家賃支援給付金、あるいは持続化給付金などもありましたけれども、これをやはり１回きりに終わらせてほしくないというご希望もあるわけです。","respondent":"遠藤商業・ものづくり課長","answer":"先ほどのレストランということであれば、東京都のほうでもいろいろな支援メニューがありますので、そのような部分、いろいろな形でのご紹介などもできるかと思いますので、そういう形で引き続き支援をしていきたいと考えています。","voiceIndex":313,"id":"exchange-142"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"２９９ページ、産学連携推進事業のうちのモンゴル高専との科学技術交流事業について、それから３０３ページのプレミアム付区内共通商品券発行助成と、臨時商品券事業についてお伺いします。昨年度の決算特別委員会でも質問させていただきました。こういったように、技術者を求める品川区内の企業とモンゴルの高専の学生を品川区がつないでいるというこの事業は、３名の雇用で実現してきました。","respondent":"遠藤商業・ものづくり課長","answer":"雇う側のほうも、今後モンゴル、引き続きという形を考えていらっしゃるところもありますので、そういう意味では、順調に今のところお仕事をしていただいているというような状況です。","voiceIndex":316,"id":"exchange-143"},{"speaker":"高橋（し）委員","kind":"意見","question":"事前のマッチング等のご努力をされたというところですが、昨年のときにも、インターシップ事業などの一定期間の交流を創出するレベルなど、こういった形で正規雇用の意味合いは非常に深いというようなご答弁がありました。それぞれの生活面、それから企業側への支援、そういった内容と、今後の定着、その方向性についてお尋ねします。","respondent":"遠藤商業・ものづくり課長","answer":"今年につきましては、オンラインですけれども、セミナーを連続で５回という形で、それぞれの企業を対象に、受入れするときの心構えや、あるいは受け入れるときに対しての支援の仕方などのセミナーをさせていただいているところです。","voiceIndex":318,"id":"exchange-144"},{"speaker":"高橋（し）委員","kind":"意見","question":"今少しありましたが、今年度、先ほどの継続性ではありませんけれども、オンライン等でモンゴルの学生と区内企業とのマッチングの機会、どのような形でやられているのか、それから今度は２期生になると思いますが、その方々が今度モンゴル高専でどれぐらい卒業され、そして区内の企業がどのような形で参加され、採用予定がもし分かれば、その辺りの数字もお願いします。","respondent":"遠藤商業・ものづくり課長","answer":"採用予定のほうですけれども、既に５社６名が、６月の段階で内定を出すような形になりまして、本来ですと１０月の頭ぐらいからこちら日本に来ていただいて、仕事をしていただくという形で進めていたところです。","voiceIndex":320,"id":"exchange-145"},{"speaker":"高橋（し）委員","kind":"質問","question":"５社６名の方が内定しているということで、品川区の企業も期待されていると思いますし、ぜひ区としても、生活面、企業側への支援、先ほどお話ししましたが、バックアップをお願いしたいと思います。その後の経過をお尋ねしたいと思います。消費税が１０％に上がったことに対する国の商品券の事業でした。これは購入される方々や商店街の店舗などで、混乱などは発生しなかったのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"昨年、比較的近い時期に２つの商品券が出たですが、現場から特に混乱したという形は聞いておりません。","voiceIndex":322,"id":"exchange-146"},{"speaker":"高橋（し）委員","kind":"質問","question":"ただ、品川区のほうのプレミアム付商品券は、商店街振興で大型店では使えない、しかし、国の臨時商品券は、大型店から取扱いの希望があった場合は区で断ることができないというような、取扱い店舗の違いがあったというふうに伺っております。その辺の状況があったと思うのですが、今混乱がないということですので、国のほうの商品券の購入というか、その実施内容はどのぐらいだったでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"件数といたしましては、特別区民税非課税者につきましては申請が必要ということで、対象者は４万８,０００人になるのですが、実際には１万件強の申請しかなかったということで、全体としては、おおむね予定の２割ぐらいという形でなっているところです。","voiceIndex":324,"id":"exchange-147"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"予算は２億円計上しましたが、決算では８,０００万円という形の購入の金額だったので、なかなか行き渡らなかった、受入れが難しかったということだと思います。今年また区の商品券を発行していますので、その事業が円滑に進められることを要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":326,"id":"exchange-148"},{"speaker":"中塚委員","kind":"質問","question":"２９５ページ、中小企業経営支援事業費に関わって、コロナで影響を受ける中小企業への支援について伺いたいと思います。区の基本姿勢ですが、コロナ感染抑止と社会経済活動の回復には、検査の拡充と医療への支援が必要だと思います。同時に、ここからが質問ですけれども、事業所への支援について、やはり一過性や一時的なものではなく、継続的に行われることが必要だと思いますが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"当初２７億円の予算のところ、補正を全部で４回ほどさせていただいて、プラスで３０億円頂戴したところで、合計で５７億円ということで、継続性を持って今まで対応してきたというふうに考えております。","voiceIndex":328,"id":"exchange-149"},{"speaker":"中塚委員","kind":"質問","question":"継続性を持って対応してきたということですが、これからもその継続性が私は必要だと思います。そこで販路拡大支援助成について伺います。支出もあるので対象にしてほしいとおっしゃっておりました。お店でお客様をお迎えするために、非接触型の検温器は助成対象なのだから、お店の営業に欠かせない従業員のマスクと、お店で使うアルコールも助成対象にすべきだと思いますが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"販路拡大支援助成の対象という形になるかと思います。","voiceIndex":330,"id":"exchange-150"},{"speaker":"中塚委員","kind":"質問","question":"前向きな投資ということなのですけれども、消耗品だとなぜ対象にならないのか、その理由を伺いたいと思います。今度はこの経済を立て直そうというわけですから、マスクとアルコールも助成対象にできると思いますけれども、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"考え方になろうかと思いますけども、マスクあるいはアルコール、先ほど言ったとおり消耗品です。","voiceIndex":332,"id":"exchange-151"},{"speaker":"中塚委員","kind":"質問","question":"だから、なぜ消耗品だと対象にならないのか、対象にしていないのか伺います。","respondent":"遠藤商業・ものづくり課長","answer":"こちらの部分につきまして、例えばマスクなどの消耗品ですと、いろいろな何といいますか、お店で使う以外の用途でもいろいろと使えるようなところもあろうかと思います。そのような部分も含めまして、今回は助成の対象外というふうにしています。","voiceIndex":334,"id":"exchange-152"},{"speaker":"中塚委員","kind":"質問・要望","question":"お店で使う費用をきちんと分けているのです。本気で中小企業を支援しようというのであれば、消耗品であっても、お店で使うマスクや消毒液は、しっかりと助成対象にすべきだと強く求めたいと思います。そして、続いて申請期間なのですけれども、今年８月末で締め切られております。経済の落ち込みは深刻で長期的になっておりますので、申請を再び開始していただきたいと思いますが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"こちらの販路拡大支援助成ですが、申請期間は７月１日から８月３１日までということで実施させていただいたところです。","voiceIndex":336,"id":"exchange-153"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区家賃支援給付金について伺いたいと思います。事前に伺いましたが、先ほどのやり取りでも、簡単に言うと月の８割が国と区の給付金をもらえる、対象になるとのことですけれども、まず品川区のチラシを見ましたが、どのような手続きをすれば幾ら入るのかが全然分からない。幾らもらえるのかのモデルケースや申請の流れなど、分かりやすく改善すべきだと思いますが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"こちらにつきましては、１１月２日から実際には申請が受けられるような体制で、今進めているところです。こちらにつきましては、今この中身を全事業者に一応配布するような形で進めております。","voiceIndex":338,"id":"exchange-154"},{"speaker":"中塚委員","kind":"質問・要望","question":"元は国のようですけれども、ぜひ改善していただきたいと思います。先ほどもありましたが、この制度は、国の制度は６か月分が一度に支給されます。やはり中小企業の営業を確保し、経済を立て直すためにも、せめて国の６か月に合わせるべきだと思います。東京都に対して６か月とすることを求めること、そして品川区も６か月とすることを求めますが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"今回につきましては、いろいろと３か月、あるいは逆に１年などという部分もあろうかと思いますけれども、今回につきましては、いろいろと諸事情を勘案した結果、３か月というふうに決めさせていただいたです。","voiceIndex":340,"id":"exchange-155"},{"speaker":"中塚委員","kind":"質問・要望","question":"どのような諸事情をどのように勘案したのか伺いたいと思います。やはり今の状況は本当に深刻です。ぜひ東京都に対して６か月とすることを求めること、品川区も６か月とすること、これは最低、せめて国に合わせるべきだと思いますが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"私どもは、こちらの家賃支援給付金以外にも様々な助成制度をつくらせていただいているところです。今回の家賃支援給付金につきましては、いろいろとご意見はあるところですが、３か月というふうにさせていただいたところです。","voiceIndex":342,"id":"exchange-156"},{"speaker":"中塚委員","kind":"質問・要望","question":"理由を言えないのですよね。ほかもいろいろとやっているから３か月と、このような理屈はないと思います。最後に、この販路拡大支援助成も家賃支援給付金も、いずれもまずは今年度中の改善、拡充も求めますけれども、ぜひこれは一度きりではなく、来年も実施すべきだと思いますが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"当初想定されていなかったものが、今中小企業支援という形で実施されているところです。来年につきましても、そのときに適時適切な支援をさせていただきたいと思いますので、こちらの２事業も含めまして、様々な支援を考えていきたいと思います。","voiceIndex":344,"id":"exchange-157"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ今年度の支援の拡充、そして来年度への拡充、充実を強く求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":346,"id":"exchange-158"},{"speaker":"大倉委員","kind":"質問","question":"２８８ページ、清掃費からちょっとお伺いできればと思います。コロナの影響で外出が自粛されて、テイクアウトやデリバリーが増えている中でありますので、ごみの量について教えていただければと思います。","respondent":"工藤品川区清掃事務所長","answer":"それに対する我々の対応ですが、やはり増量に対してもしっかりと適正処理をしなければいけないと、このような観点から、ごみ収集、資源ともに、収集車両、臨時対策的な清掃車両を増加しまして、増便いたしまして、適正な処理に努めたところです。","voiceIndex":348,"id":"exchange-159"},{"speaker":"大倉委員","kind":"質問","question":"ごみの出し方等で、例えば収集作業車に入れたときにごみ袋が破裂してマスクが出てきたとか、飛び出してくるとか、ウイルスが付着している可能性のあるペットボトルやティッシュなどが出てくるというようなお話も聞いたことがありますので、そうした感染対策についてはしっかりとやられていると思いますが、その対策について教えていただければと思います。","respondent":"工藤品川区清掃事務所長","answer":"このことによりまして、ご家庭での感染を防ぐというところと、私どもの収集作業時の感染リスクも低減されるということで、そのような形で協力のＰＲ等をしています。","voiceIndex":350,"id":"exchange-160"},{"speaker":"大倉委員","kind":"質問・要望","question":"取組みで、私の近所の方が、毎回燃えるごみの日にごみ袋にお手紙を貼って、いつもありがとうありますという感謝のお手紙ということでいつもやられているのですが、私もいい取組みだなと思っていろいろと調べると、ほかの自治体などでもそうした取組みが行われていて、区のホームページ等でも紹介をされているのですけれども、そうした手紙については、結構そういった声があるのか。","respondent":"工藤品川区清掃事務所長","answer":"今後こういったところも、しっかりと発信してまいりたいと思っているところです。","voiceIndex":352,"id":"exchange-161"},{"speaker":"大倉委員","kind":"意見","question":"通信のほうで、今６００通あるようなものを紹介しながらお礼をしているということですが、これぜひ区の広報のほうともお話をしていただいて、ホームページ等を使って、ほかのＳＮＳの媒体でもいいと思うのですけれども、使って、いただいた感謝のお手紙にお礼を出すと同時に、併せて家庭でのごみの捨て方などの周知をして、さらに一層、感染症対策というところで取り組んでいただけると。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":354,"id":"exchange-162"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私は２８６ページ、環境費の中からリサイクル推進費、２８８ページ、清掃費、あと産業経済費もちょっと時間があれば、質問させていただきたいと思います。どうぞお願いします。ごみの関係です。その辺というものは、必ず有料シールを貼ってあるものなのか、それとも貼らないでそのまま出されているのか、その辺がどのようにチェックできているのか確認をさせてください。その点だけお願いします。","respondent":"工藤品川区清掃事務所長","answer":"ですから、有料シールを貼る、もしくは収集業者のほうに処理をお願いすると、このような形になりますが、マンションですと、ごみが少量ですので、有料ごみシール券を貼るような形になってあります。","voiceIndex":356,"id":"exchange-163"},{"speaker":"鈴木（真）委員","kind":"質問","question":"やはり区民の方の声の中で、マンションの中でそれがないというものが結構多い。それから別件のほうで、集団回収についてです。というのは、区で行政収集と集団回収の費用的にも、前もちょっとコストを考えたときには、集団収集の方のほうが安いというように、たしかお聞きした記憶があります。その辺を考えると、団体に対してもう少し支援ができないのかどうか、その辺についてお考えを教えてください。","respondent":"工藤品川区清掃事務所長","answer":"今後につきましては、やはり町会の皆様方のご苦労や取組み、リサイクルへの貢献、こういったところを総合的に私どもも検証しまして、報奨金等を含めまして、どのように支援をすればこの集団回収という活動が継続して、地域のモチベーションにつながっていくのかと。","voiceIndex":358,"id":"exchange-164"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"産業経済費関係です。先日、特別区長会の要望の書類を、ホームページに出ているのでちょっと見させていただきました。それは都の支援策を要望しているのだと思うのですが、区として、都に対してどのようなものを要望していくのか、その辺のお考えがもしあれば、あると思うので、その辺をちょっと教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"都への支援ということで、基本的には補助金という形になろうかと考えています。","voiceIndex":360,"id":"exchange-165"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それからもう１点、ごみの関係です。災害ごみの関係です。お話を伺った中では、世田谷は割合作業をするところに近かったのだけれども、大田はその場所がちょっと遠かったというような状況も聞きました。品川区からも、たしかお手伝いに行っていらっしゃると思うのですが、その辺どのように、その結果を区としてどのように活かしていかれるか、その点についてお考えを教えてください。","respondent":"遠藤商業・ものづくり課長、工藤品川区清掃事務所長","answer":"現在キャッシュレス化について、いろいろと商店街連合会との意見の交換などをさせていただいているところですが、まだちょっと勉強中ですので、今後これからまた検討していきたいと考えています。やはりこのような形で、実際の現場を見て、どういった状況だったのか、どういった形で処理をすればいいのかというところを、実際に私どものほうでも、派遣という形で十分勉強してまいりましたので、それを今ミーティング。","voiceIndex":362,"id":"exchange-166"},{"speaker":"鈴木（真）委員","kind":"質問","question":"災害ごみ、これは水の関係ですけれども、一般的というか、もし万が一の場合の災害ごみの関係になると、計画は防災になるかと思うので、また改めてそちらでお聞きします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":365,"id":"exchange-167"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1490#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":128912,"voices":366}},{"id":"r02-20201012-4","meetingId":"r02-c-settlement","date":"2020年10月12日","dateIso":"2020-10-12","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を170件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"小芝委員","kind":"質問","question":"私からは、３２１ページ、水辺利活用事業に関連して品川区の運河沿いでの釣りについて、また３４５ページ、品川区国民保護計画変更費について質問します。そこでまずお聞きいたしますが、例えばこのような運河沿いの土手で釣りをされている、その場所の管理権は品川区にあるのでしょうか。区内で実際に釣り場として、例えばホームページだとか、そういったところで周知しているような場所はあるのでしょうか。","respondent":"鈴木都市計画課長","answer":"区内水辺での釣りの状況ですが、現在、京浜運河の八潮側、都立京浜運河緑道公園になりますが、こちらのほうは干潟の自然保護区域や桟橋以外については、区の魅力の１つである水辺に親しむことが可能な区域として、釣り可能エリアとして既にＰＲ、周知がなされ。","voiceIndex":8,"id":"exchange-001"},{"speaker":"小芝委員","kind":"質問・要望","question":"管理は東京都が行っており、区は委託を受けているということを理解いたしました。１人で楽しむレジャーとして、感染のリスクの少ない釣りは、これからもっと需要が伸びてくると思われます。区議会自民党でも、先般、要望させていただきましたが、ぜひとも区のほうで釣り場の確保、場所の整備を今後も図っていただきたいと思いますが、区のほうでお考えがありましたら、お願いいたします。","respondent":"鈴木都市計画課長","answer":"今ご提案いただいた釣りは、ほかのアクティビティ等を含めて、品川区の魅力発信には、あるいは区民の水辺に親しんでいただく機会としては非常に重要なところですので、今後、そうしたスポットの整備、あるいはどういった釣りの在り方があるかというのは。","voiceIndex":10,"id":"exchange-002"},{"speaker":"小芝委員","kind":"質問・要望","question":"続きまして、３４５ページ、国民保護計画変更費についてお伺いいたします。今年の２月にテレビや新聞などでも毎日のようにニュースにありました横浜港に停泊していたダイヤモンド・プリンセス号、豪華客船ですが、これを見た方も多かったと思います。この国民保護計画の変更されたポイントについて具体的に教えていただきたいと思います。","respondent":"大森災害対策担当課長","answer":"委員ご案内のとおり、品川区の国民保護計画につきましては、平成１９年に策定いたしまして、その後、平成２５年３月に、Ｊアラートなどのシステムの導入に伴いまして大きく変更をかけたところです。それから、直近で令和２年３月に、再度、変更をかけたところです。","voiceIndex":12,"id":"exchange-003"},{"speaker":"小芝委員","kind":"質問","question":"国、東京都との整合性を図るというのは分かりました。私も変更された保護計画を読みましたら、その中に品川区以外、区外からの避難民の受け入れも入っていたと思いますが、そのとおりでしょうか。","respondent":"大森災害対策担当課長","answer":"そのため、避難誘導については、基本的には国とか都の指示に基づいて区が対応することになりまして、その中の１つの選択肢として、広域避難という観点から、区内から区外への避難、もしくは区外の方からの区内への受援、こういった形の想定もあります。","voiceIndex":14,"id":"exchange-004"},{"speaker":"小芝委員","kind":"質問","question":"そうなりますと、やはりこの地域の方にも、例えば避難誘導だとか、そういったところで協力をいただくようなこともあるかと思いますが、これまで防災訓練の中にもそういった武力攻撃事態を想定した訓練も行われてきたのでしょうか。","respondent":"大森災害対策担当課長","answer":"国民保護に関する防災訓練に関するお尋ねです。区では、この国民保護計画の変更に先立ちまして、令和元年９月に国民保護の図上訓練を行いまして、警察、消防、自衛隊といった関係機関と連携しながら訓練をしたところです。","voiceIndex":16,"id":"exchange-005"},{"speaker":"松澤委員","kind":"質問","question":"私からは、３１１ページ、道路バリアフリー事業、３２７ページ、公園・児童遊園費、３４３ページ、防災関係、３４５ページ、消防団運営費、３４７ページ、避難所等備蓄品について、順不同で質問します。この大井町駅、旗の台駅周辺のバリアフリー計画の概要と進展状況を教えてください。","respondent":"鈴木都市計画課長","answer":"旗の台駅周辺地区では、心身障害者福祉会館前区道の点字ブロックの補修、旗の台公園や荏原南公園のバリアフリー化改善整備、地域センターのだれでもトイレの高機能化など、バリアフリー化に取り組んでおります。","voiceIndex":19,"id":"exchange-006"},{"speaker":"松澤委員","kind":"意見","question":"点字ブロックは視覚障害者の方にはとても必要で、杖、車椅子、ベビーカーからは逆にバリアになってしまうことがあります。適材適所にほかの利用者のことも考え設置していくことが課題となりますが、ご見解をお聞かせください。","respondent":"溝口道路課長","answer":"今後も引き続き、お互いの方たちが利用しやすい点字ブロックの設置の仕方については、様々な整備をする段階で検討していきたいというふうに考えているところです。","voiceIndex":21,"id":"exchange-007"},{"speaker":"松澤委員","kind":"意見","question":"どうしても点字ブロックの上を通るときは、車椅子とベビーカーがちょっと通れるような隙間を空けてありました。落下や飛び出しなどの危険な場所、こういったところには黄色の警告ブロック、そして誘導ブロックは一本線として景観に配慮し同系色のゴム製にするなど、新しい設置方法の考え方もこれからの時代には必要になるのではないかと思いますが、ご見解をお聞かせください。","respondent":"溝口道路課長","answer":"ただ、やはり連続して誘導していく、視覚障害者の方にはそういったことも必要だという観点もありますので、そこはやはり両方の立場のご意見等を聞いて、しっかり考えながら、今後どのような形で整備していくのがいいのかというのは検討していきたいと考えているところです。","voiceIndex":23,"id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"いろいろとお話し合いの中でよりよいものができればいいと私も思っております。いろいろと点字ブロックについてお聞きしました。デパートのエレベーターも２つあります。ハード面だけではなく、教育、歩み寄るという部分にも力を入れるべきではないでしょうか。心のバリアフリーという観点で、道路のバリアフリーに対する今後の取組やお考えを教えてください。","respondent":"溝口道路課長","answer":"やはりハードだけではなかなかすぐに、道路を利用する方が安全・安心に歩行できる空間はできない部分もあると思います。そういったところでは、やはりソフト的な対応も必要だと考えています。","voiceIndex":25,"id":"exchange-009"},{"speaker":"松澤委員","kind":"質問・要望","question":"しかし、現状、まだまだ公園は限られた空間の中、公園利用者や近隣住民からの安全や騒音等の要望などが、様々な禁止看板が立てられており、規制された空間というイメージが定着しております。公園の多様な機能を発揮するためには、柔軟な利活用が求められるのではないでしょうか。そのためには、日常の維持管理と調整を図りながら、多様な地域ニーズに対応した一定のルールづくりが必要ではないでしょうか。","respondent":"高梨公園課長","answer":"公園が周辺にお住まいの方々に認められ、愛着を持ってもらうとともに、公園を訪れる方にとって快適に憩える場となるためには、地域の皆様の合意を持ってつくられた一定のルールづくりは今後も必要であると考えているところです。","voiceIndex":27,"id":"exchange-010"},{"speaker":"松澤委員","kind":"質問・要望","question":"時代とともに公園の在り方も変わっております。道路で子どもが遊んでいた時代、車社会になり交通事故が増え、子どもたちが安全に遊べる場として住宅街に公園が整備された１９９０年代に都市公園法が改正されました。その後、相次ぐ自然災害で地域の避難場所として位置付けられるように、利用者が求める価値観が多様化しております。品川区でも、こういった逆転の発想、そういったお考えはないのでしょうか。","respondent":"高梨公園課長","answer":"しかしながら、公園や児童遊園の大規模改修や新設の際に、園内のルールは、地域の皆様と相談しながら決めている現状がありますので、ご提案のできる看板の内容につきましても、選択肢の１つとして今後に活かしていきたいと考えております。","voiceIndex":29,"id":"exchange-011"},{"speaker":"松澤委員","kind":"質問・要望","question":"ただいま禁止看板に対して遊びを考えるというお話もありましたけれども、やはり禁止で縛ってしまうと、子どもが考える力がなくなってしまうのではないのかと私は感じております。公園の曖昧だった機能を静かに過ごしたい公園と、思い切り体を動かせる公園に分ける考え方、ドッグランの設置の考え方もそうですが、２５６ある品川区の公園の多様性を求める考えを広げていきたいと思いますが、いかがでしょうか。","respondent":"高梨公園課長","answer":"今後、時代により求められるニーズも変わってまいりますので、その時々のニーズをしっかりと捉えて、区民に愛される公園づくりを今後も進めてまいりたい、このように考えております。","voiceIndex":31,"id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"自分の子どももそうでした。公園でゲームをしている子どもにゲームばかりやらないで遊びなさいと私も結構声をかけてしまうのです。やはり地域コミュニティの大切なつながりの場である公園機能のさらなる充実を願いまして、次の質問に移らせていただきます。コロナ禍において、避難所における新しい運営マニュアルが作成されましたが、品川区標準版と比べてどのようなことが変わったのか教えてください。","respondent":"平原防災体制整備担当課長","answer":"私からは、避難所におきます新型コロナウイルス感染症対策を踏まえたマニュアルにつきましてご説明します。委員ご指摘のとおり、本年７月２０日に本区から各地域に対しまして、新型コロナウイルス感染症対策を踏まえた避難所運営のマニュアルをお配りさせていただいたところです。","voiceIndex":33,"id":"exchange-013"},{"speaker":"松澤委員","kind":"質問","question":"今、運営マニュアルを配ったというお話がありましたけれども、この運営マニュアルは、どなたにお配りして、また避難所連絡会議の方には、どういうふうに対応してくださいとか、そういった説明はされたのでしょうか。","respondent":"平原防災体制整備担当課長","answer":"それを受けまして、各地域で順次開催されました避難所連絡会議、こちらにつきましては本部長だけではなくて、各町会の役員の方も入っている会議ですが、そういった会議の場に、私ども区から、防災課の人間が中心になりますけれども。","voiceIndex":35,"id":"exchange-014"},{"speaker":"松澤委員","kind":"質問","question":"本部長といいますと、多分これは町会長になるかと考えていますが、実は、町会長も近隣の町会でもそういった説明がないと私はお聞きしております。多分、今、コロナ禍の中で、なかなか集まることができない中で説明ができていないのかとは思っておるのですが、だからこそやっぱりしっかり、こういったときこそ地域に連絡がいくようなシステムの構築が大事ではないでしょうか。例えばアプリです。","respondent":"平原防災体制整備担当課長","answer":"その中で防災マップにつきましても併せてご提供していく考えです。","voiceIndex":37,"id":"exchange-015","title":"町会・自治会支援"},{"speaker":"松澤委員","kind":"質問","question":"避難所に関連しまして、備蓄について質問します。コロナ禍において、マスクが不足する大問題が発生しました。災害対応のための備蓄マスクは、あくまでも災害時におけるものとして配布はありませんでしたが、今後、このような不測の事態において、備蓄品の活用をどうお考えなのか教えてください。","respondent":"平原防災体制整備担当課長","answer":"今回の新型コロナウイルス感染症の状況を踏まえまして、必要な備蓄品の増備、マスクにつきましても併せて増備を考えておりますし、先ほどありました避難所マニュアルのところでこれまでと考え方を変えたところにつきましては、必要な衛生資機材も準備させていただいたところです。","voiceIndex":39,"id":"exchange-016"},{"speaker":"松澤委員","kind":"質問・要望","question":"こういう災害は起こらないと言われていても起こってしまいます。本当に災害はいつ起こるか分からないということを私たちは経験いたしました。こういったことがあったときもしっかりと対応できるような組織づくりを目指していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-017"},{"speaker":"新妻委員","kind":"質問・要望","question":"３１３ページ、勝島歩道橋エレベーター等整備（南側）、３１７ページ、水辺のライトアップ整備、３２１ページ、八潮地区の将来像検討経費、３４９ページ、集中豪雨等対策費ということで順番にお伺いします。最初に、勝島歩道橋エレベーター等の整備についてです。この現状を確認させていただきたいのと、予定通りのスケジュールでこれが進んでいるのかということをまずお伺いいたします。","respondent":"溝口道路課長","answer":"北側の整備につきましては、今現在、更地になっておりますが、商業施設ができるというふうに聞いておりまして、それに併せて商業施設側のほうで２４時間稼働のエレベーターを整備するということで計画をしており、現在、事業を進めているところですが。","voiceIndex":43,"id":"exchange-018"},{"speaker":"新妻委員","kind":"確認","question":"すみません、もう一度確認します。今既に付いております南側のエレベーターは、まだ稼働していないと思うのですが、これはいつから稼働するのかということをもう１回確認をさせてください。","respondent":"溝口道路課長","answer":"説明が悪くて申し訳ありません。南側エレベーターの稼働状況です。","voiceIndex":45,"id":"exchange-019"},{"speaker":"新妻委員","kind":"質問","question":"分かりました。そして、この北側の設置につきましては、当初、品川区で造るというふうにも伺っておりましたけれども、民間がやるということで、令和４年度と今伺いました。地域からも、一体ここはどうなっているのかという声も上がっておりますし、早く設置してほしいという、そういう期待もあります。これが地元にはどのようにお知らせされているのかということをお聞かせください。","respondent":"溝口道路課長","answer":"ただ、やはり北側の建築が遅れているとかというところの周知が少し足りなかった部分はあると思いますので、事業者を含めて地域の方にはしっかり説明しながら進めていきたいというふうに考えております。","voiceIndex":47,"id":"exchange-020","title":"町会・自治会支援"},{"speaker":"新妻委員","kind":"質問・要望","question":"分かりました。どうぞよろしくお願いいたします。少し先のことになってしまいますが、１日でも早く整備されますように、取組を推進していただきたいと思います。もう１点、ここは自転車が乗せられるということも聞いておりましたけれども、予定どおり自転車が乗れるということを前提に整備されているのかということだけ確認させてください。","respondent":"溝口道路課長","answer":"今回整備しておりますエレベーターにつきましては、当然、ＪＩＳ基準等、基準をクリアした形での整備をしておりますので、自転車も入れるような大きさのものを整備しています。","voiceIndex":49,"id":"exchange-021","title":"町会・自治会支援"},{"speaker":"新妻委員","kind":"質問・要望","question":"続きまして、水辺のライトアップ整備についてお伺いいたします。対岸では、八潮地域の青少年対策委員会主催でハゼ釣りが催されておりまして、ここも例年になく大きな応募があったと伺っております。でも、ここは国道でありますので、実際には品川区が何かできることではありませんけれども、ぜひ国のほうに八潮橋のイルミネーション事業を働きかけていただきたいと思いますが、いかがでしょうか。","respondent":"松本河川下水道課長","answer":"先ほどお話があったように、昨年度、京浜運河にかかるかもめ橋、勝島橋にもライトアップをさせていただきました。国が管轄する八潮橋につきましては、今後、しっかり働きかけをしていきたいというふうに考えてあります。","voiceIndex":51,"id":"exchange-022"},{"speaker":"新妻委員","kind":"質問","question":"このイルミネーション化が進む中で、夜の屋形船がこのイルミネーションを見るために走ることができるようなことも期待しておりますので、どうぞよろしくお願いします。次に、八潮地区の将来像検討経費です。ガイドラインの作成もするということも伺っておりますけれども、現状と今後の展望をお知らせください。","respondent":"鈴木都市計画課長","answer":"今、ガイドラインのご紹介もいただきましたが、このガイドラインの策定に向けて、将来、建て替え後の姿というよりも、今お住まいいただいている八潮をよりよく住みやすく、さらによりよいまちにするために、このガイドラインを区としては定めていきたいというところで。","voiceIndex":53,"id":"exchange-023"},{"speaker":"新妻委員","kind":"質問・要望","question":"１０月１日、発行の保育園のしおりでは、八潮中央保育園の改修が１年延期されたスケジュールが出されておりました。都営の１階ですので東京都から借りている立場ではありますけれども、ゆくゆく、この八潮地域全体の将来像をどうしていくのかという在り方、区としてどうお考えになっているのかということも含めて、この八潮北保育園跡の活用についてお伺いいたします。","respondent":"佐藤企画調整課長","answer":"その後に関しましては、八潮地区の行政需要でありましたら、地元のお声をお聞きしながら、どういった施設が適切なのかということを併せて検討していきたいと考えております。","voiceIndex":55,"id":"exchange-024"},{"speaker":"新妻委員","kind":"質問・要望","question":"失礼いたしました。最後に、土のうの置場についてお伺いいたします。そして、これは基本的にはこれまでに水害があったところに置かれていると認識しているのですが、区内全体でのそういう意識が高まっていることから、この土のうの置場の拡充を求めたいと考えていますが、土のうの置場の様々な条件ですとか、何かそのようなことがあるのか、拡充できるのかどうかお伺いしたいと思います。","respondent":"溝口道路課長","answer":"土のう置場につきましては、最近、災害が大きくなってきているという区民の方の認識のもと、利用が増えてきているのだというふうに感じているところではあります。","voiceIndex":57,"id":"exchange-025"},{"speaker":"新妻委員","kind":"質問・要望","question":"増えたところはできるだけホームページにも公開をしていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"３４９ページの集中豪雨等対策費について、近年巨大化する台風など豪雨災害について伺いたいと思います。それだけに十分な計画や事前の訓練を重ねる必要があります。自主避難施設の開設や土砂災害、目黒川氾濫、高潮による立会川氾濫による避難所の開設にあたって、毛布１枚の支給ではなく、環境改善へ最低限、水、食料、パーテーション、ベッドの設置を行うことを求めますが、いかがでしょうか。","respondent":"平原防災体制整備担当課長","answer":"避難所における環境改善についてですけれども、水や食料につきましては、まずは持参していただくことを呼び掛けるものではありますけれども、必要とする方につきましてはお渡しするとともに、今年度の予算や今回の補正予算でお認めいただきましたパーテーションなど。","voiceIndex":61,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"事前に水や食料を持参してくださいと呼び掛けること自体は別に構わないと思うのです。気象庁は、特別警報の運用を開始しております。品川区全域に気象庁が大雨特別警報を発表することが予測されることが示されたとき、品川区民がとるべき行動を示した行動計画はあるのか、その内容のポイントは何か、伺いたいと思います。","respondent":"平原防災体制整備担当課長、中島防災課長","answer":"避難施設におきます避難環境を少しでもよくするため、様々な資機材、物資を活用することしておりまして、さらには。万一、特別警報が発表された場合に関しましては、非常な豪雨の中で避難をするというのは危険な場合もありますので、例えば自宅の２階に上がるとか、命を守る最善の行動、そのようなものを情報発信してまいりたいと思います。","voiceIndex":63,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"大雨特別警報は、確かに数十年に一度と言われておりますが、近年は毎年のように各地で示されている。やはりこうした被害が予測される事態になったときには、浸水ハザードマップに示された浸水想定区域と、その周辺にお住まいの方の具体的な行動、またエリア外にお住まいの方の具体的な行動を示した住民の行動など、エリアを分けた行動の徹底が大切だと思いますが、いかがでしょうか。","respondent":"中島防災課長","answer":"基本的に品川区に関しましては、昨年の台風を踏まえまして、現在のところ、１,２００人の避難という基準で検討を進めているところですが、様々情報発信をしていく中で、例えば個人の避難行動を時系列でタイムラインとして計画していただくような周知をしています。","voiceIndex":66,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"タイムラインの啓発に努めていきたいということですが、まだまだ住民には十分に届いていないという実感があります。大雨特別警報が発表されることが予測され、品川区内全域が対象となることは十分あり得ます。ぜひ住民がとるべき計画の徹底、住民が参加する水防訓練などの実施も検討していただきたいと思いますが、いかがでしょうか。","respondent":"中島防災課長","answer":"防災の観点からいたしましても、避難訓練も検討しているところでございまして、例えば避難行動要支援者の避難訓練とか、そういうことも実施に向けまして検討しています。","voiceIndex":68,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"とりわけ自分で移動が困難な方、移動するのに支援が必要な方にとっては、とても不安な経験をしたとお話を伺いました。幸い、昨年は重大な水害の被害は発生しなかったのですが、いつ起きてもおかしくないと考えています。要支援者への支援も重点的にぜひ実施していただきたいと思いますが、改めて水防訓練や一人ひとりのタイムラインに沿った計画の策定などを求めたいと思いますが、改めていかがでしょうか。","respondent":"中島防災課長","answer":"水防に関しましては、かねてから区職員の訓練等に努めているところですが、やはり区民と一丸となった防災対策という観点では、避難行動要支援者の個別計画、これは震災のほうでも、今、福祉部と連携しまして取り組んでいるところですが、そちらをまた一層強化していくということ。","voiceIndex":70,"id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に一言。強化するということで、タイムラインも作っていきたいということですけれども、今週、来週起きてもおかしくない台風の被害でありますから、職員の方にはもちろん大変なご苦労をかけるかと思いますが、ぜひ住民の命を守るために力を尽くしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"私からは、３１７ページ、水辺利活用事業に関連して、３３９ページ、マンション管理支援事業、３１７ページ、治水対策費からお伺いいたします。品川区の舟運、水辺活用に、この東京国際クルーズターミナルの活用をするべきではないかと２年程前からお伝えしているところであり、今年の予算特別委員会の総括質疑でもお伝えしたところです。この内覧会に区長がご出席された経緯と理由をお聞かせください。","respondent":"鈴木都市計画課長","answer":"当初からこのクルーズターミナルにつきましては、区としても非常に品川区と近い、近接しているということもあって、いろいろ関係部署の中で、帰属ですとか、そうしたところも含めて調整をしてきたところで、お声がけがあった中での内覧会参加です。","voiceIndex":74,"id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。当然その逆も行けるということになります。舟運水辺活用を推進する品川区ですから、区民の子どもたちの教育にもよい効果が期待できるかと思います。ぜひ品川区の舟運の発展のために、舟運が区民に期待される日常の足となるために、クルーズターミナル近くの青海小型船発着所浮桟橋の活用を所管の東京都港湾局と粘り強い協議の上、積極的に進めていただきたいと思いますが、いかがでしょうか。","respondent":"松本河川下水道課長","answer":"当初、オリンピックに合わせて実施する予定でしたが、今、新型コロナウイルス感染症の状況でありまして、今後の実施に向けて検討を進めているところです。","voiceIndex":76,"id":"exchange-034","title":"町会・自治会支援"},{"speaker":"筒井委員","kind":"質問","question":"私もポテンシャルは非常に高い場所だと思いますので、ぜひご活用をお願いします。品川区の舟運、水辺活用の東京湾進出、ダイナミックな展開、そしてそのことから区民の日常の足となることを期待しまして、次の質問に移らせていただきます。","respondent":"森住宅課長","answer":"マンション管理支援事業についてです。区では、マンション管理セミナーとして年２回、防災対策等検討交流会も併せて実施しています。","voiceIndex":78,"id":"exchange-035"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。やはり防災また大規模修繕というのは一番関心が高いのかと思います。いろいろな住民のお考えがありますけれども、それらがやはり共通して関心が高い事項かと考えております。そうしたことで、今後、国は２０２２年に管理計画認定制度というものを創設されるです。今年４月から始まった東京都の管理状況届出制度との関係性、重複するところはないのか、それら３点、お伺いいたします。","respondent":"森住宅課長","answer":"東京都の条例との関係性ですが、こちらもまだ整合性がどこまでとれるのかというところも含めて、都と国で検討されているというふうに聞いてあります。","voiceIndex":80,"id":"exchange-036","title":"町会・自治会支援"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうしたことで国も動き出したと思うのですけれども、東京都の管理状況届出制度があるにもかかわらず、国もさらに出したということで、二重になってしまうところがあるのかということ、どうなるのかということがちょっと懸念されるところなのですけれども、その辺り、引き続き、品川区としても注視していただき、また、マンションは品川区にももう既に結構たくさんありまして、また今後。","respondent":"森住宅課長","answer":"周知につきましては、東京都と連携し、東京都では、例えば公共機関の吊り広告であったり、そういった部分でしっかりとＰＲしていきたいというふうに申しておりますので、区もそれと連携しまして、しっかりとＰＲをしていきたいというふうに考えております。","voiceIndex":82,"id":"exchange-037"},{"speaker":"筒井委員","kind":"質問・要望","question":"昨年も台風第１９号によりまして、武蔵小杉でマンション浸水事故が起きました。浸水を防ぐ、浸水被害の軽減という事業の趣旨・目的からしますと、そもそも扉自体を防水扉にしてしまったほうが、浸水防止、地下発電機の被害を防ぐ、浸水被害の軽減という効果は高く効率的かと考えるので、防水板に加えて防水扉の設置等工事の助成も行っていただきたいと思いますけれども、ご見解はいかがでしょうか。","respondent":"松本河川下水道課長","answer":"現在、当課で行っております防水板設置等工事助成事業ですが、大雨、洪水、高潮などによる浸水被害の軽減のために、住宅、店舗、事務所などに防水板の設置および防水効果を高めるなどの関連工事の一部に対して助成をする制度です。","voiceIndex":84,"id":"exchange-038"},{"speaker":"筒井委員","kind":"質問・要望","question":"それらは、恐らく地下発電機かと思われますので、そうしますと、台風とかで浸水して発電機が止まってしまったら停電になる、そして住民の生活が一時止まってしまうということになってしまいますので、いっそのこと防災扉のほうが、より事業の趣旨・目的の効果を達成しやすいと思うのですけれども、ぜひ検討を行っていただきたいのですけれども、その点についていかがでしょうか。","respondent":"松本河川下水道課長","answer":"今の助成制度ですが、今お話のありましたタワーマンションだとか、そういった地下に設備等がある場合には、やはりマンションを造る際に防災扉を付けるべきだというふうに考えております。私たちの今の助成につきましては、既存のある建物等でそういった……。","voiceIndex":86,"id":"exchange-039"},{"speaker":"田中委員","kind":"質問","question":"３１９ページ、３項１目雨水流出抑制推進事業、３２１ページ、４項１目やさしいまちづくり整備費、３２５ページ、３目大井町駅周辺地区再開発事業、３４１ページ、６項１目居住支援協議会について伺います。大井町駅周辺地区再開発事業、広町地区について伺います。過日の他会派の一般質問の答弁で、土地区画整理事業の活用を検討しているとありました。","respondent":"多並都市開発課長","answer":"この土地区画整理事業を今回の地区についての事業として検討を進めているところのポイントといたしましては、土地を再編する、今ちょうど駅のほうに区の土地があり、また、今ある現庁舎の離れたところにあるところをＪＲ東日本の土地と合わせながら。","voiceIndex":89,"id":"exchange-040"},{"speaker":"田中委員","kind":"質問","question":"広町地区の公有地は、区の公有財産の管理、区の規定や条例から離れてしまうのでしょうか。ご説明ください。事業の中で区民の財産が勝手に使われてしまうのではないかという不安がよぎります。区民の財産に関わることなので、区民に対して丁寧な説明が必要だと考えますが、見解を伺います。先ほど、土地区画整理事業の有効性といったことが話されていましたが、そこの理由についてももう一度お知らせください。","respondent":"多並都市開発課長","answer":"使い方についてでありますが、基本的な考え方としては、まずは土地の区画を再編して、今よりもより大井町の周辺のまちづくりに発展できるようにということで、今回も大井町駅周辺地域まちづくり方針という形で方針をまとめさせていただきまして。","voiceIndex":91,"id":"exchange-041"},{"speaker":"田中委員","kind":"質問・要望","question":"続けます。行政機能・にぎわい集積ゾーンと、駅側の新たな都市機能集積ゾーンでは浸水想定区域が異なりますが、浸水想定区域について、どのような議論がされて、このようなゾーン分けがされたのか伺います。土地区画整理事業によって、土地を公平に負担して土地の再編を図るという中で、浸水想定区域とそうでない区域での公平な負担は、どのように検討がされているのか、区の見解を伺います。","respondent":"多並都市開発課長","answer":"ベースとなるところの検討を今進めているところで、併せて、今度は細かいところについて、各事業者と協議しながら進めなければいけないところです。","voiceIndex":93,"id":"exchange-042"},{"speaker":"田中委員","kind":"質問","question":"分かりました。詳しいことは今後聞きたいと思います。行政機能・にぎわいゾーンの中では、新庁舎建設の検討がされています。庁舎機能検討委員会では、新庁舎の候補地について、今後、変更する可能性があるのか問われた区は、現在示している候補地以外の選択肢はないと発言をしています。ほかに選択肢がないとする理由を伺いたいと思います。","respondent":"多並都市開発課長","answer":"ここの中で、現庁舎が老朽化または様々な新しい機能が必要だということで、現在、庁舎機能検討委員会を開きながら、どのような機能が必要かということを検討しています。","voiceIndex":97,"id":"exchange-043","title":"町会・自治会支援"},{"speaker":"田中委員","kind":"質問","question":"選択肢がないとする理由を伺ったので、もう一度伺えればと思います。先へ進めます。現在優先すべき施策として、新型コロナウイルス感染症対策があります。このことからも拙速にまちづくりを進めていくのではなく、住民への丁寧な説明を行い、相互理解が進む時間を十分にとっていく必要があると主張し、次の質問にいきます。各駅の計画の進捗状況は先ほどの質疑から伺いました。","respondent":"鈴木都市計画課長、榎本総務部長","answer":"今ご紹介いただきました大井町、旗の台以外の重点地区化ですが、現在のところ、特定の地域を取り上げて導入に向けて検討を開始しているという状況はございません。要は、容積としてどれぐらい入るか、ざっくりですけれども、入るのは今より大きくなければ移転する意味がないですから、そういった意味で候補地としては広町のところになるです。","voiceIndex":99,"id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"障害者、高齢者、乳幼児やその保護者、ケア者、介護者などの当事者から歩きづらい場所等を聞き取り、駅周辺に限らず、区内全域でのバリアフリーを進めてほしいと要望しますが、区の見解を伺います。やさしいまちづくり推進協議会に関わっていたと思いますが、２０１８年を最後に開催されていないのでしょうか。京急側は設置に向けてどのような見解を示しているのか、協議の進捗も併せて伺います。","respondent":"溝口道路課長、鈴木都市計画課長","answer":"今後も様々なバリアフリーに対するご要望があると思いますので、機会を見ながら、関係団体等のご意見も聞きながら整備に努めていきたいと考えているところです。やさしいまちづくり推進計画が地域福祉計画のほうに統合されたというご紹介をいただきましたが、基本的な考え方として、やはりやさしいまちづくり推進計画は、ハード、ソフト両面からバリアフリー化。","voiceIndex":102,"id":"exchange-045"},{"speaker":"田中委員","kind":"提案","question":"土地がなくてという答弁がちょっとよく分からなかったのですけれども、２０１５年から生活者ネットワークは主張していますが、区は、先ほどもありましたホームドア設置などに助成を出しているのですから、区民要望の多い場所や、今回のような請願採択のあった場所については、優先的に区が率先して設置に向けた提案を事業者にしていってほしいと改めて要望いたします。雨水流出抑制推進事業について伺います。","respondent":"松本河川下水道課長","answer":"雨水利用の促進に向けてタンクの設置費の助成を行っているところです。浸水対策だったり、水の利用について助成をしています。","voiceIndex":105,"id":"exchange-046"},{"speaker":"田中委員","kind":"質問","question":"ぜひ拡充をお願いしたいのですけれども、そこの見解を伺います。","respondent":"松本河川下水道課長","answer":"拡充につきましては、こちらは東京都との協議等もありますので、東京都とその辺のことにつきまして話合いをしていきたいというふうに考えてあります。","voiceIndex":107,"id":"exchange-047"},{"speaker":"松本委員","kind":"質問","question":"本日は、３０７ページ、シェアサイクル事業について、３０９ページ、デザインマンホール蓋設置等について伺います。シェアサイクル事業についてですが、平成３０年に区は株式会社ドコモ・バイクシェアと、都内初となる災害時におけるシェアサイクル使用等に関する協定を締結しています。協定上の災害の定義は、災害対策基本法上の災害でいいのか。これまでこの協定の活用実績があるのか伺います。","respondent":"稲田土木管理課長、中島防災課長","answer":"実績は現在のところありません。繰り返しになりますが、こちらのシェアサイクルの活用については、これまで実績はございません。水害のときに使うかどうかですが、実際のところ、台風や大雨のときに自転車で行くかというと。","voiceIndex":110,"id":"exchange-048"},{"speaker":"松本委員","kind":"意見","question":"国会でも新型コロナウイルス感染症が災害対策基本法上の異常な自然現象に該当するのかというのは、これは議論がされていたところだと思います。なかなか想定は難しいとは思うのですけれども、シェアサイクル協定上、この新型コロナウイルス感染症などの感染症が災害ということで対象になっていくのかどうか、そこをお願いいたします。","respondent":"中島防災課長","answer":"こちらの協定につきましては、あくまで現時点では自然災害を想定していますので、そちら以外のところについては基本的には対象外というふうに考えているところです。","voiceIndex":114,"id":"exchange-049"},{"speaker":"松本委員","kind":"質問・要望","question":"これは要望です。災害時に、協定上、自転車は使用できるのだけれども、ポートまで遠いということになると、せっかくの協定がなかなかうまく活用できなくなってしまうのかというふうにも思います。ですので、地域センター周辺にもポート整備をしていけるように、区として計画的にドコモ・バイクシェアと、あるいは周辺地権者と協議していくべきかというふうに思うのですけれども、ご見解をお願いいたします。","respondent":"稲田土木管理課長","answer":"今年度４月から本格実施に移ったのですけれども、なかなかやっぱり荏原地区とかは、全体から見ると少ないというような状況もありますので、災害時の活用だけに限らず、シェアサイクルのポート等も増やしながら事業を進めていきたいというふうに考えております。","voiceIndex":116,"id":"exchange-050"},{"speaker":"松本委員","kind":"意見","question":"今、荏原地区というふうな話が出ましたけれども、確かに荏原地区のポートはちょっと少ないかなというふうに私も地元に住んでいますので思うのです。その荏原地区に関しては、逆にポートが少ないということもある一方で、あそこはかなり人口も密集している。これはやっぱり区としても対策というか、何かしら考えていかないといけないのではないかと思うのですが、この見解をお願いいたします。","respondent":"稲田土木管理課長","answer":"ポートに自転車があふれているというような話とか苦情等は区のほうにも入ってきており、私も現場等々を見て回っているところですが、なかなかこれをバランスよく均等に配置するところは難しいところではありますが、事業者はトラックを用いまして、いろいろなところに。","voiceIndex":118,"id":"exchange-051"},{"speaker":"松本委員","kind":"意見","question":"やっぱり抜本的な解決の１つの方法としては、ポートを増やしていくということかと思いますので、引き続きご努力をお願いしたいと思います。次に、デザインマンホール蓋設置等についてですけれども、こちらは平成３０年度の決算額だと６６万円程度だったのですけれども、平成３１年度（令和元年度）は約４７０万円と７倍以上になっています。","respondent":"溝口道路課長","answer":"ただ、令和元年度（平成３１年度）の予算につきましては、現地でデザインマンホールの設置をしており、その分、工事費等がかさんだことによって決算額が大きくなっております。","voiceIndex":120,"id":"exchange-052"},{"speaker":"松本委員","kind":"質問","question":"一方で、令和２年度の予算だと、デザインマンホールに関連する予算が計上されていないということなのですけれども、これは増やす予定がないのかと、あと、マンホールカードとかも増刷するとか、そういう費用があり得るのではないかと思うのですけれども、この辺りはどうなのでしょうか。","respondent":"溝口道路課長","answer":"今年度につきましては、道路課の事務費の中で少し考えておりまして、新たに今年度、武蔵小山のほうに、スクエア荏原においてマンホールカードの新たな配布等を行っておりますので、その分の事務的経費は予算で進めるところです。","voiceIndex":122,"id":"exchange-053"},{"speaker":"松本委員","kind":"質問・要望","question":"これは面白いことに広告代もＫＡＤＯＫＡＷＡからもらっているということで、こういった企画、実は品川区にはサンリオだけではなくて、ゲームメーカーのセガもあるということで、こういったところもぜひ協議していただきたいと思いますが、いかがでしょうか。","respondent":"溝口道路課長","answer":"区民の方に親しんでいただく、来ていただく、そういったところの１つのツールだと考えていますので、様々な手法を検討していきたいというふうに考えております。","voiceIndex":124,"id":"exchange-054"},{"speaker":"芹澤委員","kind":"提案","question":"併せて、３４５ページの防災体制整備費で、ドローンについて幾つかお伺いしますけれども、その前に１点確認で、以前、仙台市のほうで未確認飛行物体が来て、その対応をする際に、いろいろなところが気象庁ではありませんとか、自衛隊のほうでも関知していませんというような様々なことがあったと思うのですけれども、これは所管が違えばおっしゃっていただきたいと思いますが。","respondent":"森住宅課長、中島防災課長","answer":"私からは、住宅補修緊急支援事業、住宅課のほうで実際の事務を行いましたので、その部分についてご説明します。私からは、未確認飛行物体に関するお問合せにつきましてですが、こちらは災害対策というよりも危機管理事象の範疇と推察されますので、当然、危機管理の部署等が適切に対応するところではありますが、防災課といたしましては。","voiceIndex":127,"id":"exchange-055"},{"speaker":"芹澤委員","kind":"質問","question":"住宅補修に関しては、非常にいい前例ができたと思っていますので、引き続き柔軟な対応を続けていただければと思います。ドローンに関しては、順次人数、あと機器を増やしていくというようなお話がありました。次に、防災タブレットについてもお伺いします。防災タブレット、これから新しくなるというふうに伺っておりますけれども、まず新旧で何が変わったのかをお聞かせください。","respondent":"中島防災課長、平原防災体制整備担当課長","answer":"実際に飛ばす際は、必要な許認可を得てやっているところでございまして、ほかの場所、市街地での練習などでは、恐らく条件等々もまた変わってくると思いますので、可能かどうか、その条件についても確認をしてまいりたいと思います。私からは、防災タブレットにつきましてお答えします。ご案内のとおり、防災タブレットは、今年度、更新を予定しております。","voiceIndex":130,"id":"exchange-056"},{"speaker":"芹澤委員","kind":"質問","question":"ドローンに関しては、今お話しいただいたとおり、上から俯瞰して見るということで、いつもの景色とは違うわけです。そうすると、無線ＬＡＮの整備というようなものもたしかどこかに経費として入っていたように理解をしているのですが、この無線ＬＡＮ、Ｗｉ－Ｆｉの接続がなくても、同じように４Ｇなりで接続ができるという認識でよろしいでしょうか。","respondent":"平原防災体制整備担当課長","answer":"こちらのネット環境ですけれども、今度新たに導入することを検討しておりますタブレットにつきましては、通常はＬＴＥ回線です、いわゆる通常のキャリア回線を用いて通信することを考えてあります。","voiceIndex":133,"id":"exchange-057"},{"speaker":"芹澤委員","kind":"質問・要望","question":"国が指定する災害の扱いと、新型コロナウイルス感染症はまた別だと理解をしていますけれども、今回の新型コロナウイルス感染症の拡大によって、何か防災協定を使ったものがあるのかどうか、まず１点お聞かせいただきたいのと、あと、今回の新型コロナウイルス感染症で、防災の考え方が少し変わってきたのかと思うのですが。","respondent":"中島防災課長","answer":"災害時というところで、今ずっと運用してきている協定ですので、それをすぐほかの事象に展開していくというところまでは、まだ調整していないところです。基本的には現状の災害を中心に協定は運用していきたいというふうに考えてあります。","voiceIndex":135,"id":"exchange-058"},{"speaker":"芹澤委員","kind":"質問","question":"ほかにも物資の提供という意味で言えば、これまで通常の防災協定の中では、飲料水の提供であったりとか、様々な物資の提供も協定の中に入っていると理解しています。最後に、水辺千本桜計画推進費についてお伺いしていきます。目黒川沿いを中心にして、水辺に千本桜をというふうに区長の発信でこの計画をつくっていただいたと思っていますが、まずこちらの計画の進捗をお聞かせください。","respondent":"中島防災課長、溝口道路課長","answer":"協定につきましては、例えばマスクなどにつきましては、今回は防災課の管理している備蓄も活用して対応してきたところでございまして、そういうほかの災害以外の事象について。水辺千本桜計画につきましては、２０２０年まで、オリンピックの開催が予定されていたときまでに水辺に桜を整備していこうということで、平成３０年から事業を始めております。","voiceIndex":137,"id":"exchange-059"},{"speaker":"芹澤委員","kind":"質問・要望","question":"水辺千本桜計画についてですが、今お話しあったとおり、１,０００本を達成したということで、私の会派からの要望でもありますけれども、１,０００本を達成したということで、ここで水辺の桜の計画をもう中止にしてしまうというか、完了としてしまうというふうにせずに、ぜひ品川区の桜はすごいねというふうに思ってもらうには、もう一声、桜の植樹が必要なのかと思っています。","respondent":"溝口道路課長","answer":"そういった中で、場合によってはさらに増やしていく、さらに拡充していく、そういった考えもありますので、まずはしっかり管理して皆さんに目黒川沿いの桜を知っていただく、そういった取組につながっていければというふうに考えているところです。","voiceIndex":140,"id":"exchange-060"},{"speaker":"せお委員","kind":"質問","question":"３２９ページ、子どもたちのアイデア等を活かした公園づくりから何点かお聞きします。そこで、ワークショップの際に作成されたアイデアブックですが、大井坂下公園整備の設計の際、どのようなアイデアが採用される、または採用されたのでしょうか。今回、残念ながら採用されなかったアイデアは、今後どのように活用されますでしょうか。お聞かせください。","respondent":"高梨公園課長","answer":"そのアイデアをいただきまして、通常のシートに加えて背もたれ付きのシートであったり、複数人で乗れるような少し大きめなシートを備えたブランコを、今、実施設計中の大井坂下公園で採用する予定となっております。","voiceIndex":144,"id":"exchange-061"},{"speaker":"せお委員","kind":"提案","question":"今回、子どもたちの考えは柔軟で、特別支援学校の生徒が発言したりとか、特別支援学校の先生から提案などがあったりすると、すぐそれに合わせて考えてアイデアが出てきたりしていました。これから区内の施設や取組を検討する際に、障害がある子もない子も一緒に行うワークショップをぜひとも様々な場所で実施していただきたいと、これは要望したいと思います。","respondent":"高梨公園課長","answer":"しかしながら、インクルーシブの視点につきましては、これからますます重要視されていくものと区としても考えておりますので、このような視点を意識しながら、遊具改修の際にも検討していきたいと思います。","voiceIndex":146,"id":"exchange-062"},{"speaker":"せお委員","kind":"質問・要望","question":"例えば、ベンチ１つをとっても、背もたれがあるほうが、高齢者にも、あと座位が保持できないお子さんにも使いやすいかと思います。ぜひともその辺も考慮していただき改修していただきたいと要望いたします。次に、都立林試の森公園に関してです。今年の予算特別委員会でのご答弁で、都に要望を伝え、働きかけていくとありましたが、その後、何か変化はありましたでしょうか。お聞かせください。","respondent":"高梨公園課長","answer":"その検討に際しまして、品川区へも地元自治体ということで意見照会が行われました。区といたしましては、公園機能の拡充にあたり、品川区が予定しております社会福祉施設等との機能連携について、積極的な協議、検討を要望しています。","voiceIndex":148,"id":"exchange-063"},{"speaker":"せお委員","kind":"質問・要望","question":"東京都もインクルーシブ公園の整備を進めていますので、改めて連携を強めていただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-064"},{"speaker":"くにば委員","kind":"質問","question":"３０５ページ、屋外広告物取締事務です。これは具体的にどのような内容、理由でしょうか。もう１点、屋外広告物条例違反の悪質な業者に対しては、過料、罰金などがありますが、注意、指導を超えて実際に過料、罰金を科した事案は年間何件程度ありますでしょうか。このような悪質な事業者に対して、区はどのような対策を講じていますでしょうか。","respondent":"稲田土木管理課長","answer":"屋外広告物等の除却件数についてお答えいたします。","voiceIndex":152,"id":"exchange-065"},{"speaker":"くにば委員","kind":"質問","question":"その植木鉢、プランター等に関して、急増しているように感じるのは、それは取締りの基準が厳しくなったからでしょうか。その他の点もまとめて質問します。関係者の皆様にご努力いただいているのですけれども、平成２８年度１,２５６件から令和元年度１,４６７件と、一進一退でなかなか減少していないのが実情ですけれども、この理由についてどのように分析していますでしょうか。","respondent":"稲田土木管理課長","answer":"そんなに変化がないのではですが、区としましては、パトロール強化、道路課とも連携をしながら現状を把握しながらやっているところでございまして、先ほどもちょっと言いましたけれども、植木鉢とか、そのときは片づけるのですけれども。","voiceIndex":154,"id":"exchange-066"},{"speaker":"くにば委員","kind":"質問","question":"続きまして、緊急時連絡用通信機器についてですけれども、こちらは７月にＰＨＳが停波したため、スマートフォン５２台を業務用に支給したとのことですけれども、今回の分と、既に区からスマホを支給されている方は対象から外して、携帯電話のみをお持ちでスマホを持っていない理事者の方など、どの程度いらっしゃるのでしょうか。これはもちろん区長、副区長も含めてです。","respondent":"平原防災体制整備担当課長","answer":"そのような取扱いとさせていただいているところです。","voiceIndex":156,"id":"exchange-067"},{"speaker":"くにば委員","kind":"質問","question":"今ちょっと答弁漏れがあったのですけれども、先に質問のほうをいきます。今回支給の５２台には防災時の連絡用として何か統一したアプリをインストールしましたでしょうか。現在、発災時の連絡方法はどのようにしていますでしょうか。今後、アプリを活用した庁内での連絡・連携についての方針もお聞かせください。","respondent":"平原防災体制整備担当課長","answer":"あるいは、それに安否確認機能が付いておりますので、それで返答していただいて職員の安否を把握できる、そういったもので導入させていただいているところです。","voiceIndex":158,"id":"exchange-068"},{"speaker":"くにば委員","kind":"意見","question":"最終的に携帯電話のみをお持ちでスマホを持っていない理事者の方がいらっしゃるかどうかというのは分からなかったのですけれども、今、スマホにＬＩＮＥのアプリを入れているということで、そちらのＬＩＮＥのアプリのグループ、やっぱり相互に連絡ができるというのが非常に活用できて便利な部分だと思います。最後、八潮地区の将来像検討経費です。その点をお聞かせください。","respondent":"鈴木都市計画課長","answer":"平成２９年度よりまちづくり検討を開始しています。","voiceIndex":160,"id":"exchange-069"},{"speaker":"くにば委員","kind":"質問","question":"最後、端的な数字が分かれば。八潮地区、まだ耐用年数が３０年あるというふうにおっしゃっていましたけれども、この検討事業はいつぐらいまで続ける予定でしょうか。例えば、あと２０年間ずっと検討ばかり続けていると、かなりの予算がかかってしまいます。検討をいつまで続けるかお願いします。","respondent":"鈴木都市計画課長","answer":"平成２９年度から昨年度までの決算ですが、１,２４０万円余です。それから、検討ですが、基本的には来年度をもって、まちづくりのガイドラインを取りまとめて行っていきたいです。","voiceIndex":162,"id":"exchange-070"},{"speaker":"つる委員","kind":"質問・要望","question":"３４７ページ、防災行政無線管理費、３０５ページ、交通安全啓発費、３０９ページ、道路安全施設費、３３７ページ、コンクリートブロック塀等安全化支援事業、３０７ページ、駅周辺等放置自転車対策事業、３１１ページ、道路バリアフリー事業について伺っていきます。今日は子どもたちの安全・安心という視点でそれぞれ確認をさせていただきたいと思いますが、まず防災行政無線に関してです。","respondent":"平原防災体制整備担当課長","answer":"ただいまご質問のございました防災行政無線、１７時のチャイム「夕焼小焼」ですけれども、１９８９年（平成元年）に公募を行いまして、それ以降、「夕焼小焼」を放送させていただいているところです。","voiceIndex":165,"id":"exchange-071"},{"speaker":"つる委員","kind":"提案","question":"自治体によっては、季節を感じられる曲というか、季節によって四半期に一度、曲を変えたりとか、また、地元地域の出身の芸能の方で、例えばＸ ＪＡＰＡＮの曲をかけているとか、ウルトラセブンの曲をかけているとか、自治体によっていろいろあると思うのですが、過去にもそういう提案もありましたけれども、例えば、この曲について、私は「夕焼小焼」は大好きでありますけれども、いろいろな。","respondent":"平原防災体制整備担当課長","answer":"冒頭ございましたとおり、私ども、１７時のチャイムにつきましては、防災行政無線がきちんと機能しているかという試験を目的に実施しているものですけれども、例えば防災以外の効果につきまして、どのような形で使うことができるのかとか、あるいは、私ども自体は、今現在。","voiceIndex":167,"id":"exchange-072"},{"speaker":"つる委員","kind":"質問・要望","question":"次にいきます。決算ですので実績を見ると、例えば除去については６０件、フェンスについても６０件やる予算の中で、最終的な決算としては、除去が２２件で、フェンスが７件というふうになっています。そうしたところは、この条件から外れてしまうのですが、そうしたところに対する支援策もこの中で活用できるのかどうか、併せて教えてください。","respondent":"長尾建築課長","answer":"今年度に関しましては、半年程度ですけれども、おおむね３０件程度の除却助成の申請を受け付けているところで、昨年度と比べましても引き続き伸びているような状況があります。引き続き丁寧に対応していきたいと考えております。","voiceIndex":169,"id":"exchange-073"},{"speaker":"つる委員","kind":"質問・要望","question":"その脇に万年塀が非常に高い、２ｍぐらいでしょうか、あるところですので、しっかりとここは対策をお願いしたい、そういう思いであえてお伝えさせていただきました。では、次にいきます。駅周辺等ですが、駐輪対策という視点ですけれども、まずその前に、今、車道に自転車ナビマーク等が表示されているおりますが、これは法定外表示というものかと思うのですが、この認識を教えてください。","respondent":"川口交通安全担当課長","answer":"ただいまご質問の自転車ナビライン、自転車ナビマークのご質問です。こちらにつきましては、法定外表示ですので、法律上、規定されたものとは異なります。","voiceIndex":171,"id":"exchange-074"},{"speaker":"つる委員","kind":"提案","question":"いわゆるゾーン３０も含めて法定外表示は、結構いろいろあるのだなということを改めて思ったところでありますが、その中で駅周辺等の駐輪対策ということで、かつて私も２０１１年に初めて大阪市の取組を紹介して、何度か子どもたちが、「違法駐輪、駄目だよ」というようなことをかいた絵を歩道上に貼ったりとか、また敷地に貼って駐輪をやめさせていく、こういう取組をやったらどうだという。","respondent":"川口交通安全担当課長","answer":"したがいまして、以前の答弁等では交通管理者である警察等との協議を踏まえてというところなのですけれども、以前、警察のほうに質問した際には、なかなか設置は困難という回答であったと思います。","voiceIndex":173,"id":"exchange-075"},{"speaker":"つる委員","kind":"提案","question":"最後は要望になると思いますが、今申し上げた交通環境をしっかりと確保していただくというところでは、これも既に何度か提案も、２０１７年以降させていただいているＷｈｅｅＬｏｇ！国土交通省からも様々なログも提供されているわけでありますが、今後ぜひ、また改めて提案をさせていただきたいと思いますので、このＷｈｅｅＬｏｇ！の活用について、ぜひ積極的に様々な部署で検討いただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":175,"id":"exchange-076"},{"speaker":"おくの委員","kind":"質問","question":"３２０ページ、都市計画費、空港環境担当に関わって、羽田新飛行ルートについて質問いたします。国土交通省は、６月に羽田新経路の固定化回避に係る技術的方策検討会を設置しました。この検討会について、共産党の都議会議員が、先月、都議会で、「固定化回避は名ばかりで、実際は、都心上空の低空飛行が大前提とされています。お尋ねいたします。","respondent":"鈴木都市計画課長","answer":"その中では、今ご紹介いただいたように、「現在の滑走路の使い方を前提とし」と、こうした表現は、今、第１回目の議事録が国のホームページ上でもアップされておりますが、その中でも委員の発言として議事録の中でも紹介されているというところでは認識しているところですが。","voiceIndex":177,"id":"exchange-077"},{"speaker":"おくの委員","kind":"質問","question":"この検討会について、さらに念のためお伺いしておきます。そして、「新飛行ルートの滑走路運用及び発着便数そのものを再検討すべきではないか」との質問主意書を提出しました。そうしますと、品川区は、やはり検討会が新ルートを、ある意味、前提としているのだというふうにご認識しているということでよろしいのでしょうか。","respondent":"鈴木都市計画課長","answer":"羽田新ルートについて、昨年８月、国のほうで運用について本格決定を公表したわけですが、その過程の中で、これは国の事業、国策ということで、国の判断のもと、国の責任において進められていくべきものというところの認識ですが、ただ、これが決定したからといって。","voiceIndex":179,"id":"exchange-078"},{"speaker":"おくの委員","kind":"質問","question":"もう１点伺っておきます。そこで伺います。以上のこと、まず第１に、自衛隊機が新飛行ルートを飛ぶこと、それから第２に、１時間に合計４４便という着陸便数に自衛隊機が含まれていること、それから第３に、部品欠落の報告制度、それから羽田空港において実施している国による駐機中の機体チェックについて、自衛隊機は対象とされていないことを品川区は認識されていたでしょうか。お伺いいたします。","respondent":"鈴木都市計画課長","answer":"それは国の防衛あるいは様々な中で飛ぶこともあると、これは羽田新飛行ルートに限らず、従来から民間の航空機のルートを、当然ながら羽田に着陸するときは自衛隊機も飛ぶという考え方だと認識しています。","voiceIndex":181,"id":"exchange-079"},{"speaker":"おくの委員","kind":"質問・要望","question":"そう、飛ぶことがあるということなのです。そうしますと、自衛隊機までもが新ルート上を飛ぶという以上、区民の安全は、国土交通省が対策をやったというだけでは守り切れないということはいよいよ明らかであって、いよいよもって新ルートそのものをやめることを国に求めるべきではないかと私は思うのですが、その点、いかがでしょうか。お伺いいたします。","respondent":"鈴木都市計画課長","answer":"そうした中で、当然ながら自衛隊機は落下物の取組を何もしなくていいのかということは全くございませんで、それは国の責任において、それは自衛隊の中で当然ながら定期的なチェック、確認はされていると思いますが、羽田新ルートについて、これは定期ではなくて大分本数。","voiceIndex":183,"id":"exchange-080"},{"speaker":"横山委員","kind":"質問","question":"私からは、３１３ページ、都市計画道路整備事業について、３２０ページ、都市計画費について、３２１ページ、区民の自主的なまちづくりへの支援についてと、時間があれば、３０５ページ、道路・公園等監察費についてをお伺いいたします。１点目に、都市計画道路整備事業についてお伺いいたします。道路の便益計算について、例えば補助１６３号線では、どのような積み方をしていますでしょうか。","respondent":"溝口道路課長","answer":"この評価につきましては、基本的な考え方についてはあまり従前から変わっていないのですけれども、従前からの新規採択のとき、または事業が一定期間経過したとき、その後、事後という形で最終的にこの事業を行うことによってどういう成果があるのか。","voiceIndex":186,"id":"exchange-081"},{"speaker":"横山委員","kind":"質問・要望","question":"こちらの補助１６３号線につきましては、全体でやっていらっしゃるということでしたので、例えば今後ですけれども、区としてもアカウンタビリティの向上を図っていただくということを要望いたしますが、こちらはいかがでしょうか。２点目にまいります。都市計画費についてお伺いいたします。","respondent":"溝口道路課長、鈴木都市計画課長","answer":"当然、今後いろいろ様々な事業をやっていくときには、１つの指標として、また分かりやすい形、区民の方が数字でこれだけ道路を整備することによって効果がどのくらいありますという手法でありますので、また、先ほども話したように。大正初期では、全体的に田畑を計画的に作って生産性を上げていこうということで、耕地整理事業が行われましたが、耕地整理、非常に区画が大きいということで、周りの道路も４ｍない、俗に言う３.６ｍ道路が。","voiceIndex":188,"id":"exchange-082"},{"speaker":"横山委員","kind":"質問・要望","question":"歴史的な経緯についてご説明ありがとうございました。特に水害に対してなのですけれども、３０年から５０年後に起きたときにも、また１００年後もしのいでいけるように、人命を守るためのインフラの再配置の議論を始めていく必要があるというふうに私は考えておりますが、過去の災害の被害を今までどのようにまちづくりに活かされていますでしょうか。区のご見解をお聞かせください。","respondent":"鈴木都市計画課長","answer":"水害の話もございましたが、これも東日本大震災では、特に千葉県のほうで液状化が多かったというところで、東京都の液状化マップ等を来庁された方が閲覧できるような体制を関係部署がとってありますので、そうした中でこの液状化も周知させていただいて。","voiceIndex":191,"id":"exchange-083"},{"speaker":"横山委員","kind":"質問","question":"３点目にいきたいと思います。区民の自主的なまちづくりへの支援についてお伺いいたします。こちらは具体的にどのような内容なのでしょうか。","respondent":"鈴木都市計画課長","answer":"区民の自主的なまちづくりですが、地域の課題をまず居住者の方々、土地を所有されている方々が自主的に、例えば共同化を図っていきたい、あるいは防災性の向上を図っていきたいというところで、まだまだ何か市街地再開発事業とかそうしたところではなくて、地域が主体となって。","voiceIndex":193,"id":"exchange-084"},{"speaker":"横山委員","kind":"意見","question":"こういった支援があることを認知していただけるようにお願いしたいのですが、区のご見解を簡単にお聞かせください。","respondent":"鈴木都市計画課長","answer":"この制度をしっかり使っていただけるように、様々な機会を捉えて周知をしてまいりたいと思います。","voiceIndex":195,"id":"exchange-085"},{"speaker":"西村委員","kind":"質問","question":"３２３ページ、不燃化１０年プロジェクト、３４７ページ、防災行政無線設備更新費について伺ってまいります。区は、５か年計画の３年目に、２億７,６００万円近く費用をかけまして、防災行政無線の修繕を行いました。どのような工事を行ったのか、改めて詳しくお聞かせください。","respondent":"平原防災体制整備担当課長","answer":"防災行政無線の工事のお尋ねですけれども、こちらは国の法令改正に基づきまして、防災行政無線に活用しております発信電波をアナログ波からデジタル波に移行するために機器を交換するものを５か年で実施しているものです。現在はその４年目という状況です。","voiceIndex":198,"id":"exchange-086"},{"speaker":"西村委員","kind":"質問","question":"議事録を見ましても、こちらはずっと議論されていることと思いますが、工事をしていただいても、やはり聞こえない状況はあまり変わらないように思います。これをどのように解消していくのか。特段聞こえをよくする工事ではなかったと理解していますが、これまでの聞こえないという区民の方の声は承知されているでしょうか。お聞かせください。","respondent":"平原防災体制整備担当課長","answer":"私ども、そういう声をいただきましたら、直接現地に赴きまして、音量の調査など必要な調整を行っているところですけれども、現在の住宅の高層化、あるいは高気密化に伴いまして、全ての方にきちんとした形で防災行政無線が届くというのが難しい状況です。","voiceIndex":200,"id":"exchange-087"},{"speaker":"西村委員","kind":"質問","question":"私もそのように思うのですが、この防災行政無線というのは、もしかしたら、もうこれ以上、性能的には限界かもしれないというふうに思っています。区では、既に様々な方法を取り入れています。様々にＳＮＳも展開しておりますが、この中からテレビ・プッシュについて伺ってまいります。停電するとテレビは見られませんが、このテレビ・プッシュは自動表示されるのでしょうか。教えてください。","respondent":"平原防災体制整備担当課長","answer":"テレビ・プッシュのお尋ねですけれども、テレビ・プッシュはあくまでもテレビの電源を入れるというようなものですので、停電時には電源が入ることはございません。","voiceIndex":202,"id":"exchange-088"},{"speaker":"西村委員","kind":"質問・要望","question":"幾つかの自治体、都内ですと３１の自治体では、Ｊ：ＣＯＭの防災情報サービスを利用しておりました。初期費用以外に月３００円、未加入の方は月５００円がかかり、自治体と連携しているので、しながわテレビ・プッシュに近いサービスかというふうに思っています。このサービスでは、避難情報、気象情報など防災情報をテレビを自動起動して表示します。ご所見をお聞かせください。","respondent":"平原防災体制整備担当課長","answer":"品川区におきまして、既存の電波形態といいましょうか、そういうようなものをいかに活用して、どのような形でお届けできるかというのは、いろいろなパターンを、私ども、今、研究させていただいておりまして。","voiceIndex":204,"id":"exchange-089"},{"speaker":"西村委員","kind":"提案","question":"ぜひともお願いしたいと思います。例えば、どこに避難すればよいのか分かるチャットボットの活用を以前ご提案させていただきましたが、先ほど、松澤委員の答弁でもありました民間アプリを活用したコンテンツにも期待をしております。会派からも要望しておりますが、高齢者、障害をお持ちの方には、特に防災無線が自動的に入る方法、例えばラジオの一斉配布などをご検討いただきたいと思います。","respondent":"平原防災体制整備担当課長","answer":"ラジオについてですけれども、現在、私ども、平成２４年度に事業を実施いたしました防災ラジオ、こちらはアナログ波対応ということもございまして、先ほど来ご説明しています防災行政無線のデジタル波に対応して、どのような形で、今後、機器といいましょうか。","voiceIndex":206,"id":"exchange-090"},{"speaker":"西村委員","kind":"確認","question":"過渡期だと思いますが、どうぞよろしくお願いいたします。次の質問に移ります。災害時に安否確認のために玄関のドアノブにリボンをかけるという例年よりも小さな訓練ですが、防護服で救護に向かう訓練も行われました。結果的に町会の多くの方が参加する訓練になりました。コロナ禍における今年度の防災訓練に関して、区内の状況、区のお考えをお聞かせください。","respondent":"大森災害対策担当課長","answer":"現在までのところ、例年と同様の規模で実施することは困難と考えておりますが、メンバーを限定するなど、新型コロナウイルスの感染防止に工夫した形で実施したい、このように考えているところです。","voiceIndex":208,"id":"exchange-091"},{"speaker":"西村委員","kind":"意見","question":"発展的に考えてくださっておりまして、ありがとうあります。続けることが大事だというふうに思いますので、このような状況ではありますが、できる範囲で自助、公助、共助に、取り組んでいきたいというふうに思います。最後に、駆け足ですみません、不燃化１０年プロジェクトですが、現在の申請状況と、また来年３月以降の支援制度の延長について、どこまで検討されているのか、お聞かせください。","respondent":"佐藤木密整備推進課長","answer":"不燃化１０年プロジェクトにつきましては、当初、令和２年度までで終了の予定でしたけれども、東京都のほうでは助成事業につきまして、５年間の延長を決定しております。","voiceIndex":210,"id":"exchange-092"},{"speaker":"塚本委員","kind":"質問","question":"私からは、３１３ページ、補助１６３号線整備、東急大井町線交差部工事経費、３２９ページ、公園・児童遊園維持管理費の防犯カメラ設置費、３４５ページ、防災体制整備費の中からになるかと思うのですけれども、災害時の受援体制ということについてお伺いしたいと思います。初めに、３１３ページの補助第１６３号線整備の東急大井町線交差部工事経費についてですが、大体１８億円余という区の負担があります。","respondent":"溝口道路課長","answer":"補助第１６３号線の高架下の工事の件です。これにつきましては、基本は高架部分のほうを区が出すような形になっていますが、当然、東急の附帯する工事もありますので、そこについては東急と費用を按分いたしまして、それぞれの協定に基づいて支払っているものです。","voiceIndex":213,"id":"exchange-093"},{"speaker":"塚本委員","kind":"質問","question":"大井町線沿線の騒音に対する苦情について、区に対してはどのような声が届いていたりするのか、あるいは、騒音の状況についての認識をお伺いしたいと思います。例えば、最近になって、急行などが走ったりしていますので、騒音の状況が以前にも増して強くなっているとか、そのようなことがあるのかどうかも含めて区の認識をお伺いしたいと思います。","respondent":"鈴木都市計画課長","answer":"ただ、ご紹介いただいたように、各停から急行が通るということもあって、年に何件かになりますが、そうした声もいただいているところはあります。","voiceIndex":215,"id":"exchange-094"},{"speaker":"塚本委員","kind":"質問","question":"そういったこともあって、ここに来て、この騒音、何とかならないのですかみたいなお話が出ているのだと思います。そのような中で、こういったところの整備についての考え方というのは、区として整備していこうとしたときの考え方というか、どういったときに、例えば大井町線交差部みたいな道路拡幅とかというような話とは別に、あるのかどうかということをお伺いしたいと思います。","respondent":"鈴木都市計画課長","answer":"これは区として新たな課題と捉えて、東急に働きかけていく必要があるかどうかについては、いろいろ東急と様々な機会を捉えて意見交換する場等々がありますので、そうしたところをまずは技術的あるいは費用的なところも含めて。","voiceIndex":217,"id":"exchange-095","title":"町会・自治会支援"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。ぜひそういった住民の声を受け止めていただいて、東急との話し合いを進めていただければというふうに思います。続いて、公園・児童遊園維持管理費の防犯カメラ設置費についてですが、現状、品川区内の公園・児童遊園、また防災広場、水辺広場等、現在、区立公園といわれているものは２６９か所、そこら辺での今現在の防犯カメラの設置状況についてお伺いいたします。","respondent":"高梨公園課長","answer":"公園・児童遊園等における防犯カメラの設置状況ですが、昨年度、１４８公園２３５台の防犯カメラを設置いたしまして、累計で、令和元年度末時点におきまして、２４４公園で４０３台の防犯カメラを設置完了しております。","voiceIndex":219,"id":"exchange-096","title":"町会・自治会支援"},{"speaker":"塚本委員","kind":"意見","question":"そうすると、若干まだ未設置のところがあるということになるかと思います。この未設置のところについて、現在、設置に向けての考えとか、また、設置がまだされていない理由等が特にあればお聞かせください。","respondent":"高梨公園課長","answer":"防犯カメラ未設置の公園の状況ですが、まず、設置していない公園は２５公園ほどありますが、現在、工事中で設置自体ができない公園が数か所あります。これは区の工事が終われば、設置を考えていきたいと考えています。","voiceIndex":221,"id":"exchange-097"},{"speaker":"塚本委員","kind":"質問","question":"今ございました電源等がなくてというところについてですけれども、これは例えばソーラー式の防犯カメラが今出てきているかと思います。今、未設置の公園への設置について、防犯カメラの性能とか、コストパフォーマンスとか、そういったことを含めて、ソーラー式防犯カメラで対応していくということへのお考えについてお伺いしたいと思います。","respondent":"高梨公園課長","answer":"電源のない公園における防犯カメラの設置についてですが、ご提案のソーラー式の防犯カメラにつきましては、かつては大体１週間程度は連続した録画時間を確保したいといったようなこと、あと、ソーラー蓄電池の性能等から不安があったものですから。","voiceIndex":223,"id":"exchange-098"},{"speaker":"塚本委員","kind":"質問・要望","question":"ぜひ区内全ての公園になるべく早く防犯カメラが設置できるようにというふうに希望いたしますので、最新のソーラー式防犯カメラと新しい技術、積極的に検討していただいて、導入を進めていただきたいと、このような思いですので、よろしくお願いいたします。このボランティア受け入れの手順を示したマニュアルの概要について最初に教えてください。","respondent":"中島防災課長","answer":"災害時の受援についてのお尋ねですが、災害時、業務全般につきまして、災害時対応マニュアルを作っており、その中でボランティアあるいはほかの自治体からの受入れについてマニュアル化をしています。","voiceIndex":225,"id":"exchange-099"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。それで、１つお伺いしたいのは、今年７月、豪雨で熊本などで災害が出て、復旧作業でボランティアの活動があったわけですけれども、やっぱり新型コロナウイルス感染症の関係で、県外から受け入れるということに対しては、熊本県としては若干お控えくださいというような動きがあったかと思います。今、区としてこの辺の感染症とボランティアの受け入れについての考え方をお伺いしたいと思います。","respondent":"中島防災課長","answer":"いずれにしましても、今回の計画にどこまで入れられるかは今後検討ですが、そういうしっかりとした感染対策等についても配慮してまいりたいと思います。","voiceIndex":227,"id":"exchange-100","title":"町会・自治会支援"},{"speaker":"塚本委員","kind":"意見","question":"ぜひしっかり前もって考えておくというか、決めておくべきことは決めておく必要があるかと思います。いざというときに混乱を来さないように、この点についてもしっかりとご検討をよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":229,"id":"exchange-101"},{"speaker":"木村委員","kind":"質問","question":"土木費の街路灯管理費の中の３１１ページの一番上にあります街路灯建替事業、ＬＥＤ型から質問をいたします。従来の街路灯からＬＥＤ型へ建替えた事業です。これで計画していた事業は終了したと考えていいのかどうかお答えください。そして、区内には何基の街路灯があり、全てを建て替えるにはどれほどの時間が必要だったのかもお聞かせください。","respondent":"溝口道路課長","answer":"今回予算に計上しておりますＬＥＤ街路灯への建替事業です。これにつきましては、もともと水銀条約、水銀灯を使ったランプが使えなくなるということで、５年間をかけて直してきたところです。平成元年度〔同日後刻に「平成２７年度」と答弁訂正あり〕から工事を進めてきています。","voiceIndex":231,"id":"exchange-102"},{"speaker":"木村委員","kind":"質問","question":"従来の街路灯と比べますと、電力は約７５％削減、そして明るさもアップと紹介されていますけれども、そうなると、この明るさ、住宅街などではあまり使えないということになるのでしょうか。","respondent":"溝口道路課長","answer":"そういったものも見極めながら、令和元年度からのＬＥＤ化に向けて事業に計画的に着手してきたという経緯があるものです。","voiceIndex":233,"id":"exchange-103"},{"speaker":"木村委員","kind":"質問","question":"その下にあります災害時消えない街路灯設置、３基、１４９万円余からの質問ですけれども、３基で１４９万４,９００円、１基当たり５０万円弱の計算になる街路灯ですけれども、高いのか安いのかは分かりませんが、こちらも計画した事業は全て終わったと考えてよろしいのか。","respondent":"溝口道路課長","answer":"これにつきましては、やはり災害時、停電が起きたときに、区民の方々が安全に避難所なり広域避難場所に逃げ込める、そういったところを目的に、停電地点でも３日間程度は夜間明かりが点いているような街路灯を整備していくという形で整備を進めておりまして。","voiceIndex":235,"id":"exchange-104"},{"speaker":"木村委員","kind":"質問","question":"大きな災害時には、街路灯が消えてしまうわけですけれども、大変心強い街路灯であります。しかし、消えないと言っても、今、お答えがありましたけれども、点灯時間的には大体どれぐらい点灯しているものなのか。そして、もちろん昼間、日が照っているときなどは、もちろんそれは消えているわけであると思いますけれども、その点灯時間、大体どれぐらいもつものか教えてください。","respondent":"溝口道路課長","answer":"すみません、説明が足りず申し訳ありませんでした。今回設置したバッテリー内蔵の消えない街路灯につきましては、夜間のみ３日間程度。","voiceIndex":237,"id":"exchange-105"},{"speaker":"木村委員","kind":"質問","question":"２０１１年３月１１日に発生した東日本大震災のとき、東京都町田市内の広い地域で電力供給が断たれ、夜になると道路には帰宅困難者があふれたそうであります。しかし、道路照明がつかなかったため、一時停滞施設等への誘導に支障が生じたそうであります。このたびの災害時消えない街路灯とは、この「消えないまちだ君」でしょうか。それともまた本区独自で作り上げたものなのかどうか、お聞かせください。","respondent":"溝口道路課長","answer":"ただ、全部が全部これが入らないところもありましたので、そういったところはこれと類似のものをつけておりますが、こういったものも１つのいい製品だという形でご紹介をされていたものですから、そういったものも使いながら、また同等な機能のものもありますので。","voiceIndex":239,"id":"exchange-106"},{"speaker":"木村委員","kind":"質問","question":"準備は必要であります。区民の命や区の財産を守るためにも、一刻も早い準備をまたお願いしたいと思います。次に、３３９ページの中ほどにあります住環境改善促進事業の中の親元近居支援事業から質問をいたします。この三世代すまいるポイントとは、品川区に引越しをすることでポイントがいただける、そのポイントを生活の一部に活用することができるということですけれども、ご説明を願いたいと思います。","respondent":"森住宅課長","answer":"親元近居支援事業についてのお尋ねです。","voiceIndex":241,"id":"exchange-107"},{"speaker":"木村委員","kind":"意見","question":"三世代すまいるポイントというのは、親世帯、子ども世帯が、どちらかが品川区内に１年以上住まいをしていることが条件とありました。同居にしても、近居するための転居件数は増えているのかどうか。この事業、本区では、平成２３年から行っているとのことでありますけれども、他の区も行っている事業なのか、それとも区独自の事業なのか、お聞かせください。","respondent":"森住宅課長","answer":"実績につきましては、最近少し減少気味です。ＰＲに力を入れていきたいと思います。２３区では、三世代すまいるポイントとして出しているところはないですが、近居の助成をしている区は幾つかあるというふうに聞いてあります。","voiceIndex":243,"id":"exchange-108"},{"speaker":"あべ委員","kind":"質問","question":"私からは、３２５ページの市街地再開発事業、大井町駅周辺地区再開発事業と、それから、いわゆるＣ地区と呼ばれる地域などについても伺いたいと思います。それから、３４３ページ、防災対策全般と防災会議等について、そして３４７ページの備蓄物資についてもお伺いしたいと思います。","respondent":"多並都市開発課長","answer":"全体的なまちづくりマスタープランの中で、定住性であったり、人口であったり、クレーム等のいろいろな説明をその中で検証しているところでありまして、区としましては、そこの各単位の中での人口フレームは想定しないで進んでいる、その大きな中の進め方ということで。","voiceIndex":246,"id":"exchange-109"},{"speaker":"あべ委員","kind":"質問","question":"今のところ想定がないというふうなご答弁に聞こえたのですけれども、大井町は地形的にも歴史的にも道路の構造があまりよくない、鉄道を中心に発達してきたまちだと思います。開発で道路は少し拡幅したり、増やしたぐらいでは、なかなか地域としての交通キャパシティは大きく増えていかないのではないかと。この人口規模の視点がぜひ計画には必要ではないかと思いますが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"その事業を進めている中で、やはり例えばＣ地区だけではなくて、今回の広町地区、Ｃ地区、Ｅ地区等の今地域の方にまちづくりの検討をしていただいている地区がありますけれども、そのような機会を捉えながら、区としましては。","voiceIndex":248,"id":"exchange-110"},{"speaker":"あべ委員","kind":"質問・要望","question":"Ｃ地区の話はこれからです。今、地域内では、例えば開発に早く同意すると、買取価格が上がるとか、有利になるとか、あるいは区が決定したことだから、もう反対しても無駄だというような話も出回っているようですが、こういったことはあるのでしょうか。人によって権利率が変わったりとか、区が既に何かを決定しているということはあるのか、そこをまず確認させてください。","respondent":"多並都市開発課長","answer":"Ｃ地区についてのところですけれども、現在は、地域の有志の方が勉強会という形で開いて、今後のいろいろな手法について検討している段階と認識しています。","voiceIndex":250,"id":"exchange-111"},{"speaker":"あべ委員","kind":"質問","question":"質問したことに答えてください。私が質問をしたのは、同意する時期によって交換率が変わることがあるかということと、それから、区が既に何かを決定しているのかという２点だけです。それ以外のことで時間を使わないでください。答弁をお願いします。","respondent":"多並都市開発課長","answer":"同意することで変わることはありません。もう１つが、区が早く決めたからといって変わることももちろんありません。要するに、今進めている事業の中で公平に進めていただくものです。","voiceIndex":252,"id":"exchange-112"},{"speaker":"あべ委員","kind":"確認","question":"確認したいことができました。ですので、区としては、この情報デバイトを埋めていくのが行政としての責任ではないか、特に再開発事業の収益構造ですとか、権利変換状況、他地域での地権者の方々がどのような提示がされて、結果的にどのようであったのかといったようなことを積極的に提示していくことが区の役割ではないかと思いますが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"やはり地域の方のお話をよくお聞きさせていただいて、今後のどういうまちにしていくかというのは、地域の方が主体で考えていくべきでもありますので、そこについてご不安がある方がいらっしゃれば、区としてやはりそこはしっかりお支えさせていただいて。","voiceIndex":254,"id":"exchange-113"},{"speaker":"あべ委員","kind":"質問・要望","question":"かなり聞いていないことで時間が経ってしまいました。防災会議については、先日の本会議の中で女性の人数がまだ３人ということで、１０年近く求めてきたことがまだ実現していなかったということは非常に衝撃でありました。これからは太陽光発電機をマンション等にも配備できるよう助成していくような考え方をぜひお願いしたいのですけれども、いかがでしょうか。","respondent":"中島防災課長、平原防災体制整備担当課長","answer":"防災会議につきましては、女性の委員の割合を国の目標値である３０％に至る方策の中で、委員の任命については様々考えていきたいと思います。停電時に太陽光発電について助成するですが、そこは検討させていただきたいと思います。","voiceIndex":256,"id":"exchange-114"},{"speaker":"のだて委員","kind":"質問","question":"私からは、３２４ページの都市開発費に関連して、超高層ビルは防災対策にならないということについて質問をいたします。トイレも使えず、住民の大半が１週間以上、生活できなくなりました。目黒川沿いに超高層マンションが多数あります。この住宅棟の電気室は何階にあるのか伺います。超高層マンションが浸水で停電したら、生活できなくなるという新たな問題が起こると思いますが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"これ以外の箇所についても同様なところが多いところですけれども、各地区とも、目黒川沿いに再開発事業、また事業を進めるということで、電気室に水が入らないように、防水板をハザードマップの浸水の深さに合わせながら設置するということで。","voiceIndex":260,"id":"exchange-115"},{"speaker":"のだて委員","kind":"質問・要望","question":"早急な対策が必要だと思いますが、先ほど、防水板を電気室に設置しているということなのか、これからしていくということなのか、そこの確認もさせていただきたいと思います。やはりこれ以上の新築はやめて、既存建物への対策を抜本的に強めていくことが必要なのではないかと思いますが、それぞれ伺います。","respondent":"多並都市開発課長","answer":"いずれにいたしましても、その現場の状況に合わせながら、今あるマンション等のビルについても、そういう内容で、より安全・安心できるような形で整備していかなければいけないというところで。","voiceIndex":262,"id":"exchange-116"},{"speaker":"のだて委員","kind":"質問・要望","question":"今の答弁ですけれども、防水板は既に設置されているということで、浸水深に合わせてという話でしたが、先ほど紹介した２棟は３.０ｍから５.０ｍの浸水深になるということですけれども、電気室が地下にあって、防水板を設置したというのは、天井いっぱいまでの防水板ということになるのか、そこのところを確認させていただきたいと思います。","respondent":"多並都市開発課長","answer":"もう１つは、防災課とよく連携しながら、避難体制等はどのような形ですればいいか、その現象に合わせながら、その地域の住民の方が安心・安全にできるように進めていくべきというところで考えているところです。","voiceIndex":264,"id":"exchange-117"},{"speaker":"のだて委員","kind":"質問","question":"特に耐火性や耐震性などがありますけれども、以前の予算特別委員会でも耐震性について、超高層とそれ意外とでは違いがあるのかと質問したところ、区は「何ら変わりはない」と答弁しました。超高層再開発は防災対策にならないと思いますが、いかがでしょうか。そうした取組を区が支援していくことが、地権者だけでなく、地域住民との関係でも重要だと思いますが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"そもそも今あるまちの中で老朽化建物であったり、耐震性のないマンションがあったり、そのまちの課題、または細い道路があって避難に困難だとか、そのような様々な課題を抱える中で、市街地再開発事業、まちづくりの中で改善していくということで。","voiceIndex":266,"id":"exchange-118"},{"speaker":"のだて委員","kind":"意見","question":"再開発を進めていると言いますけれども、それ以外の方法もあるということで、やはり地域の住民が立ち退きを迫られたり、周辺の住民に大きな影響を及ぼすということがありますので、そういった面でも低層での共同化を進めていくということが、やはり住民に理解されるまちづくりだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":268,"id":"exchange-119"},{"speaker":"こんの委員","kind":"質問","question":"私からは、３０５ページ、交通安全啓発費、３４７ページ、防災行政無線管理費、同じく避難所管理費からお伺いしたいと思います。そこで、新型コロナウイルス感染症の影響で自転車が生活の移動手段となってきている現状を区はどのように捉えていますでしょうか。こうした現状を捉えて、今後の自転車利用について、区のご見解をお聞かせください。","respondent":"川口交通安全担当課長","answer":"東京都におきましても、自転車活用推進計画の見直しが図られているところでございまして、その内容を踏まえ、区としても対策について検討をしてまいりたいというふうに考えております。","voiceIndex":270,"id":"exchange-120"},{"speaker":"こんの委員","kind":"確認","question":"こうした新型コロナウイルス感染症も影響してということで、自転車の利用というところは、放置自転車の関係で徒歩というところだったけれども、これからは自転車を利用するという考え方で進んでいくということが確認されました。しかし、便利な移動手段ではありますが、自転車は車両の一部という扱いですから、きちんと運転マナーが守られないと大変に危険な車両とも理解をしております。","respondent":"川口交通安全担当課長","answer":"したがいまして、今度、第１０次品川区交通安全計画につきましても、今年度末で終了いたしまして、次年度からは第１１次計画ですので、引き続き自転車の事故防止対策については強化をする上での計画等の策定を検討していきたいというふうに考えております。","voiceIndex":272,"id":"exchange-121"},{"speaker":"こんの委員","kind":"提案","question":"次の質問にまいります。このデジタル化へ移行後、令和３年度中に今後の対策を決めていくという、現在検討されていることを承知しておりますが、この検討内容は、例えばＦＭ波を受信して自動的にスイッチが入るものについて、コミュニティＦＭでは、そういった機能を持たせることも可能だとするなど、区の見解は議事録でも確認をしております。","respondent":"平原防災体制整備担当課長","answer":"防災行政無線の放送をいかにしてお届けするかということについてですけれども、現在、防災行政無線のデジタル化に移行する工事に伴いまして、現行の防災ラジオについてはご指摘のとおりデジタル波を受信することはできないのですが。","voiceIndex":274,"id":"exchange-122"},{"speaker":"こんの委員","kind":"質問・要望","question":"ですので、現在の防災ラジオをお持ちの方が、このデジタル化に移行後も、同じ仕組みでラジオを持てるような形で進めていただきたいと思いますが、もう一言、ご答弁をお願いできますでしょうか。","respondent":"平原防災体制整備担当課長","answer":"新たな防災ラジオですが、あくまでまだ検討中のものですので、これといったはっきりした形ではございませんけれども、平成２４年から大分年数が経ちまして、インターネット環境などの拡大もありますので、そういったところも踏まえながら。","voiceIndex":276,"id":"exchange-123"},{"speaker":"こんの委員","kind":"確認","question":"避難所管理費に関連して、総務費でも少しお聞きいたしました災害対策職員待機寮の職員の方の動きについて確認をしたいと思います。そこで、総務費の中でもお聞きいたしました災害対策職員待機寮の職員の方が、現在、１１９人いらっしゃるとお聞きしておりますけれども、その待機寮の職員の方の初動について、昨年の台風第１５号、第１９号の際には、どのような対応、どのような初動をとられたのでしょうか。","respondent":"中島防災課長","answer":"災害対策職員待機寮の職員につきまして、基本的には災害、風水害のときにも動員をしているところで、昨年の台風の際は、本部において情報収集、電話対応等も含めまして、本部のほうで従事しています。","voiceIndex":278,"id":"exchange-124"},{"speaker":"こんの委員","kind":"質問","question":"今のご答弁からいくと、本部でこの待機寮の職員の方の動きを、いわゆる指揮命令して動いていただくという理解でいいでしょうか。その動き方、どのような対応、行動をされたのかお聞きしたいと思います。","respondent":"中島防災課長","answer":"本部の中では、指令情報部というか、実際に防災課を中心とした指揮の中に、待機寮は動員しておりまして、本部の中で台風の対応のときは電話対応を行ったところです。","voiceIndex":280,"id":"exchange-125"},{"speaker":"こんの委員","kind":"確認","question":"１１９人余りの方々が全部そういう対応だったのかというところをお聞きしたいわけですが、要は、この待機寮の職員の方々は、この名目のとおり、災害対策に待機をしてくださっている職員の方ですので、災害時にどのような動きをしているのか、またどのような動きをすることになっているのか、そこら辺を確認したいと思います。","respondent":"中島防災課長","answer":"説明が不足して申し訳ございませんでした。１１９人、災害対策職員待機寮に職員がおりますが、基本的に風水害のときは、輪番制で大体１０名程度の職員が従事しています。ですので、昨年の台風のときは、その１０名の職員を中心に動員をかけたところです。","voiceIndex":282,"id":"exchange-126"},{"speaker":"こんの委員","kind":"質問","question":"風水害の場合、いわゆる台風や集中豪雨のときは、事前に災害が大体予測ができるので、対応もこれぐらいでというような形で、昨年の１０名程度の対応をとられたということですけれども、確かに震災のときには、どういう災害が起きるかというのが分かりませんので、どの程度の職員の方に動いていただくかということもあると思いますが、そうしたことがきちんと決められているのか。","respondent":"中島防災課長","answer":"実際、避難所連絡会議の方々と、主に係長級の職員を中心といたしまして、毎年、避難所連絡会議などでお会いする機会などを設けてあります。実際に避難所訓練、特に区内一斉防災訓練、そういう中で実際に顔を合わせてしっかりお互いを知る関係で訓練に取り組んでいるところです。","voiceIndex":284,"id":"exchange-127"},{"speaker":"西本委員","kind":"質問・要望","question":"３２３ページの密集住宅市街地整備促進事業、この中では大井五丁目・七丁目、西大井三丁目の道路の測量をするという話があったと思うのですけれども、それがどういう状況になっているのでしょうか。その考え方、どういう進め方を今後しようとしているのか、お考えをお聞きします。３つ目は、３２１ページのコミュニティバス導入です。なぜコミュニティバスというものが入ってくるのだろうか。","respondent":"佐藤木密整備推進課長、多並都市開発課長、鈴木都市計画課長","answer":"令和元年度におきましては、決算書の中の事業推進業務等委託という中に入っておりますけれども、こちらで大井。委員からお話がございましたが、今現在、地域の有志の方がまちづくりの勉強会という形で将来の方向性について検討されている段階です。コミュニティバスの導入目的についてですが、ご紹介いただきましたように、世論調査でも非常に住み続けたいという回答をいただく方が高い割合であった。","voiceIndex":288,"id":"exchange-128"},{"speaker":"西本委員","kind":"質問・要望","question":"密集住宅市街地整備促進事業ですが、測量は終わったのですか。それがご答弁になかったのですが、それを基にしてどういう動きをしようとしているのか。なので、そういう手法も今後考えていくべきではないかと思います。私たちの思うものと、住民たちが必要だと思うニーズが本当に合っているのかというのは、やはり検証していきながら進めていただきたいと思いますが、いかがでしょうか。","respondent":"佐藤木密整備推進課長、多並都市開発課長、鈴木都市計画課長","answer":"今回、実施いたしました測量につきましては、いわゆる工事の前の測量というよりは、今現在、地域で５町会の皆様方と。大井町周辺のまちづくりにつきましては、やはりまちの課題や、まちの活性化等をよく見ながら、また地域の方のご意見をお伺いしながら。いろいろ声も寄せられている中で、やはり高齢化ですとか、子育て世代の多い地域、１１の指標を先ほどご紹介しましたが、そうした分析をしっかり行って。","voiceIndex":292,"id":"exchange-129"},{"speaker":"鈴木（真）委員","kind":"確認","question":"災害ごみ関係です。衛生費でもごみの問題を確認させていただきましたが、区のがれき処理について、地域防災計画を見ていきますと、その仮置場として、しながわ区民公園、鮫洲運動公園、あとは都の施設が幾つか出ていましたが、そういうところでは想定訓練的なものをやっているのかどうかということがまず１点です。それから、都の施設との間で何か協定でも結んでいるのかどうか、その辺を教えてください。","respondent":"中島防災課長、高梨公園課長、稲田土木管理課長","answer":"災害廃棄物に関する訓練については、具体的な場所等も含めまして、特に実施はしていないところです。この対応といたしまして、特に平日の昼間であったりとか、保育園のお散歩等で訪れる方が多いという状況を鑑みまして。今後におきましては、今、公園課長も申しましたとおり、公園の配置とか、いろいろと周辺のまちづくりの状況等も考えながら。","voiceIndex":300,"id":"exchange-130"},{"speaker":"鈴木（真）委員","kind":"意見","question":"災害ごみの関係ですけれども、やはり衛生費のときも言いましたが、世田谷区、大田区での被害もあります。さっきもちょっと言ったのですけれども、鮫洲運動公園のところは、フェンスを張ってしまっていて、車が入れるところは、１か所ぐらい、ちょっと狭いところしかないので、いざというときに入れない。あれを見ていてもすごくいいと思ったので、ぜひそれはお願いしたいと思います。","respondent":"中島防災課長","answer":"災害廃棄物に関しましては、これまでは災害対応マニュアルを区のほうで作っておりまして、その中で関係部署と連携して運営に努めているところですが、具体的な内容の反映、あるいは災害廃棄物は災害の規模によりまして、総合的かつ計画的に対処すべきものですので。","voiceIndex":304,"id":"exchange-131"},{"speaker":"鈴木（真）委員","kind":"確認","question":"具体的にもう１か所、同じ鮫洲運動公園ですけれども、実は今朝も確認をしてきたのですけれども、あそこは通路の間に大型のオートバイが結構止まっているのです。今朝も１０台ぐらい止まっていました。万が一事故でも起きたときも心配もあるので、その辺、区も承知して整備をやっていると思うのですけれども、その辺のお考えをお聞きしたいと。それから、旧東海道の道路の問題で確認させてください。","respondent":"高梨公園課長、溝口道路課長","answer":"今、委員のご提案のありました方法等も含めて、解消に向けて前向きに検討していきたいと考えております。悪ければ直していく、そういったことを引き続きやっていくというのは大切だと思っていますし、今後どういう形で解消できるのか、それについては、また来年度を含めてしっかり検討していきたいと考えているところです。","voiceIndex":306,"id":"exchange-132"},{"speaker":"鈴木（真）委員","kind":"意見","question":"鮫洲運動公園のほうはよろしくお願いします。鮫洲運動公園に限らず、そういう公園があれば、全てのところで同じように考えていってもらいたいと思います。それから、旧東海道のところは、殊に駐車場が最近できているところなどは、その出入口がかなり凸凹になっているところもあるので、その辺、またご苦労ですがよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":309,"id":"exchange-133"},{"speaker":"石田（ち）委員","kind":"確認","question":"私からは、３２５ページの大井町駅周辺地区再開発事業から広町地区のまちづくりとＣ地区について伺いたいと思います。その協定に基づき検討される中に、現庁舎跡地の活用も入っているのかというふうに伺ったのですけれども、私は資料で見たら、入っているということだったのですけれども、そういうことでいいのかということをまず確認したいと思います。","respondent":"多並都市開発課長","answer":"広町地区のまちづくりにつきましては、ＪＲ東日本と平成３０年に協定を締結して、共同で検討を進めているところです。このまちづくりの手法について、今、検討していますけれども、土地の再編という形で土地区画整理事業という形で再編をしていくということになります。","voiceIndex":311,"id":"exchange-134"},{"speaker":"石田（ち）委員","kind":"質問","question":"とても丁寧に説明されたのですけれども、では、新庁舎ができた後、現庁舎は跡地という形になってくるのですけれども、そこは共同ではなく、区として検討していくということでいいのですか。","respondent":"多並都市開発課長","answer":"単独検討というのは、今度は区が再編した土地について、どのようなものを建てたり、どう利用していくか、土地利用をどうしていくかということを検討するものでありますので、単独検討というのは区が単独で行うものとご理解いただければと思います。","voiceIndex":313,"id":"exchange-135"},{"speaker":"石田（ち）委員","kind":"質問","question":"現庁舎跡地は単独検討になるということですね。やっぱりそうした十分な収益、もうけが見込めると判断したＪＲ東日本と検討するというところでは、開発なわけですから、ＪＲ東日本のもうけのために現庁舎まで一緒に使われてしまうのかというところで、私はすごく心配したのですけれども、そうすると、開発と切り離して単独で考えていくということをもう１回伺いたいと思います。","respondent":"多並都市開発課長","answer":"土地の再編についてのことは先ほど説明しましたけれども、あともう１つは、まちづくりという観点で、大井町駅周辺がどういう形で進めていくべきかということで、その方針に従って、区ももちろん検討しますけれども、ＪＲ東日本がこれから施設検討をする際には。","voiceIndex":315,"id":"exchange-136"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ちょっと話を聞いていると、やっぱり開発と一体に進められるのかという。私としては、切り離して考えていただきたいとずっと求めてきているとおりなのですけれども。区民の土地を何に使う、交換してまで何に使うのかということが明かせないというのはなぜなのか、そしてそれをなぜ区民に問わないのか、示さないのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"今後、まちづくり方針に従いながら、都市計画の様々な手法について検討しながら進めていくということで、１つの手法として、土地区画整理事業、また、具体的な建築物の施設計画を立てる際には、都市計画手法も考えながらやっていくことになりますので。","voiceIndex":317,"id":"exchange-137"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区有地は区民の土地なわけです。先ほどもおっしゃっていましたけれども、それがどう公平に交換されたのか、されるのか、そういうことを公表していただくと、ああ、なるほどというふうになるので、そういうものを公表すべきだと思いますし、また、土地を交換する駅前一等地は何に使われるのか、そして、現庁舎跡地の活用の検討内容なども公表していただきたいと思いますけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"今後の進め方をもう少し詳しくご説明しますと、先ほどの土地区画整理事業、ずっとお話ししていますけれども、これはその手法の説明をしているものでありまして、その内容をどうするかというのは、まだお示しできる状況ではないということで。","voiceIndex":319,"id":"exchange-138"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やっぱり新型コロナウイルス感染症のこういう最中で、検討とはいえどもすごく、１億円、２億円とかかってくるのがまちづくりの検討ですので、一旦ここは立ち止まって、コロナ対策に十分使うことを求めたいと思います。そして、Ｃ地区について伺います。まちづくり勉強会が行われているということですけれども、区としては、Ｃ地区は再開発として進めたいと考えているということでいいでしょうか。","respondent":"多並都市開発課長","answer":"その内容を共有した段階で、次にどういう事業手法になるかという進め方の順番ではないかということで、現時点ではまだ再開発事業等を区としてそのように進めるということで考えているものではありません。","voiceIndex":321,"id":"exchange-139"},{"speaker":"石田（ち）委員","kind":"質問","question":"お話を聞きながらとか、今も共有しながらという段階ですと言うのですけれども、今、課長がお答えいただいているということは、都市開発課長ですので、都市開発なのですね。都市開発課は開発以外に何かほかに事業をされる所管なのでしょうか。そこを伺いたいと思います。","respondent":"多並都市開発課長","answer":"市街地再開発事業だけではなくて、いろいろ地区計画の中であったり、総合設計だったり、その土地の特性に応じて様々な手法が違いますので、区画整理もその中の１つですけれども。","voiceIndex":323,"id":"exchange-140"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"地域の課題を解決するというところで、東小路などの防災性に課題があるところなどは、木密整備推進事業とか、そういうところでできるところだと思うのです。望んでいないのに自分の、そして家族の土地を奪われる。ぜひ住民の声を聞くというのであれば、デベロッパーを除いて、抜きにして住民の方とじっくり話して協力していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":325,"id":"exchange-141"},{"speaker":"高橋（し）委員","kind":"質問","question":"届いているとしたら、どういうようなお声があったでしょうか。３２３ページ、平成３１年にまちづくりビジョンが作成されて、令和元年度には、今、都市再生整備計画を作成していると伺っています。大きな枠組みの考え方の中で、庁舎機能も検討されていますけれども、第二庁舎について、工事は約３０年前、平成３年から平成６年、平成６年８月に竣工と伺っています。内訳等が分かればお尋ねします。","respondent":"松本河川下水道課長、品川財政課長、鈴木都市計画課長","answer":"区民の声ですが、直接私たちのところに現在のところはありませんが、設置にあたって、周辺の住民の方にこの工事を。第二庁舎の建設費ですが、おおむね７０億円となっております。それから、建設期間は、平成３年から平成６年までの３年間となっています。今後の予定ですが、この検討を進めまして、令和４年度には、いろいろハードルがありますので予定ではありますが、令和４年度末には事業認定を受けて。すみません、答弁を追加します。財源としましては、基金、それから一般財源、あと特別区債を発行しています。","voiceIndex":327,"id":"exchange-142"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"台風に間に合ったのでよろしいかと思います。立会川・勝島のまちづくりについては、勝島地区は人口が急増していて、高齢化率も区全体は２１％なのに、勝島地区は４.４％という大変若いファミリー層が多いところです。そして、それは当時の東京都の財調の算定に入っていたのでしょうか。入っていたとすれば、どれぐらいの割合が算定されたのでしょうか。お願いします。","respondent":"品川財政課長","answer":"これは防災センター等が入っておりますので、この防災の部分ということで起債が発行できるということで上げてあります。それから、財調の部分ですけれども、当時はこの起債部分の２５％分が財調でまかなわれておりました。","voiceIndex":332,"id":"exchange-143"},{"speaker":"高橋（し）委員","kind":"質問","question":"７０億円のうち１４億円は起債して、そのうちの２５％、約３.５億円は算定されたということです。財源確保が重要だと考えていますが、どのように調達するのか、現時点でのお考えがあればお願いします。もし仮に起債した場合、先ほどは２５％が東京都の財調の算定でしたが、現在もし同じように起債したとすれば、金額は置いておいて、どれぐらいの割合で算定されるのでしょうか。","respondent":"品川財政課長","answer":"ここの部分は毎年財調交渉の内容には入っていないのですけれども、財調の部分で結構これは変更になる部分になっているですので、今は５０分の１となっておりますが、今後、続くかどうかは、ちょっと見通しとしては難しいかと考えています。","voiceIndex":334,"id":"exchange-144"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"不確定な要素が多い中、ご答弁ありがとうございました。ところで、今、起債の話が出ましたが、なかなかこの辺の起債のことは難しいので、ちょっと教えていただきたいのですが、庁舎建設などにおける国や都の補助金、あるいは国や都の手当てのある、さっきの起債です、先ほど、東京都で５０分の１と言われましたが、特別区には、市町村とは異なり、なかなか難しい事情があるのかと思います。","respondent":"品川財政課長","answer":"財調のほうの特別交付金の中で、一部使える部分もあるのではないかということですが、これもはっきりと条件等が確定しているわけではないので、そういった部分もいろいろ活用できるところは十分活用しながら、庁舎建設の財源を獲得していきたいと、このように思っております。","voiceIndex":336,"id":"exchange-145"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"活用できるものは活用して探していかれるということですので、ぜひ研究、検討をして、財源を確保していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":338,"id":"exchange-146"},{"speaker":"藤原委員","kind":"質問・要望","question":"３４１ページ、借上型区民住宅、これは、決算書に１団地出ていますが、特優賃、これがこういう形で出てくるのは最後の最後ということで確認させていただきたいと思います。課長は東京都に品川区の代表として協議に行っていただいていると思うのですけれども、そういう意味において、どういう思いで、またどういう決意で行かれているか、改めてお伺いします。どういう進捗状況か、教えてください。","respondent":"森住宅課長、長尾建築課長、佐藤木密整備推進課長、川口交通安全担当課長、松本河川下水道課長、中島防災課長","answer":"借上型区民住宅につきましては、今年の２月末をもちまして、区内の借上型住宅全てを終了いたしましたので。今後についてもこの品川シェルターについては、引き続き周知等をしながら活用を図っていきたいと考えております。区としましても、この取組については引き続き取り組む必要があると考えています。こちらにつきましては、道路交通法の第３８条におきまして、車両等が横断歩道のところで横断しようとする歩行者があるとき。","voiceIndex":340,"id":"exchange-147"},{"speaker":"藤原委員","kind":"質問・要望","question":"もう１回ぐらいやって終わりましたということを伺って、だって、私、１０年ぐらい伺っているのです。もう１回言います、看板とかを立てても止まらないですから、行ってしまいますから、今までやっているわけですから、ぜひそこをやっていただきたいと考えていますので、よろしくお願いします。ですから、上の収入、上限を、私はもう変えてもいいのだと思うのですけれども、その辺はいかがでしょうか。","respondent":"森住宅課長、川口交通安全担当課長","answer":"区民住宅の使用料につきましては、上限として、２人、３人、４人という家族の中で決めさせていただいているところでございまして、今後、区民住宅の中で使用料について議論があるときには。区といたしましては、今は区の公式のＬＩＮＥアカウントですとか、いわゆる情報発信ツールが非常に充実しておりますので、警察以上の情報発信能力を持っているというふうにも認識しております。","voiceIndex":347,"id":"exchange-148"},{"speaker":"藤原委員","kind":"質問・要望","question":"本当に。ルールを守って横断歩道を渡っているだけではないですか。ここだけは知恵を出していただいて、もう課長が担当しているか、品川区でいう湾岸警察も入れて、交通課長等と話していただいて、もう横断歩道は止まるという形にしていっていただきたいと思いますが、改めて、あと１年半の間に、どういう形でやっていっていただけるかという思いは、これはお伺いしたいので、よろしくお願いいたします。","respondent":"川口交通安全担当課長","answer":"今年度、第１０次品川区交通安全計画が終わります。第１１次でありますけれども、そこの中の具体的な講じようとする施策の中にも、この部分については入れ込めないのかということで検討していきたいというふうに考えております。","voiceIndex":350,"id":"exchange-149"},{"speaker":"安藤委員","kind":"質問","question":"３２１ページ、特定整備路線、コミュニティバス、時間があれば、３２５ページ、大崎駅周辺地区再開発事業について伺います。特定整備路線です。この特定整備路線は、区長が手を挙げ、３路線が特定整備路線に選定され、事業化されました。補助第２９号線と放射第２号線について、見込まれる総事業費、またこれまで取得した道路用地の取得率と総面積をそれぞれ教えてください。","respondent":"鈴木都市計画課長","answer":"補助第２９号線の用地取得率、これは令和２年４月現在になりますが、補助第２９号線は６区間に分けられておりますが、全体の平均としては、４月１日時点で２１％、放射第２号線の用地取得率が３２％です。","voiceIndex":353,"id":"exchange-150"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり住民が反対していますから、全然進んでいないということと、６０２億円と２２６億円、膨大な税金だということです。伺いますけれども、コロナ禍という社会情勢の変化に鑑み、事業を中止して速やかに廃止するよう都に求め、住民要望実現のために活用するべきではないでしょうか。区長に伺いたかったのですが、区長はいないので、ぜひ責任ある方がご答弁いただければと考えています。","respondent":"鈴木都市計画課長","answer":"これは特定整備路線と一緒に、周辺の耐震化、不燃化、区が行っている事業とセットで重層的に行っていく必要があると。これはコロナ禍においても立ち止まらずに、しっかりこの取組は進めていかなければいけないという認識です。","voiceIndex":355,"id":"exchange-151"},{"speaker":"安藤委員","kind":"質問","question":"そう言いますけれども、私は膨大な税金と時間と労力をかけ、今いる人を追い出す。南北の延焼遮断道路を整備、防災を強調しますけれども、風が東西に吹けば、また同時発火すれば何の意味もない道路です。火の粉や車両閉鎖の可能性も考慮にそもそも入っていない。区は、道路反対、そして税金の使い方を変えろという粘り強い区民の皆さんの声をどう受け止めているのでしょうか。伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"区としては、東京都と一緒に重層的に防災性の向上、地震に対する備えをしっかり取り組んでいきたいです。","voiceIndex":357,"id":"exchange-152"},{"speaker":"安藤委員","kind":"提案","question":"次にいきます。ワークショップでの住民の意見はできる限り反映していただきたいわけですが、人数的に限界もありまして、人選する町会もなかなか一苦労なのではないかと、コミュニティバスに強い関心をお持ちで、そういう意見を言える方を選出するのはなかなか苦労しているのではないかと思うのですけれども、この場でも、私が地元の地域から伺っているルート案、以前の提案について何点か伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"コミュニティバスについて、まず大崎ルートですが、大崎ルートにつきましては、導入効果の高い区域は、先ほどからご説明しておりますが、１１の指標を用いて地域の選定、さらには、ルート選定にあたっての７つの視点ということも決めて行ってあります。","voiceIndex":359,"id":"exchange-153"},{"speaker":"安藤委員","kind":"質問・要望","question":"併せて質問してしまいます。２点目が、新しいルートですけれども、例えば区が認定している交通不便地域でありながら、上大崎がルート候補から外れているのですけれども、これはやっぱり強い要望があるのです。途中で池田山公園とか、上大崎なども通るというルートも、具体的な要望として伺っているのですが、こういうルートを検討していただきたいのですが、いかがでしょうかというのが２点目です。","respondent":"鈴木都市計画課長","answer":"これ、先ほど来、ご説明している１１項目の指標の中の重み付けを２倍にして重点的に検討を行っている指標の１つなのですが、やはりその遠い地域も面積が大きいところ、小さいところ様々でございまして、決して上大崎ルートも点数を付けて効果的な地域を選出するにあたって。","voiceIndex":362,"id":"exchange-154"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ住民の声を取り入れ、１日も早く区民に便利なコミュニティバスの運行を実現していただきたいと思います。区は当該地区について、３名くらいの未同意はやむを得ないという認識なのでしょうか。伺いたいと思います。１００％同意までは認可しないよう都に働きかけるよう求めますが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"これまでも準備組合の中では権利者の皆様とよくお話合いをしながらここまで続けてきたところもありますので、法令の規定も踏まえて、今回の申請に至ったという受け止めで、区としてもそういう受け止めで計画的なまちづくりということで進めていきたいと考えているところです。","voiceIndex":364,"id":"exchange-155"},{"speaker":"たけうち委員","kind":"確認","question":"３０７ページの有料自転車等駐車場運営費、また同じページのシェアサイクル事業、３２３ページの不燃化１０年プロジェクト、３４７ページの避難所管理費について伺います。それから、不燃化１０年プロジェクトについては、いろいろ質疑があって確認ですけれども、東京都は延長していくとなっていますが、品川区では、９地区は継続、それから新しい地域も含めて東京都に申請を出している。","respondent":"川口交通安全担当課長、稲田土木管理課長、中島防災課長、佐藤木密整備推進課長","answer":"下神明駅周辺には、確かにおっしゃるとおりそういうものがございませんので、今後もシェアサイクルポート。職員にヒアリングなどを行いまして、やはり災害対策本部の運営、あるいは避難施設の周知、避難場所の運営要領などが課題ということで。それを受けまして、品川区といたしましては、現行の整備地区および新しい地域も視野に入れまして。","voiceIndex":367,"id":"exchange-156"},{"speaker":"たけうち委員","kind":"質問・要望","question":"使っていない部分をどう有効活用できるのかという視点で考えてもらいたいと。東京都の土地なので、そことの調整も要るのだと思いますけれども、これは要望にします。不燃化１０年プロジェクトについては、そろそろ東京都からも返事がないと、やっぱり地域でも、多分皆さん、いつ終わるのでしょうかと、本当だと今年度末なのですね。これはぜひお願いしたいので、ここはもう１回答弁をいただきたいと思います。","respondent":"佐藤木密整備推進課長、中島防災課長","answer":"令和３年度以降の不燃化特区の件ですが、委員ご指摘のとおり、我々も窓口等で来年度以降どうなるのかというお問合せを受けておりまして、東京都のほうにもそういった実態を含めて申入れをしておりますので、地区が決定次第。風水害の避難行動の訓練、検討していたところも新型コロナウイルス感染症の関係で少し滞っている部分もありますが、課題認識として持っておりますので、引き続き調整してまいります。","voiceIndex":372,"id":"exchange-157"},{"speaker":"たけうち委員","kind":"質問・要望","question":"不燃化１０年プロジェクトのほうは、我々も我々の立場で東京都にぜひ早く返事をくれということでやってまいりたいと思いますので、ぜひ積極的に頑張っていただきたいと要望します。これも要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":375,"id":"exchange-158"},{"speaker":"大沢委員","kind":"質問・要望","question":"３４７ページ、避難所について伺いたいと思います。冗談はさておいて、３４７ページの避難所からお伺いさせていただきたいと思いますけれども、いろいろと調べて、事務事業概要等々も見せていただいたのですが、内部障害者、オストメイトの方の避難所における対策、対応は、どのように行われているのか教えていただきたい。","respondent":"平原防災体制整備担当課長","answer":"一部そのような施設がないようなところもありますけれども、それに対応した仮設のものになってしまうのですが、それで今、代用させていただいているところです。こちらはトイレの状況になりますけれども、こういったような形で現在対応させていただいているような状況になります。","voiceIndex":377,"id":"exchange-159"},{"speaker":"大沢委員","kind":"質問","question":"だれでもトイレということで、ストーマを洗う部分のところということで心得ておりますけれども、ストーマ装具等々の備蓄はされているのですか。","respondent":"平原防災体制整備担当課長","answer":"こちらにつきましては、学校設備ということもございまして、学校の備蓄品といいましょうか、通常の備品を活用するということになっておりまして、現状では災害用備蓄品として、だれでもトイレ用のものを準備しているものはございません。","voiceIndex":379,"id":"exchange-160"},{"speaker":"大沢委員","kind":"意見","question":"「ございません」とはっきりおっしゃいましたけれども、やはり内部障害の方はなかなか障害をお持ちだということが、手帳は持っていらっしゃるけれども、なかなかお困りのことは多かろうと思いますし、ましてや腸とか膀胱の罹患が非常に高かろう、成人病としては多いところだと思うのですけれども、そこのところでやはり用意しておく必要が私は多くあると思いますし、やっぱり性質上。","respondent":"平原防災体制整備担当課長","answer":"例えば区民避難所なのか、福祉避難所なのか等々、いろいろなことを検討させていただきながら、そういったものの配備を進めていきたいというふうに考えてあります。","voiceIndex":381,"id":"exchange-161"},{"speaker":"大沢委員","kind":"提案","question":"そこで１つ提案なのですけれども、内部障害者向けのポータブルのトイレ、これは普及というか、近年出始めております。これで３４７ページの質問については終わります。国なのでそうそう区は手をつけられるという問題ではないとは思うのですけれども、そこのところをどういうふうにお考えになっていらっしゃるか教えてください。","respondent":"高梨公園課長","answer":"今、委員お尋ねのとおり、林試の森公園は区内の貴重な緑を生み出す場所ということで、区としても認識しています。特に緑の少ない荏原地区にとっては、貴重な緑であるというふうに感じております。","voiceIndex":383,"id":"exchange-162"},{"speaker":"大沢委員","kind":"質問・要望","question":"自転車の事故もということなのですけれども、やはりコロナ禍ということで、最近、多く見るのが、宅配の自転車業者の方、あの方たちは時間に追われている部分もあるのですけれども、意外と交通ルールに、先ほどもルールなのかマナーなのかと藤原委員からもありましたけれども、怖い運転をされていて、ヒヤリとするようなところもあるのですけれども、その宅配業者の方たちに対する安全教育というか。","respondent":"川口交通安全担当課長","answer":"これにつきましては、今、シェアサイクルの担当者が、他区、同じ実施をしている区の会議が定期的にありますので、その中で事業者に対してしっかりそういう指導も併せてやってもらいたいという要請を区からもしています。","voiceIndex":385,"id":"exchange-163"},{"speaker":"大沢委員","kind":"質問・要望","question":"交通安全について業者の方たちに伝えていただきたいと考えています。先ほど来、「交通安全」という言葉が出ていますが、ここに表記をしてある「交通安全計画」とありますけれども、私は「交通安全」というのは、どうもあまり解せない言葉で、「交通安全計画」ではなくて、「交通安全化計画」ではないのでしょうか。","respondent":"川口交通安全担当課長","answer":"ちなみに、参考ですけれども、いわゆる交通切符を適用した自転車の取締り、赤切符で取締りをされた件数が、平成３０年には１,５６３件であったものが、令和元年は１,９６０件ということで。","voiceIndex":387,"id":"exchange-164"},{"speaker":"大沢委員","kind":"質問","question":"そうなると、やはり標語、スローガンは交通安全でもいいのですけれども、ここのところを一ひねり、二ひねり変えて、「交通安全化運動」、交通の安全に対する何とかというふうに変えていただいて、交通の安全と言っても、交通安全というのは何がなんだか意味をつかみかねるのですけれども、そこのところをどういうふうにお感じになられますでしょうか。","respondent":"川口交通安全担当課長","answer":"委員ご指摘の「交通安全化」なのではないかですけれども、我々は１つの名詞的に「交通安全」と申し上げておりますけれども、やはり「交通安全」の中には、それぞれ、例えば交通の円滑化を図ることによる交通安全もありますし、交通の障害に基づいて。","voiceIndex":389,"id":"exchange-165"},{"speaker":"大沢委員","kind":"質問","question":"これは東京都の警視庁なり、あるいは上の役所から出た言葉なので、私ごときが言っても、どうにも変わる問題ではないのですけれども、やはり交通安全という交通に対する安全性をかもし出すには、やはり表現を変える必要はあるのではないか。もうちょっと交通に対する危機感を持ってもらえるような表現に変える必要があるのではないかと私は思いまして、この質問をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":391,"id":"exchange-166"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、３３３ページ、しながわ水族館、それから３２４ページ、都市開発費の中で京急連続立体化とか、品川駅南地域、大井町駅周辺関係に触れたいと思っています。初めに伺いたいのは、今、品川区は都市型観光といろいろ言っています。集客が必ず必要だと。なぜこのようなことを言うかというと、例えば台東区、今、台東区に来る方は、来客数６,０００万人だと言われています。これも１つの仕掛けなわけです。","respondent":"高梨公園課長","answer":"都市型観光、集客についてのご質問ですが、水族館という切り口でお答えします。しながわ水族館は、品川区を代表する観光施設であると考えておりますが、開館から来年で３０周年を迎えるということと、周辺に大分水族館が３０年前に比べて多くできました。","voiceIndex":393,"id":"exchange-167"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"シンボル的なしながわ水族館になっていただきたいと考えていますけれども、その中で何点か話をさせていただきたいのは、現在の管理許可制度、これに基づく基本協定、これはやっぱり見直すということは非常に考えてほしいというのが１点。それは近隣の方の話もよく分かっていますけれども、それぐらいのことも含めて検討していただきたいと思うので、水族館のところはもう１回お答えいただきたいと思います。","respondent":"高梨公園課長","answer":"営業時間のご提案につきましては、委員からもありました周辺の住居等との関係もありますが、３０年経ってきたといったところもありますので、そういったところを既存の考え方にとらわれないで、また周辺の方々ともお話合いをしながら検討を進めていきたい。","voiceIndex":395,"id":"exchange-168"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"決定をして、今、買収行為もスタートしていくということでありますけれども、必ず高架があるので高架下、それから駅舎のデザイン、それから駅前広場、地域の方からも意見を聞いて、いろいろパースを引いていただくということにこれからなっていくのだろうと思っていますけれども、ぜひそのときに、いろいろ考えていただきたいのは、地域の人としては、もう決まっていて、南地域と連動してくるとなると。","respondent":"中道まちづくり立体化担当課長","answer":"今お話のございましたゴジラの点につきましては、品川区で旧東海道、八ツ山といったところで登場したといったところで、非常に北品川に関係の深いキャラクターであり、また幅広い方に親しまれているキャラクターというところで、非常に魅力あるキャラクターですが、その一方で。","voiceIndex":397,"id":"exchange-169"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"確かに地域でも、上陸して八ツ山を踏みつけて壊してしまった、まちを破壊したのはゴジラだという意見もあるのは事実でありますけれども、やっぱりそれはそれで１つの考え方もあるので、ぜひ考えていただきたいと思います。では、あそこは品川駅から１０分圏内だけれども、そこにテナントがあったから入るのか、それがずっと後々になってどういう状況になるのだということも考える。そこは一段超えると。","respondent":"中道まちづくり立体化担当課長","answer":"そうした東京都の敷地に対しましては、区が間に入りまして課題を解決していくとともに、やはり品川浦といったところで船宿等の観光施設がありますので、そういった活用も地域と一緒に考えていきたいと思います。","voiceIndex":399,"id":"exchange-170"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1492#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":123969,"voices":401}}]);
